/* ÇEVİRİ ar · olay — arac/ceviri.py ile YAZILDI, elle düzenleme: py arac/ceviri.py uygula.
   Kayıt: id → [metin, kaynak_ozet] (olayda alan başına). Tasarım: denetim/CEVIRI-1103/TASARIM.md */
Ceviri.ekle("ar","olay",{
"OLAYLAR_EK7:1555-09-29:0":{"b": ["إعدام قره أحمد باشا وعودة رستم باشا صدرًا أعظم", "9a85076a"], "d": ["وفقًا لمادتي رستم باشا وقره أحمد باشا في موسوعة الإسلام التركية (TDV)، عُيّن رستم باشا في اليوم نفسه صدرًا أعظم للمرة الثانية بدعم من السلطانتين خرّم ومهرماه، خلفًا لقره أحمد باشا الذي أُعدم فجأة أثناء اجتماع الديوان في 13 ذي القعدة 962 (29 سبتمبر 1555). وتركت المصادر كواليس الواقعة غير واضحة، وقُدّرت بأنها نتيجة لدسائس داخل القصر.", "54f3fd71"]},
"OLAYLAR_EK7:1558-04-15:0":{"b": ["وفاة خرّم سلطان", "1ae998b5"], "d": ["وفقًا لمادة خرّم سلطان في موسوعة الإسلام التركية (TDV)، توفيت خرّم سلطان، التي كانت لسنوات طويلة صاحبة نفوذ كبير داخل القصر بوصفها خاصكي سلطان القانوني، في إسطنبول في 26 جمادى الآخرة 965 (15 أبريل 1558)، ودُفنت في ضريحها بمجمع جامع السليمانية. وبوفاة خرّم سلطان، التي كانت قد ثبّتت سلطتها على الحريم بعد وفاة الوالدة سلطان حفصة عام 1534، زال كذلك الأثر الموازن الذي كان يقف أمام التنافس على العرش بين ولديها بايزيد وسليم.", "d8c41dae"]},
"OLAYLAR_EK7:1565-06-29:0":{"b": ["ارتقاء صوقوللو محمد باشا إلى الصدارة العظمى", "896391a2"], "d": ["وفقًا لمادة صوقوللو محمد باشا في موسوعة الإسلام التركية (TDV)، ارتقى صوقوللو محمد باشا إلى الصدارة العظمى إثر وفاة سميز علي باشا في 30 ذي القعدة 972 (29 يونيو 1565)، وكان آخر صدور القانوني العظام، واستمر في هذا المنصب بعده في عهدي سليم الثاني ومراد الثالث، فصار من أطول الوزراء العظام خدمةً في التاريخ العثماني.", "dfe55e0b"]},
"OLAYLAR_EK7:1566-09-24:0":{"b": ["وصول سليم الثاني إلى إسطنبول وجلوسه على العرش", "0289ef97"], "d": ["بعد وفاة السلطان سليمان القانوني في زيغتفار، أبقى صوقوللو محمد باشا الخبر سرًا أسابيع حفاظًا على النظام. ووفقًا لموسوعة الإسلام التركية (TDV)، يذكر سلانيكي أن تاريخ وصول سليم إلى إسطنبول هو 15 ربيع الأول 974 (30 سبتمبر 1566)، بينما يرى معظم المؤرخين المعاصرين أن الصحيح هو 9 ربيع الأول (24 سبتمبر). ولم تُعلن وفاة القانوني رسميًا في بلغراد إلا في 24-25 أكتوبر 1566.", "66da7cdb"]},
"OLAYLAR_EK7:1572-06-13:0":{"b": ["نزول الأسطول الذي أعاد قلج علي باشا بناءه إلى البحر", "d0fc9f48"], "d": ["بعد الهزيمة الثقيلة في إينه بختي (7 أكتوبر 1571) بُنيت السفن في الترسانات طوال الشتاء. ووفقًا لموسوعة الإسلام التركية (TDV)، أُنزل الأسطول الجديد المؤلف من 250 قادسًا ونحو 300 سفينة جكتري من سفن الرياس المتطوعين إلى البحر في استعراض للقوة في 1 صفر 980 (13 يونيو 1572).", "33415db2"]},
"OLAYLAR_EK7:1579-10-12:0":{"b": ["اغتيال صوقوللو محمد باشا", "6ffa8dec"], "d": ["قُتل صوقوللو محمد باشا، الذي تولى الصدارة العظمى أربع عشرة سنة في عهد ثلاثة سلاطين، طعنًا بخنجر على يد درويش اقترب منه كأنه يريد تقديم عريضة إلى ديوان العصر في قصره، في 20 شعبان 987 (12 أكتوبر 1579). ووفقًا لموسوعة الإسلام التركية (TDV)، يُناقَش أن يكون الاغتيال متصلًا بالانتقام لشيخ الحمزوية حمزة بالي الذي نُفّذ فيه حكم الإعدام.", "b1355377"]},
"OLAYLAR_EK7:1580-01-01:0":{"b": ["أول عهدنامة تجارية مع إنجلترا — منح الإنجليز الامتيازات", "59c8e3ee"], "d": ["حصل المبعوث الإنجليزي وليم هاربورن، الذي أُرسل إلى إسطنبول في أكتوبر 1578، بدعم من صوقوللو محمد باشا وخوجه سعد الدين أفندي، على عهدنامة مؤرخة في عام 1580 من مراد الثالث. وبموجب هذه العهدنامة نال التجار الإنجليز حق الانتفاع بالقدر نفسه من الامتيازات التجارية (الكابيتولاسيون) التي كانت قد مُنحت من قبل للفرنسيين والبنادقة. وتبودلت الرسائل بين الملكة إليزابيث الأولى ومراد الثالث، وأُقيمت علاقة رسمية بين الدولتين. وعقب هذه الامتيازات مباشرة تأسست في لندن عام 1581 شركة الليفانت؛ وأدار الإنجليز تجارتهم في المنطقة عبر هذه الشركة حتى عام 1825.", "c25734eb"]},
"OLAYLAR_EK7:1580-01-22:0":{"b": ["هدم مرصد إسطنبول بخط همايوني", "3bc0c78c"], "d": ["تحت تأثير فتوى بأن المراصد تجلب الشؤم على البلاد ومعارضة داخل القصر، هُدم مرصد إسطنبول بجميع آلاته بموجب خط همايوني مؤرخ في 4 ذي الحجة 987 (22 يناير 1580). ووفقًا لموسوعة الإسلام التركية (TDV)، كانت هذه نهاية قصيرة العمر للمؤسسة التي أسسها تقي الدين الراصد.", "7b4f41fe"]},
"OLAYLAR_EK7:1582-05-29:0":{"b": ["بدء حفل ختان الأمير محمد في أت ميداني", "c2926d5d"], "d": ["خُتن الأمير محمد، ابن مراد الثالث، في احتفالات فخمة بدأت في 6 جمادى الأولى 990 (29 مايو 1582) واستمرت ستة وخمسين أو سبعة وخمسين يومًا. ووفقًا لموسوعة الإسلام التركية (TDV)، كانت الاحتفالات التي أُقيمت في أت ميداني من أروع احتفالات القصر في عصرها.", "eaf7772a"]},
"OLAYLAR_EK7:1583-12-07:0":{"b": ["وفاة نوربانو والدة سلطان", "77d0a577"], "d": ["توفيت نوربانو سلطان، والدة مراد الثالث، في 22 ذي القعدة 991 (7 ديسمبر 1583). ووفقًا لموسوعة الإسلام التركية (TDV)، أجرت بوصفها والدة سلطان مراسلات مع بلاطي البندقية وفرنسا، وكان مجلس الشيوخ البندقي قد قبل في العام نفسه أن يرسل إليها هدية بقيمة 2000 دوقية ذهبية بندقية مقابل خدماتها.", "56b04854"]},
"OLAYLAR_EK7:1589-06-01:0":{"b": ["اندلاع وقعة بكلربكي بسبب الأقجة المغشوشة", "db2f2e61"], "d": ["لما دفعت الدولة الرواتب بأقجة خُفضت نسبة الفضة فيها، حاصر السباهية والإنكشارية القصر وأثاروا تمردًا دمويًا دخل التاريخ باسم وقعة بكلربكي. ووفقًا لمادة عبد القادر شيخي أفندي في موسوعة الإسلام التركية (TDV)، عُزل شيخ الإسلام من منصبه بسبب هذه الواقعة.", "b1db5aea"]},
"OLAYLAR_EK7:1595-01-27:0":{"b": ["جلوس محمد الثالث على العرش وخنق تسعة عشر أميرًا", "2cd9a8c5"], "d": ["وصل محمد الثالث إلى إسطنبول يوم الجمعة 16 جمادى الأولى 1003 (27 يناير 1595) إثر وفاة أبيه مراد الثالث، وتولى العرش. ووفقًا لموسوعة الإسلام التركية (TDV)، خُنق في الليلة نفسها تسعة عشر أميرًا، أربعة منهم بالغون (مصطفى وبايزيد وعثمان وعبد الله)؛ وكانت هذه أكبر مجزرة للإخوة في التاريخ العثماني.", "fee571d5"]},
"OLAYLAR_EK7:1595-02-01:0":{"b": ["ازدياد نفوذ صفية سلطان بوصفها والدة سلطان", "000bec21"], "d": ["ارتقت صفية سلطان، زوجة مراد الثالث ووالدة محمد الثالث، بجلوس ابنها إلى مكانة حاسمة في سياسة القصر بصفتها والدة سلطان. ووفقًا لموسوعة الإسلام التركية (TDV)، بلغ النفوذ الصادر عن الحريم في هذه الفترة حد التدخل المباشر في شؤون الدولة.", "dcf5f731"]},
"OLAYLAR_EK7:1596-06-20:0":{"b": ["خروج محمد الثالث بنفسه إلى الحملة بضغط من الإنكشارية", "d3c50656"], "d": ["رغم معارضة الصدر الأعظم داماد إبراهيم باشا، وبضغط من الإنكشارية، خرج محمد الثالث من إسطنبول إلى الحملة في 20 يونيو 1596، وهو أول سلطان يتولى قيادة الجيش بنفسه بعد السلطان سليمان القانوني. ووفقًا لموسوعة الإسلام التركية (TDV)، كان ذلك يعني إحياء تقليد الغزو القديم.", "396dc19b"]},
"OLAYLAR_EK7:1600-06-01:0":{"b": ["استمرار وباء الطاعون الذي بدأ في عقد 1570 في التأثير في إسطنبول", "eb4ca37a"], "d": ["وفقًا لمادة الطاعون في موسوعة الإسلام التركية (TDV)، استمر الوباء الذي بدأ في عقد 1570 في أثره حتى أوائل القرن 17، وضرب إسطنبول أولًا ثم الأناضول والبلقان ومصر وشمال أفريقيا. وكانت فترات الوباء تشكّل تهديدًا مزمنًا يقطع حياة القصر والمدينة مرارًا.", "3afd5ea1"]},
"OLAYLAR_EK7:1602-02-15:0":{"b": ["وفاة قره يازيجي عبد الحليم وضعف حركة التمرد", "876ca7a6"], "d": ["توفي قره يازيجي عبد الحليم، الذي انسحب جريحًا بعد هزيمته الثقيلة في سبتلي قرب أبلستين في 12 أغسطس 1601، في سنة 1010 (1602). ووفقًا لموسوعة الإسلام التركية (TDV)، بلغ نبأ وفاته إسطنبول في رمضان 1010 (فبراير-مارس 1602)؛ وتذكر المصادر أن كون موته ناتجًا عن جراحه أم على يد رجاله أمر مختلف فيه.", "f9c28a0d"]},
"OLAYLAR_EK7:1603-12-23:0":{"b": ["الانتهاء الفعلي لتقليد قتل الإخوة", "9046c607"], "d": ["لم يأمر أحمد الأول عند جلوسه على العرش بقتل أخيه الأمير مصطفى، خلافًا للسلاطين السابقين، بل عفا عنه؛ ويُعدّ هذا القرار بداية الأخذ الفعلي بنظام الأكبر والأرشد في الوراثة العثمانية. وتنقل مادة «مصطفى الأول» في موسوعة الإسلام التركية (TDV) أن مصطفى ظل بعد هذا التاريخ يعيش حياة المحفل في القصر. وبذلك وضع هذا التطبيق نهاية فعلية لجرائم الجلوس التي استمرت قرونًا.", "7734428a"]},
"OLAYLAR_EK7:1609-08-09:0":{"b": ["وضع حجر أساس جامع السلطان أحمد", "1683262f"], "d": ["بأمر أحمد الأول، وُضع حجر أساس الجامع الذي سيبنيه المعمار صدفكار محمد آغا، في أت ميداني بحفل. ووفقًا لمادة «جامع السلطان أحمد ومجمعه» في موسوعة الإسلام التركية (TDV)، كان البناء، بوصفه أول جامع سلطاني كبير يُشيَّد مباشرة من الخزينة دون انتصار في فتح، موضع انتقادات في عصره أيضًا. وصُمّم المجمع بحيث يشمل مع الجامع مدرسة وعمارة وضريحًا.", "2605235a"]},
"OLAYLAR_EK7:1622-05-20:0":{"b": ["قتل عثمان الشاب على يد الإنكشارية (الفاجعة العثمانية)", "324f6582"], "d": ["ثار الإنكشارية والسباهية إثر شائعات بأنه يخطط للخروج من إسطنبول بذريعة الحج وحلّ أوجاق الإنكشارية، فخلعوا عثمان الثاني عن العرش وخنقوه في سجون يدي قولة. ووفقًا لمادة «عثمان الثاني» في موسوعة الإسلام التركية (TDV)، كانت هذه الواقعة أول حالة في التاريخ العثماني يُقتل فيها سلطان صراحةً بتمرد عسكري، وأحدثت صدعًا عميقًا في علاقة الأسرة الحاكمة بالجيش. وكانت ساعاته الأخيرة على النحو الآتي: لما لم تُجدِ محاولته اللجوء إلى قصر آغا الإنكشارية علي آغا، أُركب السلطان على فرس، وبحسب تعبير TDV «في حال فظيعة، مكشوف الرأس، مضطرب الثياب»، وسط إهانات شديدة، فسيق أولًا إلى الجامع الأوسط حيث كان مصطفى الأول، ثم بعد ظهر اليوم نفسه إلى يدي قولة؛ وبحسب بعض المؤرخين قُطعت أذنه وأنفه لإثبات موته وعُرضتا على والدة مصطفى الأول. وبعد الواقعة أُعيد مصطفى الأول إلى العرش للمرة الثانية. وقد أخلّت الواقعة المعروفة بـ«الفاجعة العثمانية» (مأساة عثمان) بالتوازن بين القصر والأوجاق إخلالًا دائمًا، وأطلقت جدلًا حول الشرعية سيستمر طوال قرن.", "cf706a0a"]},
"OLAYLAR_EK7:1622-05-20:1":{"b": ["إعادة مصطفى الأول إلى العرش للمرة الثانية", "34a0b29a"], "d": ["بعد قتل الإنكشارية لعثمان الشاب، أُعيد مصطفى الأول إلى العرش للمرة الثانية، إذ لم يكن في الأسرة الحاكمة عضو ذكر بالغ آخر. ووفقًا لمادة «مصطفى الأول» في موسوعة الإسلام التركية (TDV)، مرت هذه السلطنة الثانية أيضًا، كالأولى، دون أن يتمكن من تسيير شؤون الدولة فعليًا، وبقيت إدارة الدولة في أيدي الوزراء والوالدة سلطان. وانتهت هذه الفترة التي دامت أربعة عشر شهرًا بجلوس مراد الرابع على العرش عام 1623.", "0fb39afd"]},
"OLAYLAR_EK7:1633-09-01:0":{"b": ["حريق جبالي", "3e42fb08"], "d": ["أتى الحريق الذي اندلع في جبالي وانتشر بسرعة بتأثير الريح على جزء كبير من إسطنبول؛ ووفقًا لمادة «إسطنبول» في موسوعة الإسلام التركية (TDV)، تنقل مصادر العصر أن آلاف البيوت احترقت. وكان ربط الحريق بنسيج البيوت الخشبية وبتدخين التبغ السبب المباشر للحظر الصارم للتبغ والمقاهي الذي سيعلنه مراد الرابع بعد وقت قصير. وكانت الكارثة واحدة فحسب من الحرائق الكبرى المتكررة في إسطنبول ذلك العصر.", "580b710f"]},
"OLAYLAR_EK7:1633-10-01:0":{"b": ["حظر مراد الرابع للتبغ والمقاهي", "5dd71297"], "d": ["بعد حريق جبالي، حظر مراد الرابع تدخين التبغ والمقاهي حرصًا على الأمن ومنعًا للحرائق؛ وطُبقت على المخالفين عقوبات شديدة منها عقوبة الإعدام. ووفقًا لمادة «مراد الرابع» في موسوعة الإسلام التركية (TDV)، انتهج السلطان سياسة انضباط داخلي صارمة بلغت حد أنه كان يجول بنفسه في شوارع المدينة متنكرًا لمراقبة تطبيق الحظر. وتُعدّ هذه التدابير القاسية جزءًا من سعي مراد الرابع إلى إعادة تأسيس السلطة المركزية.", "cc3ae964"]},
"OLAYLAR_EK7:1637-01-01:0":{"b": ["وباء الطاعون في إسطنبول", "f33f58c5"], "d": ["هزّ إسطنبول في عهد مراد الرابع وباء طاعون شديد أصاب جزءًا مهمًا من السكان؛ وتعطلت التجارة داخل المدينة والحياة اليومية أشهرًا. وتسجل مادة «إسطنبول» في موسوعة الإسلام التركية (TDV) أن الأوبئة المتكررة في القرن 17 أثرت تأثيرًا جسيمًا في التوازن السكاني للمدينة. وفي فترة الوباء انتقل القصر والطبقة النخبوية إلى البساتين والأجنحة خارج المدينة لبعض الوقت.", "2dc59aee"]},
"OLAYLAR_EK7:1638-06-01:0":{"b": ["طيران هزارفن أحمد جلبي بالجناحين (رواية)", "df474c04"], "d": ["وفقًا للرواية التي ينقلها أوليا جلبي، تمكن هزارفن أحمد جلبي بجناحين صنعهما بنفسه من القفز من برج غلطة والانزلاق حتى أسكدار؛ ومع أن ثبوته التاريخي موضع جدل، فقد صار رمزًا للخيال التقني. وقد نفى السلطان هزارفن، الذي كان قد كافأه في البداية، إلى الجزائر لاحقًا بسبب الصدى الذي أحدثته الواقعة.", "f1671c60"]},
"OLAYLAR_EK7:1642-01-01:0":{"b": ["اكتساب جنجي خوجه حسين أفندي النفوذ في القصر", "41d21572"], "d": ["استُدعي الراقي حسين أفندي إلى القصر لمعالجة الاضطرابات النفسية لدى السلطان إبراهيم، فكسب ثقة السلطان في وقت قصير وارتقى حتى منصب قاضي عسكر الأناضول. ووفقًا لمادة «حسين أفندي، جنجي خوجه» في موسوعة الإسلام التركية (TDV)، استخدم هذا النفوذ لجمع الثروة والتدخل في الأحداث السياسية في عصره. وبعد وفاة إبراهيم عُزل من جميع مناصبه وأُعدم عام 1648.", "af40c3d4"]},
"OLAYLAR_EK7:1644-01-31:0":{"b": ["إعدام كمانكش مصطفى باشا", "0ecc8030"], "d": ["خُنق كمانكش مصطفى باشا، الذي تولى الصدارة العظمى منذ عهد مراد الرابع وحقق للخزينة فائضًا مهمًا بإصلاحاته المالية، وأُعدم إثر تأثير خصومه داخل القصر في إبراهيم واتهامه بإثارة تمرد للإنكشارية. ووفقًا لمادة «كمانكش مصطفى باشا» في موسوعة الإسلام التركية (TDV)، نُفّذ إعدامه في 21 ذي القعدة 1053 / 31 يناير 1644: خنقه الجلاد قره علي في سوق خوجه باشا، ودُفن في ضريحه الذي أنشأه لنفسه في جارشي قابي. ويُذكر موته مثالًا لافتًا على عدم الاستقرار في منصب الصدارة العظمى في ذلك العصر، وقد أنهى فترة إصلاح صارمة قصيرة.", "9ae1d459"]},
"OLAYLAR_EK7:1645-04-01:0":{"b": ["قرار الديوان بحملة كريت وخروج الأسطول", "9076827e"], "d": ["تقرر في ديوان همايون فتح حملة واسعة النطاق على جزيرة كريت التابعة للبندقية، وتحرك الأسطول العثماني بقيادة قبطان باشا من إسطنبول نحو كريت. ووفقًا لمادة «كريت» في موسوعة الإسلام التركية (TDV)، شكّل هذا القرار البداية السياسية لمرحلة طويلة من الحصار والحرب ستدوم نحو خمس وعشرين سنة. وكان فتح الحملة قد أثار جدلًا واسعًا بين رجال الدولة بوصفه أكبر مبادرة في السياسة الخارجية في عهد إبراهيم.", "da4feb76"]},
"OLAYLAR_EK7:1648-08-08:0":{"b": ["جلوس محمد الرابع على العرش في السابعة من عمره", "a197a3bc"], "d": ["عقب خلع إبراهيم مباشرة، أُجلس ابنه محمد، وهو في السابعة من عمره، على العرش، فصار سلطانًا بلقب محمد الرابع. ووفقًا لمادة «محمد الرابع» في موسوعة الإسلام التركية (TDV)، أدى الجلوس على العرش في هذه السن المبكرة إلى احتدام الصراع على النفوذ داخل القصر بين جدته كوسم سلطان وأمه تورهان سلطان. وسينتهي هذا الصراع على السلطة بقتل كوسم سلطان عام 1651.", "aa8955d5"]},
"OLAYLAR_EK7:1652-06-20:0":{"b": ["إصلاح الميزانية المتوازنة على يد طرخونجو أحمد باشا", "376fc7f2"], "d": ["طبّق الصدر الأعظم طرخونجو أحمد باشا، للتغلب على الأزمة المالية التي سببتها سنوات الحرب الطويلة، برنامج تقشف صارمًا شمل نفقات القصر أيضًا، وأعد أول ميزانية متوازنة معروفة في التاريخ العثماني (لائحة طرخونجو). ووفقًا لمادة «طرخونجو أحمد باشا» في موسوعة الإسلام التركية (TDV)، حقق هذا الإصلاح فائضًا مهمًا للخزينة، لكنه أثار استياءً واسعًا في أوساط القصر والبيروقراطية العليا. وسيفضي هذا الاستياء بعد عام إلى إعدامه.", "c837950b"]},
"OLAYLAR_EK7:1656-03-04:0":{"b": ["واقعة الجنار (الوقعة الواقواقية)", "4c6ed90f"], "d": ["وفقًا لمادة «واقعة الجنار» في موسوعة الإسلام التركية (TDV)، ثار الإنكشارية والسباهية العائدون من حملة كريت دون أن يتقاضوا رواتبهم في إسطنبول، وطالبوا بإعدام رجال الدولة الذين اتهموهم بالفساد. ولم يُقبل اقتراح الصدر الأعظم زورنازن مصطفى باشا بالمصادرة والنفي؛ فأُعدم ثلاثة مسؤولين أولًا، ثم نحو ثلاثين من رجال الدولة، وعُلّقت جثثهم على أشجار الجنار في ميدان السلطان أحمد. ولذلك عُرفت الواقعة باسم واقعة الجنار.", "f187180a"]},
"OLAYLAR_EK7:1656-09-15:0":{"b": ["تعيين كوبريلي محمد باشا صدرًا أعظم بقبول مشروط", "3a6b7f8f"], "d": ["وفقًا لمادة كوبريلي محمد باشا في موسوعة الإسلام التركية (TDV)، لم يتسلم كوبريلي محمد باشا، وقد قارب الثمانين من العمر، الختم إلا بعد أن حمل الوالدة تورهان سلطان ومحمدًا الرابع على قبول الشروط الثقيلة التي قدمها — وهي عدم التدخل في تعييناته وعدم تصديق ما يُقال ضده. وباشر مهامه في 26 ذي القعدة 1066 خلفًا لبويون أغري محمد باشا، وشرع في إعادة تأسيس انضباط الدولة بشدة.", "066ec089"]},
"OLAYLAR_EK7:1656-10-01:0":{"b": ["قمع كوبريلي محمد باشا لحركة القاضي زاديين", "5ec3ce84"], "d": ["وفقًا لمادة «القاضي زاديون» في موسوعة الإسلام التركية (TDV)، تناول كوبريلي محمد باشا فور تسلمه مهامه الصراع الديني بين حلقة قاضي زاده محمد أفندي وأهل الطريقة. وبعد استشارة العلماء، صدر فرمان بإعدام زعماء الحركة أوستوفاني محمد أفندي وترك أحمد وديوانه مصطفى، غير أن هذه العقوبة حُوّلت إلى النفي، وأُرسل الثلاثة إلى قبرص؛ وبذلك انتهت المرحلة الثانية من الحركة.", "a6f49f27"]},
"OLAYLAR_EK7:1660-07-15:0":{"b": ["حريق كبير في إسطنبول: احتراق آغا قابي", "b9253b66"], "d": ["وفقًا لمادة آغا قابي في موسوعة الإسلام التركية (TDV)، احترق آغا قابي، المقر الرسمي لآغا الإنكشارية، احتراقًا تامًا في الحريق الكبير الذي اندلع في يوليو 1660 في عهد محمد الرابع، ثم أُعيد بناؤه. وكان هذا الحريق من حرائق المدينة الكبرى التي ضربت إسطنبول ذلك العصر مرارًا.", "f9ae495b"]},
"OLAYLAR_EK7:1661-11-01:0":{"b": ["تعيين كوبريلي زاده فاضل أحمد باشا صدرًا أعظم", "c1999b5c"], "d": ["وفقًا لمادة كوبريلي زاده فاضل أحمد باشا في موسوعة الإسلام التركية (TDV)، عُيّن في الصدارة العظمى في 8 ربيع الأول 1072 (1 نوفمبر 1661) إثر وفاة أبيه كوبريلي محمد باشا. وأنشأ فاضل أحمد باشا، المعروف، خلافًا لأبيه، بلين طبعه وتدينه ورعايته للعلماء والفنانين، خلال صدارته التي تجاوزت خمس عشرة سنة، مكتبات ومؤسسات خيرية في إسطنبول وفي الأراضي المفتوحة.", "25ea9a1e"]},
"OLAYLAR_EK7:1665-06-01:0":{"b": ["تعيين وانلي محمد أفندي واعظًا في الجامع الجديد ومعلمًا للسلطان", "7ea6aaae"], "d": ["وفقًا لمادة محمد أفندي، واني في موسوعة الإسلام التركية (TDV)، استُدعي واني محمد أفندي إلى إسطنبول عند تولي كوبريلي زاده فاضل أحمد باشا الصدارة العظمى، وقُدّم إلى محمد الرابع، فكسب اهتمام السلطان القريب في وقت قصير. وفي عام 1665 عُيّن واعظًا في الجامع الجديد ومعلمًا للسلطان، فصار من أكثر رجال الدين نفوذًا في القصر.", "3b1a8c25"]},
"OLAYLAR_EK7:1676-11-05:0":{"b": ["تعيين قره مصطفى باشا المرزيفوني صدرًا أعظم", "3d1e836c"], "d": ["وفقًا لمادة مرزيفونلو قره مصطفى باشا في موسوعة الإسلام التركية (TDV)، عُيّن في الصدارة العظمى في 28 شعبان 1087 (5 نوفمبر 1676) إثر وفاة فاضل أحمد باشا. وصار المرزيفوني، صهر أسرة كوبريلي وتلميذها وصاحب الخبرة الطويلة في إدارة الدولة، من أقوى صدور محمد الرابع العظام وأكثرهم نفوذًا.", "364f6283"]},
"OLAYLAR_EK7:1685-10-12:0":{"b": ["وفاة وانلي محمد أفندي في المنفى", "cda714aa"], "d": ["وفقًا لمادة محمد أفندي، واني في موسوعة الإسلام التركية (TDV)، أُسقط واني محمد أفندي، الذي يُعدّ من أبرز من حملوا السلطان على قبول حملة فيينا، من مكانته بضغط الرأي العام بعد انتهاء الحملة بهزيمة، ونُفي إلى بلدة كستل في بورصة. وتوفي فيها في 14 ذي القعدة 1096 (12 أكتوبر 1685)، ودُفن عند مدخل الجامع الذي أنشأه.", "d8dc341f"]},
"OLAYLAR_EK7:1689-10-25:0":{"b": ["تعيين كوبريلي زاده فاضل مصطفى باشا صدرًا أعظم وإصلاحاته المالية", "b048570e"], "d": ["وفقًا لمادة كوبريلي زاده فاضل مصطفى باشا في موسوعة الإسلام التركية (TDV)، أعاد فاضل مصطفى باشا، الذي عُيّن في الصدارة العظمى في 11 محرم 1101 (25 أكتوبر 1689)، تنظيم أسلوب جباية الجزية وفق الأسس الشرعية، وكافح تضخم المانغير، وقوّى الخزينة بتحويل موارد من مؤسسات القصر. كما عزز الإدارة في الولايات بموظفين موثوقين وأقام مجالس محلية شبيهة بالديوان المركزي.", "57c6c63d"]},
"OLAYLAR_EK7:1695-01-01:0":{"b": ["بدء العمل بنظام المالكانة", "316b8426"], "d": ["وفقًا لمادة المالكانة في موسوعة الإسلام التركية (TDV)، أدخل ازدياد نفقات الحرب في الربع الأخير من القرن 17 وتناقص الإيرادات بسبب خسائر الأراضي الخزينةَ في أزمة مالية شديدة. وفي نظام المالكانة الذي بدأ العمل به عام 1106 (1695) مُنح الملتزمون حق ضريبة ثابتة مدى الحياة، وأُدخل حافز لحماية الإنتاج بدلًا من الاستغلال قصير الأجل.", "f564e96c"]},
"OLAYLAR_EK7:1695-02-06:0":{"b": ["جلوس مصطفى الثاني على العرش", "b53656c7"], "d": ["وفقًا لمادة مصطفى الثاني في موسوعة الإسلام التركية (TDV)، أعلن مصطفى الثاني، الذي تولى العرش وهو في الحادية والثلاثين من عمره، سلطنته دون انتظار موافقة الصدر الأعظم وشيخ الإسلام؛ وأُقيم حفل تقليد السيف بعد أيام قليلة في الجامع القديم. وصار السلطان، الذي تولى العرش في فترة استمرت فيها الحروب على جبهات متعددة بعد هزيمة فيينا، آخر سلطان عثماني يخرج بنفسه إلى الحملة.", "6cd0fed9"]},
"OLAYLAR_EK7:1695-05-25:0":{"b": ["تعيين فيض الله أفندي شيخًا للإسلام للمرة الثانية", "1cf14cff"], "d": ["وفقًا لمادة فيض الله أفندي، سيد في موسوعة الإسلام التركية (TDV)، عُيّن في مشيخة الإسلام للمرة الثانية في 11 شوال 1106 (25 مايو 1695) عقب جلوس مصطفى الثاني. وازداد نفوذه على السلطان تدريجيًا خلال فترة هذا المنصب التي دامت أكثر من ثماني سنوات.", "a2d4ab3e"]},
"OLAYLAR_EK7:1703-03-01:0":{"b": ["تولية فيض الله أفندي أبناءه المناصب العليا وتراكم ردود الفعل", "a6398280"], "d": ["وفقًا لمادة فيض الله أفندي، سيد في موسوعة الإسلام التركية (TDV)، نال شيخ الإسلام من مصطفى الثاني فرمانًا لا مثيل له بأن يكون ابنه فتح الله أفندي شيخًا للإسلام بعده، ووضع أقاربه في مناصب عليا في سن مبكرة. وأثارت هذه الممارسات استياءً واسعًا بين طبقة العلمية والجيش وأهالي إسطنبول؛ وتضافرت مع شائعات عن نقل العاصمة إلى أدرنة فمهدت الأرضية لوقعة أدرنة عام 1703.", "34c068d3"]},
"OLAYLAR_EK7:1703-07-17:0":{"b": ["اندلاع وقعة أدرنة", "5a106458"], "d": ["وفقًا لمادة «وقعة أدرنة» في TDV، بدأت الحركة بتمرد جنود لم يتقاضوا رواتبهم، وسرعان ما تحولت إلى تمرد واسع شارك فيه الإنكشارية وطلبة المدارس والتجار والعامة. وكان الهدف الأساسي للتمرد شيخ الإسلام فيض الله أفندي الذي زُعم أنه يتدخل في شؤون الدولة تدخلًا مفرطًا. وسار جمع يناهز 60.000 شخص من إسطنبول إلى أدرنة.", "201120ba"]},
"OLAYLAR_EK7:1718-05-09:0":{"b": ["صدارة نوشهرلي داماد إبراهيم باشا العظمى", "8d627a6f"], "d": ["وفقًا لمادة «داماد إبراهيم باشا، نوشهرلي» في TDV، عُيّن في منصب الصدارة العظمى في 8 جمادى الآخرة 1130 (9 مايو 1718) أثناء مفاوضات السلام الجارية مع النمسا، وتوجه فور تعيينه إلى المفاوضات التي ستنهي الحرب؛ وبعد شهرين وُقعت معاهدة باساروفيتس (21 يوليو 1718). وبحسب تعبير TDV: «كان يريد الانشغال بالمسائل الاجتماعية والمالية، وكان يتوق إلى عصر سلام ينسي الحروب التي انتهت بالهزيمة منذ سنوات طويلة». وأجرى إصلاحات في المالية فخفض رواتب الجنود وكوّن فائضًا مهمًا في خزينة الدولة. وشكلت صدارته التي ستدوم اثنتي عشرة سنة الإطار السياسي للعهد الذي يحمل اسمه (عصر التوليب).", "5874203b"]},
"OLAYLAR_EK7:1720-06-01:0":{"b": ["تأسيس أوجاق الطلمبجية", "f58b0d97"], "d": ["وفقًا لمادة «الطلمبجي» في TDV، إثر نجاح داود الحقيقي، العائد من حملة المورة عام 1715، في استخدام المضخة في حرائق إسطنبول، كلّفه الصدر الأعظم نوشهرلي داماد إبراهيم باشا بتأسيس أوجاق رسمي لإطفاء الحرائق. وبلغ الأوجاق، الذي أُسس في ثكنة عجمي أوغلان بستة ضباط وخمسين فردًا، 150 فردًا عام 1724 و461 فردًا عام 1755. وبقي داود على رأس الأوجاق حتى وفاته عام 1733.", "3b860f0f"]},
"OLAYLAR_EK7:1721-03-21:0":{"b": ["استقبال لويس الخامس عشر لمحمد أفندي", "0ff5b174"], "d": ["وفقًا لمادة «يكرمي سكيز جلبي محمد أفندي» في TDV، استقبل ملك فرنسا لويس الخامس عشر السفير رسميًا في قصر التويلري، وقدم هدايا أحمد الثالث ورسالته. وزار خلال إقامته قصور فرساي وتريانون ومارلي والمستشفيات والمراصد والمصانع، وسجل ما رآه برسوم.", "c0c34dbc"]},
"OLAYLAR_EK7:1721-10-08:0":{"b": ["عودة محمد أفندي إلى إسطنبول", "a09a8bba"], "d": ["وفقًا لمادة «يكرمي سكيز جلبي محمد أفندي» في TDV، أثرت ملاحظات السفير العائد من سفارة دامت سنة في باريس في الذوق المعماري لعصر التوليب. وكان عمل ابنه لاحقًا مع إبراهيم متفرقة تمهيدًا لتأسيس أول مطبعة تركية، وهي أدوم إرث للسفارة.", "799571fc"]},
"OLAYLAR_EK7:1722-06-01:0":{"b": ["بناء قصر سعد آباد", "aec9c65e"], "d": ["وفقًا لمادة «سعد آباد» في TDV، أُنشئ على ضفة نهر كاغدخانة مجمع واسع للترفيه والنزهة، مؤلف من قصر وقنوات وسُبُل وأجنحة، مستوحى من العمارة القصرية الفرنسية. وصار سعد آباد، وقد غدا أحب أماكن الترفيه في العصر، خالدًا في أشعار الشاعر نديم. وقد دُمّر المجمع في معظمه أثناء تمرد باترونا خليل عام 1730.", "2698478e"]},
"OLAYLAR_EK7:1722-09-03:0":{"b": ["استيلاء القوات الروسية على دربند: حملة بطرس الأول على بحر قزوين", "c2b269f9"], "d": ["في وقت كانت الدولة الصفوية تنجرف فيه إلى الاضطراب الداخلي بسبب الغزو الأفغاني، خرج القيصر الروسي بطرس الأول في حملة بقصد الاستيلاء على الأراضي الإيرانية على ساحل بحر قزوين؛ وسلّمت مدينة دربند الساحلية نفسها للقوات الروسية دون مقاومة تُذكر. ووفقًا لمادة «دربند» في موسوعة الإسلام التركية (TDV)، كان هذا الاحتلال بداية سيادة روسية مؤقتة ستدوم ثلاث عشرة سنة؛ وتوجهت الدولة العثمانية كذلك، مستفيدة من الاضطراب نفسه، نحو القسم الغربي من القوقاز. وكان الجيش قد نزل من أستراخان بحرًا إلى خليج أغراخان، ثم سار برًا على طول الساحل عبر طرقو؛ واستضاف شمخال طرقو بطرس ودخل في التبعية الروسية.", "4220bd4e"]},
"OLAYLAR_EK7:1726-01-01:0":{"b": ["إلغاء شمخالية طرقو: الإدارة الروسية المباشرة", "b0f029c6"], "d": ["ثار شمخال طرقو عادل كراي، الذي استضاف بطرس عام 1722 ودخل في التبعية الروسية، في عام 1725؛ فدمّر ييروبكين طرقو في خريف 1725، واعتُقل الشمخال ونُفي في منتصف مايو 1726، وأُلغيت الشمخالية. وبقيت طرقو وما حولها تحت الإدارة الروسية المباشرة حتى معاهدة كنجة عام 1735.", "32bb2cc9"]},
"OLAYLAR_EK7:1727-07-01:0":{"b": ["الإذن لإبراهيم متفرقة بتأسيس مطبعة", "0659dd0a"], "d": ["وفقًا لمادة «إبراهيم متفرقة» في TDV، أُذن بتأسيس أول مطبعة تركية بفرمان من أحمد الثالث وبفتوى من شيخ الإسلام يني شهرلي عبد الله أفندي. وبدأت المطبعة عملها في حي يافوز سليم في إسطنبول. وطبع متفرقة حتى وفاته عام 1747 سبعة عشر كتابًا في ثلاثة وعشرين مجلدًا.", "2b37f2a0"]},
"OLAYLAR_EK7:1729-02-01:0":{"b": ["اكتمال أول كتاب مطبوع: قاموس وانقولي", "684700e8"], "d": ["وفقًا لمادة «إبراهيم متفرقة» في TDV، اكتملت في أوائل عام 1729 الترجمة التركية لـ«صحاح الجوهري» (قاموس وانقولي)، وهي أول أعمال المطبعة. وكان هذا أول كتاب يُطبع بالحروف العربية في الأراضي العثمانية، ويُعدّ بداية تاريخ الطباعة التركية.", "d204cfc9"]},
"OLAYLAR_EK7:1730-10-01:0":{"b": ["إعدام نوشهرلي داماد إبراهيم باشا", "50c64341"], "d": ["وفقًا لمادة «داماد إبراهيم باشا، نوشهرلي» في TDV، سُحبت جثة الصدر الأعظم، الذي قُتل في القصر أثناء تمرد باترونا خليل، في شوارع إسطنبول ثم تُركت قرب سبيل أحمد الثالث في ميدان السلطان أحمد. وانتهت بذلك صدارته التي دامت اثنتي عشرة سنة وعصر التوليب نهاية دموية.", "3af021b4"]},
"OLAYLAR_EK7:1730-10-02:0":{"b": ["تنازل أحمد الثالث عن العرش وجلوس محمود الأول", "a43f5d40"], "d": ["وفقًا لمادة «محمود الأول» في TDV، تنازل أحمد الثالث عن العرش بعد أن أخذ ضمانًا لنفسه ولأولاده أمام ضغط الثوار، وأجلس بنفسه ابن أخيه الأمير محمود على العرش. وشرع محمود الأول، الذي جلس على العرش بنصيحة عمه «خذ شؤون الدولة بيدك ولا تثق بأحد»، أول ما شرع في كسر نفوذ جماعة الثوار التي أجلسته على العرش.", "32260f8c"]},
"OLAYLAR_EK7:1733-06-01:0":{"b": ["إصلاح أحمد باشا القومباراجي لأوجاق المدفعية", "ea3a7c64"], "d": ["وفقًا لمادة «القومباراجي» في TDV، شرع الضابط أحمد باشا، الفرنسي الأصل الذي اعتنق الإسلام، في عهد الصدر الأعظم حكيم أوغلو علي باشا في إصلاح تنظيم القومباراجية ذوي العلوفة على النمط الأوروبي. وأقام بنية جديدة تتبع الصدر الأعظم مباشرة، من 601 شخص، منهم 300 برواتب و301 بتيمار. وأنتج بتقنية العصر 100 مدفع هاون و50.000 قذيفة.", "bf4e60c1"]},
"OLAYLAR_EK7:1734-06-01:0":{"b": ["تأسيس الهندسخانة (النموذج الأول لمدرسة الهندسة)", "a77ed1f3"], "d": ["وفقًا لمادة «محمود الأول» في TDV، أسس أحمد باشا القومباراجي في أسكدار الهندسخانة، التي تُسمى أيضًا القومبارخانة، وقدم تدريبًا عسكريًا قائمًا على الرياضيات والهندسة للطلاب الذين اختارهم من بين خدم القصر والبستانجية. وتُعدّ هذه المؤسسة النموذج الأول لمدارس الهندسة التي ستتطور في العهد اللاحق.", "84b5af85"]},
"OLAYLAR_EK7:1735-03-21:0":{"b": ["معاهدة كنجة: إعادة دربند وباكو إلى إيران", "ff19d531"], "d": ["أعادت روسيا، التي كانت تبحث عن تحالف مع إيران في وجه التهديد العثماني، بموجب معاهدة كنجة مدن ساحل بحر قزوين التي ظلت في يدها ثلاث عشرة سنة إلى إيران بقيادة نادر خان (الذي لم يكن قد اتخذ لقب شاه بعد). ووفقًا لمادة «دربند» في موسوعة الإسلام التركية (TDV)، كان هذا الانسحاب نتيجة لعدم رغبة روسيا في قتال على جبهتين في الجنوب (العثمانية والإيرانية) في آن واحد، وعزز مكانة نادر العسكرية التي مهدت طريق جلوسه على العرش بعد بضع سنوات. وعادت طرقي (طرقو) الخاضعة للإدارة الروسية هي الأخرى إلى الجانب الإيراني بهذا الانسحاب (يُستعمل في الخريطة يوم كنجة).", "94b6c31b"]},
"OLAYLAR_EK7:1736-03-08:0":{"b": ["جلوس نادر شاه على العرش في سهل موغان: النهاية الفعلية للأسرة الصفوية", "4f640979"], "d": ["وفقًا لمادة «نادر شاه» في موسوعة الإسلام التركية (TDV)، ألحّ مجلس القورولتاي المنعقد في سهل موغان، المؤلف من نحو عشرين ألف شخص، على أن يتولى نادر رئاسة إيران؛ فقبل نادر هذا العرض بشرط التخلي عن الفهم الشيعي المفرط الذي تسبب في الحروب بين الصفويين والعثمانيين واعتماد المذهب الجعفري المعتدل، وجلس على العرش بلقب نادر شاه في 24 شوال 1148 (8 مارس 1736). وكان ذلك يعني النهاية الفعلية للأسرة الصفوية التي دامت قرنين وتأسيس الأسرة الأفشارية.", "7f742f06"]},
"OLAYLAR_EK7:1739-06-01:0":{"b": ["بدء وباء الطاعون في إسطنبول", "9fa82b56"], "d": ["وفقًا لمادة «الطاعون» في TDV، ضرب وباء الطاعون، الذي كان مؤثرًا في الجغرافيا الإسلامية بين عامي 1739 و1743، إسطنبول أيضًا في هذه الفترة. وتشير المادة إلى أن أوبئة القرن 18 كانت أخف نسبيًا من أوبئة القرون السابقة. وتُعدّ سنوات 1713 و1719 و1728-1729 و1759-1765 أيضًا من فترات الوباء.", "d650b99e"]},
"OLAYLAR_EK7:1755-09-29:0":{"b": ["حريق خوجه باشا", "321c7d0d"], "d": ["وفقًا لمادة «جامع فاطمة سلطان» في TDV، دمّر حريق خوجه باشا، الذي اندلع ليلًا، الباب العالي وما حوله؛ ويُقدَّر أن جامع فاطمة سلطان في المنطقة تضرر من هذا الحريق أيضًا. وقد تسببت هذه الكارثة، وهي من الحرائق الكبرى التي ضربت إسطنبول في عهد عثمان الثالث، في دمار شديد في مركز المدينة التجاري والإداري.", "3554d781"]},
"OLAYLAR_EK7:1757-02-28:0":{"b": ["صدارة كوجه راغب محمد باشا العظمى", "a1846910"], "d": ["عُيّن راغب باشا، المعروف بكونه شاعرًا ودبلوماسيًا، في منصب الصدارة العظمى على يد عثمان الثالث (واصل مهامه بعد وفاة عثمان الثالث في أكتوبر 1757 ونال ختمًا جديدًا من مصطفى الثالث). واتبع سياسة خارجية متوازنة أبقت الدولة العثمانية بمنأى عن النزاعات في أوروبا أثناء حرب السنوات السبع. وأولى أهمية للأنشطة الثقافية، كتأسيس المكتبات، طوال صدارته التي ستدوم ست سنوات.", "d3682725"]},
"OLAYLAR_EK7:1763-04-08:0":{"b": ["وفاة راغب باشا", "6bc19323"], "d": ["توفي راغب باشا بعد صدارة دامت ست سنوات. وبوفاته انتهت أطول صدارة عظمى في عهد مصطفى الثالث نفَسًا وأكثرها توازنًا.", "7da43eab"]},
"OLAYLAR_EK7:1766-05-01:0":{"b": ["زلزال إسطنبول الكبير وانهيار جامع الفاتح", "2475b4dc"], "d": ["وفقًا لمادة «جامع الفاتح ومجمعه» في TDV، انهارت القبة الرئيسية للجامع انهيارًا تامًا في الزلزال الكبير عام 1766، وتضررت جدرانه ضررًا لا يمكن إصلاحه. وبأمر مصطفى الثالث بدأت عام 1767 إعادة البناء تحت إشراف المعماريين صاريم إبراهيم أفندي وعزت محمد بك، واكتملت عام 1771 بتصميم جديد يختلف عن المخطط القديم.", "680af5a8"]},
"OLAYLAR_EK7:1772-10-01:0":{"b": ["تجربة مدرسة مدفعية قصيرة العمر بقيادة البارون دو توت", "4192260c"], "d": ["وفقًا لمادة «مهندسخانة بحري همايون» في TDV، كشفت الإخفاقات في الحرب العثمانية الروسية عام 1768 الحاجة إلى التدريب العسكري التقني؛ وبدأت مدرسة المدفعية قصيرة العمر، التي افتُتحت بمساهمة الضابط الفرنسي البارون دو توت، عملها في أكتوبر 1772 لكنها ظلت عديمة الأثر. وتُعدّ هذه التجربة طليعة مهندسخانة بحري همايون التي ستؤسس عام 1775.", "1b031ce8"]},
"OLAYLAR_EK7:1789-04-07:0":{"b": ["جلوس سليم الثالث على العرش", "00d046d9"], "d": ["إثر وفاة عبد الحميد الأول، تولى ابن أخيه سليم الثالث العرش. ووفقًا لمادة سليم الثالث في موسوعة الإسلام التركية (TDV)، بدأ السلطان الجديد، الذي كان يهتم منذ أن كان أميرًا بإصلاح الجيوش الأوروبية، يعدّ برنامج تجديد جذري بعد جلوسه بوقت قصير. وسيُعرف هذا البرنامج بعد بضع سنوات باسم النظام الجديد.", "ec094618"]},
"OLAYLAR_EK7:1792-06-01:0":{"b": ["بدء إعداد برنامج إصلاح النظام الجديد", "eff78a68"], "d": ["أعدّ سليم الثالث برنامج تجديد شامل وفق اللوائح التي طلبها من رجال الدولة والخبراء الأجانب. ووفقًا لمادة «النظام الجديد» في موسوعة الإسلام التركية (TDV)، لم يقتصر هذا البرنامج على تأسيس جيش جديد، بل تحول إلى حركة إصلاح واسعة شملت المالية وإدارة الولايات والدبلوماسية. وسيجد البرنامج في السنوات الخمس عشرة التالية مؤيدين ومعارضين.", "7efcd62f"]},
"OLAYLAR_EK7:1793-03-01:0":{"b": ["تأسيس سفارات دائمة في العواصم الأوروبية", "2e9dc8a1"], "d": ["أرسل سليم الثالث، لأول مرة في تاريخ الدولة العثمانية، سفراء دائمين للعمل المستمر في المراكز الأوروبية الكبرى. ووفقًا لمادة «السفير» في موسوعة الإسلام التركية (TDV)، أعطت هذه الخطوة الدبلوماسية العثمانية، التي كانت تُدار حتى ذلك الوقت بوفود مؤقتة لمرة واحدة فقط، تنظيمًا دائمًا. وكانت المهمة الرئيسية للسفارات الجديدة إبلاغ إسطنبول بانتظام بالتطورات السياسية والعسكرية في أوروبا.", "8fef612b"]},
"OLAYLAR_EK7:1793-06-01:0":{"b": ["تأسيس خزينة الإيراد الجديد", "ae5c8ce2"], "d": ["أُسست خزينة منفصلة لتغطية نفقات جيش النظام الجديد وبرنامج الإصلاح. ووفقًا لمادة «الأسهم» في موسوعة الإسلام التركية (TDV)، كان من إيرادات الخزينة الجديدة تشغيل بعض المقاطعات مباشرة بيد الدولة وإخضاع بيع الأسهم للرقابة. وكان هذا الترتيب محاولة لخلق مورد جديد خارج نظام المالية التقليدي.", "ddacec62"]},
"OLAYLAR_EK7:1807-05-25:0":{"b": ["اندلاع تمرد قاباقجي مصطفى", "b98eee17"], "d": ["انفجر الاستياء المتراكم ضد النظام الجديد بتمرد جنود اليماك بقيادة قاباقجي مصطفى. ووفقًا لمادة «تمرد قاباقجي» في موسوعة الإسلام التركية (TDV)، سيطر الثوار على إسطنبول في وقت قصير وطالبوا برؤوس رجال الدولة المؤيدين للنظام الجديد. وانتهى التمرد في غضون أيام بخلع سليم الثالث عن العرش.", "820bdd75"]},
"OLAYLAR_EK7:1807-05-29:0":{"b": ["خلع سليم الثالث عن العرش", "ff2c30ec"], "d": ["خُلع سليم الثالث عن العرش بفتوى من شيخ الإسلام تحت ضغط تمرد قاباقجي مصطفى. ووفقًا لمادة سليم الثالث في موسوعة الإسلام التركية (TDV)، كان هذا القرار اللحظة التي انتهت فيها فعليًا مرحلة الإصلاح التي دامت ثماني عشرة سنة؛ وأُلغي جيش النظام الجديد أيضًا في وقت قصير. وبدأ احتجاز سليم في قصر طوب قابي.", "d4f1293b"]},
"OLAYLAR_EK7:1807-05-29:1":{"b": ["جلوس مصطفى الرابع على العرش", "8f1ac86c"], "d": ["أُعلن ابن أخي سليم الثالث، مصطفى الرابع، سلطانًا فور خلعه عن العرش. ووفقًا لمادة مصطفى الرابع في موسوعة الإسلام التركية (TDV)، بدأ السلطان الجديد سلطنته تحت تأثير الأوساط المعادية للنظام الجديد التي دعمت التمرد. وكانت هذه الفترة القصيرة مرحلة من عدم الاستقرار ضعفت فيها السلطة المركزية ضعفًا شديدًا.", "58865f17"]},
"OLAYLAR_EK7:1808-07-19:0":{"b": ["دخول علمدار مصطفى باشا إسطنبول بجيشه", "0cad3dea"], "d": ["جاء أعيان روسجق علمدار مصطفى باشا بجيشه إلى أطراف إسطنبول بقصد إعادة سليم الثالث إلى العرش. ووفقًا لمادة علمدار مصطفى باشا في موسوعة الإسلام التركية (TDV)، استقبله مصطفى الرابع بنفسه عند دخوله المدينة؛ لكن ميزان القوى داخل القصر سيتغير تمامًا في غضون أيام. وأطلق هذا الدخول سلسلة من الأحداث انتهت بوفاة سليم وبجلوس جديد على العرش.", "c042d316"]},
"OLAYLAR_EK7:1808-07-28:0":{"b": ["مقتل سليم الثالث", "e452f5f6"], "d": ["في اليوم الذي استولى فيه علمدار مصطفى باشا على الباب العالي، قُتل سليم الثالث في القصر بأمر مصطفى الرابع. ووفقًا لمادة سليم الثالث في موسوعة الإسلام التركية (TDV)، كان ذلك قرارًا اتُّخذ لمنع محاولة إعادة سلطان مخلوع إلى العرش. وأفضت وفاة سليم، في اليوم نفسه، إلى جلوس محمود.", "7d63123d"]},
"OLAYLAR_EK7:1808-07-28:1":{"b": ["جلوس محمود الثاني على العرش", "661c1974"], "d": ["بعد قتل سليم الثالث، جلس محمود، وقد بقي العضو الذكر الوحيد في الأسرة الحاكمة، على العرش بدعم من علمدار مصطفى باشا. ووفقًا لمادة محمود الثاني في موسوعة الإسلام التركية (TDV)، أمضى السلطان الجديد الأشهر الأولى من سلطنته تحت وصاية علمدار الذي أجلسه على العرش، ساعيًا إلى إعادة إقامة التوازن بين الأعيان والمركز. وكانت هذه الفترة بداية مسيرة إصلاح جذري دامت عشرين سنة تالية.", "491f1eb0"]},
"OLAYLAR_EK7:1808-08-15:0":{"b": ["تأسيس جيش السكبان الجديد", "6f9eb5e4"], "d": ["أنشأ علمدار مصطفى باشا جيشًا جديدًا مجهزًا على الطريقة الأوروبية بدلًا من النظام الجديد الملغى. ووفقًا لمادة «السكبان الجديد» في موسوعة الإسلام التركية (TDV)، عدّ الإنكشارية هذه القوة المؤلفة من ثلاثة أفواج تهديدًا مباشرًا لهم، وقُضي عليها في تمرد للإنكشارية بعد أشهر قليلة فقط من تأسيسها.", "ba52d1dd"]},
"OLAYLAR_EK7:1809-12-02:0":{"b": ["سقوط إبراييل — أول ثغرة كبرى في خط الدانوب", "ee519321"], "d": ["في الحرب الروسية التي بدأت عام 1806، حوصرت قلعة إبراييل على الضفة الشمالية للدانوب وقُصفت بالمدافع من القوات الروسية بقيادة الكونت كامينسكي. وكان في داخلها 4100 مشاة و1100 فارس و260 مدفعًا؛ وسلّمت القلعة للجنرال إيسن بسبب نقص الأقوات. وبذلك انفتح الطرف الشمالي من خط الدفاع على الدانوب.", "12ec2aef"]},
"OLAYLAR_EK7:1810-09-26:0":{"b": ["تسليم روسجق — الضفة الجنوبية للدانوب تخرج من اليد أيضًا", "084062e8"], "d": ["قاومت روسجق حصارًا طويلًا ودمويًا من الجيش الروسي بقيادة الكونت كامينسكي؛ وسلّمت بشرط أن يغادر الحامية والسكان المدنيون المدينة آمنين. وحوّل سقوط أقوى مدينة قلعة على الضفة الجنوبية للدانوب مجرى الحرب لصالح روسيا.", "00685e1d"]},
"OLAYLAR_EK7:1826-05-15:0":{"b": ["تأسيس أوجاق الأشكنجية", "67c56759"], "d": ["أسس محمود الثاني وحدة جديدة تتدرب على الطريقة الأوروبية من جنود اختيروا من داخل أوجاق الإنكشارية. ووفقًا لمادة «أوجاق الأشكنجية» في موسوعة الإسلام التركية (TDV)، بدأت الوحدة التدريب في 12 يونيو 1826، لكن الإنكشارية رأوا في ذلك نهاية أوجاقهم. وأنهى التمرد الذي اندلع بعد ثلاثة أيام عمر أوجاق الأشكنجية القصير أيضًا.", "ab923dc4"]},
"OLAYLAR_EK7:1826-06-18:0":{"b": ["تأسيس العساكر المنصورة المحمدية", "14b84a7e"], "d": ["فور إلغاء أوجاق الإنكشارية، أسس محمود الثاني بدلًا منه جيشًا جديدًا نظاميًا مدربًا على الطريقة الأوروبية. ووفقًا لمادة «العساكر المنصورة المحمدية» في موسوعة الإسلام التركية (TDV)، صار هذا الجيش مؤسسة دائمة، خلافًا للمحاولات السابقة، بنظام الرتب وبرنامج التدريب ونظام الرواتب. وسيتحول الجيش في السنوات التالية إلى الجيش النظامي في عهد التنظيمات.", "2e0ee6f7"]},
"OLAYLAR_EK7:1826-06-19:0":{"b": ["إغلاق الطريقة البكتاشية", "f7d9a367"], "d": ["بالتزامن مع إلغاء أوجاق الإنكشارية، حُظرت كذلك الطريقة البكتاشية المعروفة بصلاتها الدينية بالأوجاق. ووفقًا لمادة «البكتاشية» في موسوعة الإسلام التركية (TDV)، أُعدم بعض شيوخ التكايا الصغيرة، ونُفي شيخ درگاه حاجي بكتاش إلى أماسيا، وسُلّمت التكايا إلى إدارة النقشبندية. وواصلت الطريقة تنظيمها سرًا رغم هذه الضربة الثقيلة.", "305773c2"]},
"OLAYLAR_EK7:1827-04-29:0":{"b": ["حادثة المروحة — ذريعة الاحتلال", "e949001e"], "d": ["في مفاوضات توترت بسبب عدم سداد دين الحبوب القديم المستحق على فرنسا للجزائر، ضرب الداي حسين القنصل الفرنسي دوفال بالمروحة التي في يده. وجُعلت هذه الحادثة، التي نشأت عن خلاف حول دين مستحق، ذريعةً رسمية للاحتلال الذي سيبدأ بعد ثلاث سنوات.", "0e58142a"]},
"OLAYLAR_EK7:1827-06-16:0":{"b": ["الحصار البحري الفرنسي لسواحل الجزائر — حصار دام ثلاث سنوات", "d0ba97a5"], "d": ["بعد حادثة المروحة ضربت فرنسا حصارًا على السواحل الجزائرية. واستمر الحصار ثلاث سنوات؛ وجُففت موارد الأوجاق من التجارة البحرية ومصادر الدخل، وتآكلت قدرته على المقاومة قبل أن يبدأ الاحتلال.", "79d27be2"]},
"OLAYLAR_EK7:1828-02-22:0":{"b": ["معاهدة تركمانجاي: انتقال إيروان وطالش إلى روسيا", "abffcfdb"], "d": ["لما انتهت الحرب الروسية الإيرانية في 1826-1828 بهزيمة ثقيلة لإيران، تُركت بموجب المعاهدة الموقعة في تركمانجاي خانيتا إيروان ونخجوان ومنطقة طالش على ساحل بحر قزوين (لنكران وأستارا) لروسيا؛ وفُرض فضلًا عن ذلك تعويض حرب ثقيل. ووفقًا لمادة «إيروان» في موسوعة الإسلام التركية (TDV)، هذه الخسارة هي اللحظة التي رُسمت فيها الحدود الروسية الإيرانية في القوقاز بشكل سيبقى ساريًا إلى حد كبير حتى اليوم، وقد أطلقت كذلك هجرة السكان الأرمن إلى إيروان.", "f6438d89"]},
"OLAYLAR_EK7:1828-06-23:0":{"b": ["السقوط الثاني لإبراييل — القيصر نيقولا أمام القلعة", "eb6a8741"], "d": ["حوصرت إبراييل، التي أُعيدت إلى العثمانيين عام 1812 وأُعيد تحصينها في 1817-1818، في أبريل وفيها 4000 حارس و278 مدفعًا. وأقام قائدها أبو بكر باشا خط دفاع جديدًا؛ وجاء القيصر نيقولا الأول بنفسه إلى أمام القلعة في أواخر مايو. وتعرضت المدينة للاحتلال الروسي، لكنها ستُعاد بمعاهدة أدرنة وتُترك لإمارة الأفلاق.", "b7e53f03"]},
"OLAYLAR_EK7:1829-06-01:0":{"b": ["إعلان الطربوش غطاء الرأس الرسمي", "f55be4eb"], "d": ["أجرى محمود الثاني تغييرًا جذريًا في لباس الموظفين والجنود، فأعلن الطربوش غطاء الرأس الرسمي بدلًا من العمامة. ووفقًا لمادة «الطربوش» في موسوعة الإسلام التركية (TDV)، أُعلن هذا القرار بخط همايوني وطُبق مع الإصلاحات ذات الطابع الغربي للعساكر المنصورة المحمدية. وكان التغيير يعني أيضًا إنهاء التسلسل الهرمي التقليدي للباس.", "9739e485"]},
"OLAYLAR_EK7:1829-09-14:0":{"b": ["التخلي عن أخسخة لروسيا — مركز إيالة جلدير يخرج من اليد", "e2e00b2a"], "d": ["أخسخة، التي كانت تحت الإدارة العثمانية منذ حرب جلدير عام 1578 ومركز إيالة جلدير، تُركت لروسيا بمعاهدة أدرنة الموقعة في ختام حرب 1828-1829. وخلّف خروج المدينة من اليد حزنًا عميقًا بين الناس وصار موضوعًا لكثير من المراثي.", "9ad8078a"]},
"OLAYLAR_EK7:1830-06-14:0":{"b": ["إنزال سيدي فرج — الجيش الفرنسي على أرض الجزائر", "33327553"], "d": ["بعد حصار دام ثلاث سنوات، أنزل جيش الإنزال الفرنسي بقيادة الكونت دي بورمون جنوده في خليج سيدي فرج في غرب الجزائر. وكسرت القوات الزاحفة نحو المدينة خط الدفاع في ثلاثة أسابيع؛ وسقطت في 4 يوليو قلعة الإمبراطور المشرفة على المدينة، وفي اليوم التالي استسلم الداي حسين.", "0d2a2c9a"]},
"OLAYLAR_EK7:1830-08-09:0":{"b": ["نفي الداي حسين — النهاية الفعلية لأوجاق الجزائر", "e122403b"], "d": ["بموجب شروط الاستسلام، أُخرج آخر دايات الجزائر، حسين، من المدينة مع أسرته وخزينته وأُرسل إلى نابولي. وبذلك انتهت إدارة الأوجاق الذي ارتبط بسليم الثاني عام 1519 وكان طوال ثلاثمئة سنة أقوى قاعدة بحرية عثمانية في البحر المتوسط.", "54846340"]},
"OLAYLAR_EK7:1834-01-01:0":{"b": ["انسحاب الجيش الروسي من الأفلاق والبغدان — نهاية احتلال دام ست سنوات", "efdb0275"], "d": ["في الحرب العثمانية الروسية 1828-1829 احتل الروس الأفلاق والبغدان، ولم ينسحبوا بعد معاهدة أدرنة أيضًا إلى أن يُدفع تعويض الحرب. ولما خُفض التعويض إلى خمسة ملايين في يناير 1834، أخلت القوات الروسية الإمارتين، وعُيّن في الإمارتين وُلاة جدد. وعادت التبعية العثمانية على الورق، لكن روسيا حافظت على النفوذ الذي أقامته بالنظام الأساسي (Reglement Organique).", "312a9319"]},
"OLAYLAR_EK7:1834-07-08:0":{"b": ["تأسيس تنظيم رديف العساكر المنصورة", "15947493"], "d": ["أُسس تنظيم الرديف قوةً احتياطية تدعم العساكر المنصورة المحمدية، بنظامنامة مؤرخة في 8 يوليو 1834. ووفقًا لمادة «الرديف» في موسوعة الإسلام التركية (TDV)، شُكلت في أقضية الولايات، تحت إشراف السرعسكر قوجه خسرو باشا، طوابير من نحو ألف وأربعمئة فرد لكل منها. وصُمّم التنظيم بحيث يدعم الأمن المحلي أيضًا دون أن يُستدعى للخدمة الدائمة.", "ca6cb4a0"]},
"OLAYLAR_EK7:1836-06-01:0":{"b": ["تأسيس نظارة الخارجية", "750c6c7d"], "d": ["ألغى محمود الثاني منصب رئيس الكتّاب الذي كان يدير الشؤون الخارجية وأسس بدلًا منه نظارة الخارجية. ووفقًا لمادة «نظارة الخارجية» في موسوعة الإسلام التركية (TDV)، عُيّن محمد عاكف باشا في أول وزارة لهذه النظارة، وبدأ التنظيم عمله في قصر رفعت بك سفير فيينا. وكان هذا الترتيب بداية إدارة السياسة الخارجية العثمانية على أساس الوزارة الحديثة.", "50ebd952"]},
"OLAYLAR_EK7:1838-03-24:0":{"b": ["تأسيس مجلس الأحكام العدلية الأعلى", "69db056e"], "d": ["أسس محمود الثاني مجلس الأحكام العدلية الأعلى مجلسًا رفيع المستوى تُناقش فيه القوانين والنظم التي ستُعد. ووفقًا لمادة «مجلس والا أحكام عدلية» في موسوعة الإسلام التركية (TDV)، بدأ المجلس عمله فعليًا في 31 مارس 1838، وأُعدّت تقريبًا جميع إصلاحات التنظيمات اللاحقة وروقبت عبر هذا المجلس. وصارت المؤسسة من أهم مراكز البيروقراطية العثمانية الحديثة.", "9346611a"]},
"OLAYLAR_EK7:1853-11-30:0":{"b": ["غارة سينوب", "5947e93f"], "d": ["شن الأسطول الروسي في البحر الأسود، بقيادة الأميرال ناخيموف، غارة على الأسطول العثماني الراسي في ميناء سينوب دون إعلان حرب؛ فغرقت اثنتا عشرة سفينة، واستُشهد أكثر من ألفي جندي، وأُسر قائد الأسطول عثمان باشا. ووفقًا لمادة «سينوب» في موسوعة الإسلام التركية (TDV)، احترقت في الغارة في المدينة أيضًا سبعة مساجد ومدرستان و247 بيتًا و170 دكانًا، وقُتل من المدنيين خمسة مسلمين وستة عشر مسيحيًا. وكانت الواقعة، التي دوّت في الرأي العام الأوروبي بوصفها «مأساة سينوب»، المحرّك المباشر لدخول إنجلترا وفرنسا الحرب في صف العثمانيين بعد أشهر قليلة.", "89a8c874"]},
"OLAYLAR_EK7:1862-06-27:0":{"b": ["صدور صحيفة تصوير أفكار", "506c98e2"], "d": ["بدأت صحيفة تصوير أفكار التي أصدرها شناسي بالصدور رابعَ صحيفة تركية بعد تقويم وقائع وجريدة حوادث وترجمان أحوال. ووفقًا لمادة «تصوير أفكار» في TDV، صارت الصحيفة في عهد نامق كمال، الذي تولى رئاسة التحرير لاحقًا، لسان حركة العثمانيين الجدد.", "72568463"]},
"OLAYLAR_EK7:1867-08-30:0":{"b": ["تأسيس جمعية العثمانيين الجدد", "335fb02d"], "d": ["تنظّم المثقفون العثمانيون الذين فروا إلى أوروبا بقيادة مصطفى فاضل باشا باسم تركيا الفتاة بنظام داخلي من ثلاث عشرة مادة. ووفقًا لمادة «جمعية العثمانيين الجدد» في TDV، نشرت المجموعة مطلب الحكم الدستوري بإصدار صحف مثل «المخبر» و«الحرية» في باريس ولندن وجنيف.", "169dff06"]},
"OLAYLAR_EK7:1868-03-05:0":{"b": ["تأسيس مجلس شورى الدولة", "b863b306"], "d": ["قُسّم مجلس الأحكام العدلية إلى قسمين، فأُسس شورى الدولة الذي يتولى الشؤون الإدارية وديوان الأحكام العدلية الذي ينظر في الشؤون القضائية. ووفقًا لمادة «شورى الدولة» في TDV، عُيّن مدحت باشا في أول رئاسة للمؤسسة التي اتُّخذ مجلس الدولة الفرنسي نموذجًا لها؛ وكان الهدف فصل التشريع والتنفيذ والقضاء بعضها عن بعض.", "6a4ac9ed"]},
"OLAYLAR_EK7:1869-04-08:0":{"b": ["صدور الإرادة بتأسيس دار الفنون", "513704bf"], "d": ["أُسست دار الفنون رسميًا بإرادة أعدّها الصدر الأعظم عالي باشا وناظر المعارف صفوت باشا؛ وكانت الدروس الأولى قد بدأت قبل ذلك عام 1863. ووفقًا لمادة «دار الفنون» في TDV، بدأت المؤسسة التدريس فعليًا في فبراير 1870 بإدارة خوجه تحسين أفندي، بفروع الفلسفة والأدب والعلوم والحقوق.", "884a094b"]},
"OLAYLAR_EK7:1869-06-01:0":{"b": ["بدء أعمال مجلة الأحكام العدلية", "8abdcbee"], "d": ["شرعت جمعية المجلة، التي تأسست برئاسة أحمد جودت باشا رئيس ديوان الأحكام العدلية، في إعداد قانون مدني يقوم على الفقه الحنفي. ووفقًا لمادة «مجلة الأحكام العدلية» في TDV، اكتمل الجزء الأخير من العمل المؤلف من ستة عشر كتابًا و1851 مادة في 15 سبتمبر 1876 وبدأ العمل به؛ ويُعدّ أول تقنين للفقه الإسلامي.", "159b40e5"]},
"OLAYLAR_EK7:1873-04-01:0":{"b": ["تمثيل مسرحية «وطن أو سيليستره» ونفي نامق كمال", "3861284c"], "d": ["لما مُثلت مسرحية نامق كمال الوطنية في مسرح كدك باشا، نزل الجمهور إلى الشوارع هاتفًا «يحيا الوطن، يحيا كمال». ووفقًا لمادة «نامق كمال» في TDV، ذعرت الحكومة من هذا الاستعراض فأغلقت صحيفة «عبرت» ونفت نامق كمال في 6 أبريل 1873 إلى قبرص (ماغوسا) دون محاكمة.", "b713ac86"]},
"OLAYLAR_EK7:1876-06-04:0":{"b": ["وفاة عبد العزيز في ظروف مشبوهة", "85816692"], "d": ["عُثر على عبد العزيز، الذي نُقل بإرادته بعد خلعه عن العرش إلى قصر فريّة (1 يونيو 1876)، في 4 يونيو في غرفته وقد قُطعت شرايين معصميه. وأعدّت هيئة أطباء من تسعة عشر شخصًا، شارك فيها أطباء السفارات، تقريرًا غامض العبارة؛ وأُعلن الموت في الصحف في 6 يونيو انتحارًا. أما التحقيق الذي أمر به عبد الحميد الثاني فانتهى إلى أن الوفاة ليست انتحارًا بل جريمة قتل، وحوكم المتهمون عام 1881 في محكمة يلدز؛ والمسألة لا تزال محل جدل في الكتابة التاريخية حتى اليوم.", "a7b39d5c"]},
"OLAYLAR_EK7:1877-02-05:0":{"b": ["عزل مدحت باشا من الصدارة العظمى ونفيه", "b5247b06"], "d": ["عُزل الصدر الأعظم مدحت باشا، مهندس القانون الأساسي، من منصبه على يد عبد الحميد الثاني بعد ستة أسابيع من إعلانه، ونُفي إلى خارج البلاد في ليلة واحدة. ووفقًا لمادة مدحت باشا في موسوعة الإسلام التركية (TDV)، يُربط العزل بانزعاج السلطان من الأحكام التي تقيّد سلطاته في الدستور. وذهب الباشا أولًا إلى نابولي، ثم إلى مدن أوروبية مختلفة.", "88f7d5e3"]},
"OLAYLAR_EK7:1902-01-15:0":{"b": ["استعادة عبد العزيز بن سعود الرياض من آل رشيد", "75eb8830"], "d": ["شنّ عبد العزيز، الشاب من أسرة آل سعود الذي نُفي إلى الكويت قبل عشر سنوات، بمفرزة صغيرة هجومًا على الرياض، وقتل قائم مقام والي آل رشيد (شمّر) واستولى على المدينة. ووفقًا لمادة «الرياض» في موسوعة الإسلام التركية (TDV)، سهّل ضعف آل رشيد المتزايد وعجزهم عن إرسال مدد إلى المدينة نجاح هذا الهجوم؛ ويُعدّ الحدث لحظة تأسيس الدولة السعودية الثانية التي ستشكل في السنوات الثلاثين التالية نواة المملكة العربية السعودية الحالية.", "7e0bf55b"]},
"OLAYLAR_EK7:1909-04-24:0":{"b": ["دخول جيش الحركة إسطنبول", "41c8304c"], "d": ["دخل جيش الحركة، الذي انطلق من سالونيك وتألف في أغلبه من وحدات تابعة لجمعية الاتحاد والترقي، إسطنبول لقمع تمرد 31 مارس. ووفقًا لمادة «جيش الحركة» في موسوعة الإسلام التركية (TDV)، تولى محمود شوكت باشا قيادته، وتولى رئاسة أركانه القائمقام مصطفى كمال. وبعد اشتباكات قصيرة أُعيد الأمن في المدينة.", "e47ad17d"]},
"OLAYLAR_EK7:1920-04-11:0":{"b": ["حلّ آخر مجلس مبعوثان عثماني", "2b709269"], "d": ["بعد الاحتلال الرسمي لإسطنبول من قوات الوفاق واعتقال كثير من النواب، صار مجلس المبعوثان عاجزًا عن العمل وحُلّ رسميًا بإرادة محمد السادس. ووفقًا لمادة «مجلس المبعوثان» في موسوعة الإسلام التركية (TDV)، رمز هذا الحل إلى نهاية تقليد البرلمان الدستوري العثماني فعليًا. وقد عزز الإغلاق الحاجة إلى انعقاد مجلس وطني جديد في أنقرة.", "4caabf36"]},
"OLAYLAR_EK7:1920-04-23:0":{"b": ["افتتاح المجلس الوطني الكبير لتركيا", "6eab539d"], "d": ["بعد حل مجلس المبعوثان في إسطنبول، اجتمع النواب في أنقرة وافتتحوا المجلس الوطني الكبير لتركيا، وانتُخب مصطفى كمال باشا رئيسًا للمجلس. ووفقًا لمادة «المجلس الوطني الكبير لتركيا» في موسوعة الإسلام التركية (TDV)، كان للمجلس طابع استثنائي جمع في يده السلطتين التشريعية والتنفيذية. وكان هذا الافتتاح نقطة التحول التي انتقل فيها المركز السياسي والمؤسسي للنضال الوطني إلى أنقرة.", "805871d7"]},
"OLAYLAR_EK8:1460-01-01:0":{"b": ["فتح قلعة زفورنيك (إزفورنيك)", "657c465a"], "d": ["فتح العثمانيون قلعة زفورنيك على ضفة نهر درينا عام 1460. ووفقًا لموسوعة الإسلام التركية (TDV)، جُعلت أولًا مركز قضاء لموقعها المناسب إداريًا وعسكريًا، وتحولت عام 1480 إلى مركز السنجق الذي يحمل الاسم نفسه، وحُصّنت عام 1491 بأسوار حجرية، فتحولت بجوامعها الستة وتكاياها الثماني وحماماتها إلى مركز إداري تجاري مهم.", "160e9a01"]},
"OLAYLAR_EK8:1468-01-01:0":{"b": ["وفاة قاسم خان وجلوس دانيال خان (خانية قاسم)", "522fd0fd"], "d": ["بوفاة مؤسس الخانية قاسم خان عام 873/1468، خلفه ابنه دانيال؛ وحكم دانيال حتى عام 1486.", "6217828f"]},
"OLAYLAR_EK8:1509-02-03:0":{"b": ["معركة ديو البحرية — تفوق البرتغال في المحيط الهندي", "1778d347"], "d": ["لحقت هزيمة ثقيلة، قبالة ديو، بأسطول مالك أياز، الذي كان يحكم المنطقة باسم سلطنة غجرات، بدعم من المماليك، أمام أسطول الحاكم العام البرتغالي فرانسيسكو دي ألميدا الذي كان يحاول إقامة قاعدة إمداد على هذه السواحل. وأكسبت هذه الهزيمة البرتغال تفوقًا بحريًا دائمًا في المحيط الهندي وكسرت القوة البحرية المملوكية الغجراتية؛ وتُعدّ بداية اختلال التوازن الذي شكّل خلفية الصراع في البحر الأحمر والمحيط الهندي الذي ورثه العثمانيون بعد 1517 (الدفاع عن جدة، حصار ديو 1538).", "88e4e561"]},
"OLAYLAR_EK8:1526-01-01:0":{"b": ["تمرد قلندر شاه", "f60f6ca4"], "d": ["بتأثير الضائقة المالية في الأناضول، والاستياء من الترتيبات الإدارية الجديدة، والدعاية الصفوية، اجتمعت حول قلندر شاه عشائر تركمانية كبرى مثل جيجكلي وآق قويونلو وماسادلي وبوزوكلو، وجماعات بقيت من تمرد بابا ذي النون السابق، وبلغت قوة تناهز ثلاثين ألف شخص. وهزم الثوار أولًا بكلربك الروم؛ وبجمع الصدر الأعظم مقبول إبراهيم باشا الجنود ووعده إياهم بحقوقهم تلاشى دعم قلندر، وقُمع التمرد قرب أبلستين، وقُتل قلندر شاه وولي دوندار في يونيو 1527.", "a12c9471"]},
"OLAYLAR_EK8:1554-08-22:0":{"b": ["فتح شهرزور — الاستيلاء على قلعة زلم", "4320d9b8"], "d": ["كُلّف بكلربك بغداد عثمان باشا، أثناء حملة القانوني على نخجوان، بالاستيلاء على منطقة شهرزور؛ ولما توفي صار بالطه جي محمد باشا بكلربك بغداد، فحاصر قلعة زلم، القلعة المركزية للمنطقة، واستولى عليها في 22 أغسطس 1554 (23 رمضان 961). وبذلك دخل حوض شهرزور على السفح الغربي لجبال زاغروس في الإدارة العثمانية وضُمن الاتصال بين بغداد وكردستان؛ وجُعلت المنطقة أولًا سنجقًا وأُعطيت لمراد بك. وفي عام 1563 بنى البكلربك مظفر باشا قلعة غولنبر مركزًا جديدًا للإيالة؛ وستُهدم القلعة عام 1623 بأمر الشاه عباس، وستُعاد إقامتها عام 1638 في عهد خسرو باشا.", "068e1ae8"]},
"OLAYLAR_EK8:1573-01-01:0":{"b": ["اعتناق حاكم خانية قاسم المسيحية وعزله من الخانية", "a1a8eeb9"], "d": ["اتخذ الحاكم الذي كان على رأس الخانية اسم «سيميون (Simeon)» واعتنق المسيحية؛ وعزله الروس عن الخانية مراعين ردة فعل الرعايا المسلمين. وقد أُعلن هذا الشخص بعد وقت قصير على يد إيفان الرهيب حاكمًا اسميًا في موسكو بلقب «الأمير الأعظم للقيصر ولروسيا» (1575) — وهو أبرز تقاطع بين خانية قاسم وعرش موسكو.", "123a7380"]},
"OLAYLAR_EK8:1577-01-01:0":{"b": ["ربط سنجق فزان بطرابلس الغرب — مرزق ومفترق قوافل الصحراء", "2e6554a4"], "d": ["نتيجة لضغط بكلربكية طرابلس الغرب، قبلت فزان، مفترق قوافل الصحراء، ومركزها مرزق، التبعية العثمانية. ووفقًا لمادة «فزان» في موسوعة الإسلام التركية (TDV)، تُركت أسرة أولاد محمد التي تحكم المنطقة حرة في شؤونها الداخلية بشرط دفع الضرائب بانتظام؛ ونُظمت فزان سنجقًا تابعًا لإيالة طرابلس التي فُتحت عام 1551. وبذلك دخلت تجارة العبيد والذهب والجمال على خط طرابلس-مرزق-برنو تحت الرقابة العثمانية. وستنتقل هذه الإدارة غير المباشرة عام 1711 إلى القره مانليين، وعام 1842 إلى تنظيم القضاء المباشر.", "dff1c8b1"]},
"OLAYLAR_EK8:1586-01-01:0":{"b": ["دخول نخجوان وأوردوباد في الإدارة العثمانية", "24d939b3"], "d": ["بعد الاستيلاء على إيروان وجعلها مركز بكلربكية عام 1583، ربطت القوات التي نزلت جنوب شرقي على طول وادي آراس نخجوان وأوردوباد بالإدارة العثمانية؛ وصارت المدينتان سنجقين من سناجق إيالة إيروان المُنشأة حديثًا. ووفقًا لمادة «نخجوان» في موسوعة الإسلام التركية (TDV)، أُقيمت الإدارة العثمانية الدائمة في المدينة لأول مرة أثناء هذه الحرب — فقد كانت المدينة في حملة نخجوان عام 1553 قد أُخذت ولكن نُهبت فقط وتُركت. وبذلك انفتح طريق الجيش بين إيروان وتبريز، وأمكن دخول تبريز في سبتمبر من السنة نفسها. وسيستعيد الشاه عباس نخجوان عام 1603.", "270c0faa"]},
"OLAYLAR_EK8:1603-03-01:0":{"b": ["تمرد دالي حسن باشا وتهدئته ببكلربكية البوسنة", "144f3f2d"], "d": ["بعد وفاة زعيم الجلالية قره يازيجي عبد الحليم عام 1602، تولى أخوه دالي حسن رأس الحركة، فاستفاد من حرية الحركة التي أتاحتها الحروب النمساوية المتواصلة للجماعات الجلالية، فغزا كوتاهية وزحف على أفيون قره حصار. وفي هذه الفترة التي كانت الدولة فيها منشغلة بالجبهتين النمساوية والإيرانية في آن واحد، حُلّت المسألة «بالتي هي أحسن»: فمُنح دالي حسن رتبة الباشوية وبكلربكية البوسنة، وأُنهيت حركة التمرد رسميًا عام 1603.", "22ea1f34"]},
"OLAYLAR_EK8:1609-01-01:0":{"b": ["استيلاء القوات الروسية على مدينة قاسم، أوراز محمد خان", "b3f0bd34"], "d": ["كانعكاس لعصر الاضطرابات (سموتا) في روسيا، حاصرت القوات الروسية مدينة قاسم واستولت عليها وأعملت السيف في معظم أهلها. وكان أوراز محمد، الذي كان على رأس الخانية، مستهدفًا لدعمه ديمتري الكاذب الثاني؛ وقُتل هو أيضًا في العام التالي (1610) بمؤامرة.", "3583477d"]},
"OLAYLAR_EK8:1637-06-18:0":{"b": ["فقدان قلعة آزاق لصالح قوزاق الدون", "ba068b2f"], "d": ["استولى قوزاق الدون على قلعة آزاق، التي حاصروها في 21 أبريل 1637، بعد شهرين؛ وخرجت القلعة، بوابة البحر الأسود الشمالية الشرقية ومفتاح تجارة الدون، لأول مرة من يد العثمانيين. ووفقًا لمادة «آزاق» في موسوعة الإسلام التركية (TDV)، استولى القوزاق على القلعة عام 1637، وصمدوا أمام حصار كبير دام ثلاثة أشهر بقيادة دالي حسين باشا عام 1641، ولم يخلوا القلعة إلا عام 1642 بمجيء خان القرم محمد كراي. وكانت الدولة مشغولة آنذاك بجبهة بغداد؛ وعدم إمكان الاحتفاظ بالقلعة خمس سنوات هو أول شرخ في صفة البحر الأسود «بحيرة عثمانية».", "da9b9fd8"]},
"OLAYLAR_EK8:1657-11-15:0":{"b": ["استرداد ليمنوس وساموثراقي", "c445553b"], "d": ["بعد تحرير بوزجه أدا في 31 أغسطس 1657، وجّه كوبريلي محمد باشا الأسطول شمالًا، واستعاد ليمنوس وساموثراقي اللتين ظلتا ستة عشر شهرًا في يد البندقية. ووفقًا لمادة «ليمنوس» في موسوعة الإسلام التركية (TDV)، كانت الجزيرة قد وقعت في يد البندقية في يوليو 1656، واستُردت في نوفمبر 1657. وبذلك كُسر الحصار البندقي عند مدخل مضيق الدردنيل كسرًا تامًا، وأُمّن من جديد طريق الحبوب إلى إسطنبول؛ وهذا أوضح مكاسب السنة الأولى التي جاء فيها الصدر الأعظم بصلاحيات استثنائية.", "9a57630d"]},
"OLAYLAR_EK8:1688-09-11:0":{"b": ["فقدان كنين للبندقية — سقوط قلعة حدود دالماسيا بعد 166 سنة", "252406b7"], "d": ["في الحرب التي فُتحت على جبهات متعددة بعد هزيمة فيينا عام 1683، تقدمت القوات البندقية إلى دواخل دالماسيا. وسلّم البكلربك محمد باشا كنين، التي حاصرها قائد دالماسيا جيرولامو كورنارو، بعد حصار دام اثني عشر يومًا. وكانت كنين، التي فتحها غازي خسرو بك عام 1522 وظلت 166 سنة في يد العثمانيين، القلعة المفتاحية لخط حدود دالماسيا؛ وفتح فقدانها المنطقة إلى حد كبير أمام البندقية.", "d4aa761c"]},
"OLAYLAR_EK8:1779-04-01:0":{"b": ["استرداد البصرة من الاحتلال الإيراني", "5b10c5c1"], "d": ["البصرة التي استولى عليها صادق خان، أخو كريم خان زند، عام 1776، أُخليت بعد بدء الصراع على العرش في إيران عقب وفاة كريم خان في 2 مارس 1779؛ وعاد صادق خان إلى إيران مدعيًا السلطنة. وبعد أن بقيت المدينة وقتًا قصيرًا في يد عشيرة المنتفق، دخلت من جديد في الإدارة العثمانية. وطلب المتسلم السابق سليمان آغا، العائد من شيراز، ولاية البصرة، وصار والي البصرة وبغداد وشهرزور باسم سليمان باشا الكبير. وعادت تجارة الخليج إلى الرقابة العثمانية؛ وكان جزء من التجارة قد انتقل في سنوات الاحتلال إلى الكويت، ومنذ عام 1778 صار بريد الصحراء كذلك ينطلق من الكويت.", "2f14ff54"]},
"OLAYLAR_EK8:1793-01-01:0":{"b": ["وفاة تيمور شاه وجلوس زمان شاه (الدولة الدرانية)", "c3effdb2"], "d": ["بوفاة تيمور شاه، الذي وطّد البلاد من الداخل أكثر من عشرين سنة، تنازع الإخوة الثلاثة، ولاة قندهار وهراة وكابل، على العرش؛ وصار زمان شاه، والي كابل الذي كانت العاصمة في يده، شاهًا في 20 مايو 1793. وأزمة الوراثة هذه هي البداية الفعلية لعملية تفتت الأسرة.", "4b3d7d19"]},
"OLAYLAR_EK8:1819-11-01:0":{"b": ["آي نوا — إنهاء نظام الكابو التقليدي في هاواي", "0b10e1d8"], "d": ["بعد ستة أشهر من وفاة كاميهاميها الأول، انتهك الملك الجديد ليهوليهو عن عمد، بدعم من أمه كاأهومانو، حظر أكل الرجال والنساء معًا (آيكابو). وأنهى هذا الفعل، المعروف بـ«آي نوا» (الأكل الحر)، رسميًا نظام الكابو التقليدي الديني القانوني؛ وهُدمت المعابد القديمة في الجزر (هيياو) في وقت قصير. وهو أكبر قطيعة دينية سياسية قبل وصول المبشرين الغربيين (1820).", "7f6d4463"]},
"OLAYLAR_EK8:1830-02-03:0":{"b": ["بروتوكول لندن — الاعتراف باستقلال اليونان", "4c7b4b72"], "d": ["اعترف البروتوكول الذي وقعته إنجلترا وفرنسا وروسيا في لندن باليونان دولة مستقلة، متجاوزًا الحكم الذاتي الذي نصت عليه معاهدة أدرنة. أحكامه: تُركت للدولة الجديدة شبه جزيرة المورة وأتيكا وإغريبوز وجزر السيكلاديس؛ ورُسمت الحدود على خط أرتا-فولوس؛ وتقرر دفع تعويض للدولة العثمانية؛ وحُدد شكل حكم الدولة بأنه «ملكية مستقلة». وهذه أول دولة مستقلة تنفصل عن الإمبراطورية، وقد أرست النموذج القانوني لاستقلالات البلقان اللاحقة.", "e8fc6290"]},
"OLAYLAR_EK8:1835-01-01:0":{"b": ["استيلاء عبد الله بن رشيد على إمارة حائل — تأسيس أسرة شمّر (آل رشيد)", "fb513b8a"], "d": ["بسقوط الدرعية على يد قوات محمد علي باشا عام 1818، خرجت منطقة جبل شمّر من السيادة السعودية وبقيت الإمارة في يد أسرة ابن علي. وانتصر عبد الله بن رشيد، الذي كان يدعم إعادة تأسيس السيادة العثمانية، مع أخيه عبيد في الصراع الذي خاضه ضد أسرة ابن علي عام 1835، واستولى على إمارة حائل وأسس سيادة أسرة آل رشيد.", "631e33a9"]},
"OLAYLAR_EK8:1840-10-08:0":{"b": ["إعلان أول دستور مكتوب لهاواي", "401a8a1d"], "d": ["أُعلن أول دستور مكتوب كامل للمملكة؛ وحوّلت هذه الوثيقة، التي قيّدت سلطة الملك وأنشأت مجلسًا تمثيليًا، هاواي إلى ملكية دستورية.", "a32cdab2"]},
"OLAYLAR_EK8:1887-07-06:0":{"b": ["دستور الحربة — تقليص سلطات الملك كالاكاوا", "4953363b"], "d": ["أجبرت مجموعة ميليشيا مسلحة الملك كالاكاوا، بتهديده، على التوقيع على دستور جديد قلّص سلطات المملكة تقليصًا كبيرًا؛ ويُعرف هذا النص بـ«دستور الحربة» (Bayonet Constitution)، وأدخل العرش فعليًا تحت سيطرة النخبة المستوطنة البيضاء.", "cc95eabb"]},
"OLAYLAR_EK8:1893-02-18:0":{"b": ["وفاة جورج توبو الأول وجلوس جورج توبو الثاني (تونغا)", "b56e2b32"], "d": ["بوفاة الملك المؤسس جورج توبو الأول، تولى العرش حفيد حفيده جورج توبو الثاني؛ وأُقيم حفل التتويج في 17 مارس 1893 في نوكوألوفا.", "01fe9fa1"]},
"OLAYLAR_EK8:1893-09-19:0":{"b": ["نيوزيلندا تصبح أول بلد ذاتي الحكم يمنح النساء حق التصويت", "0d277cde"], "d": ["بموجب قانون الانتخابات الجديد الذي وقعه الحاكم اللورد غلاسغو، أصبحت نيوزيلندا أول بلد ذاتي الحكم في العالم يمنح النساء حق التصويت في الانتخابات البرلمانية.", "ba9b7f63"]},
"OLAYLAR_EK8:1894-07-04:0":{"b": ["إعلان جمهورية هاواي", "4346bd5d"], "d": ["حوّل المتآمرون الذين أطاحوا بالملكة ليليوكالاني عام 1893 الحكومة المؤقتة إلى جمهورية رسمية؛ وأُعلن سانفورد دول رئيسًا. واستمر هذا النظام الانتقالي حتى الضم الأمريكي عام 1898.", "d1a76858"]},
"OLAYLAR_EK8:1901-06-11:0":{"b": ["توسع حدود نيوزيلندا لتشمل جزر كوك ونيوي", "d0370a33"], "d": ["وُسّعت حدود نيوزيلندا لتشمل جزر كوك (راروتونغا وأيتوتاكي والجزر الجنوبية وجزر كوك الشمالية) ونيوي؛ وصارت هذه الجزر إقليمًا تابعًا لنيوزيلندا.", "464148bd"]},
"OLAYLAR_EK8:1918-04-05:0":{"b": ["وفاة جورج توبو الثاني وجلوس سالوتي توبو الثالثة (تونغا)", "a3084f3b"], "d": ["توفي جورج توبو الثاني بالسل؛ وأُعلنت ابنته سالوتي، وعمرها 18 سنة، ملكة في اليوم التالي، وأُقيم حفل التتويج في 11 أكتوبر 1918.", "a63672b5"]},
"OLAYLAR_EK8:1920-04-26:0":{"b": ["إعلان جمهورية خوارزم الشعبية", "0a6b79f9"], "d": ["بعد إطاحة خان خيوة عقب ثورة أكتوبر 1917، أُعلنت جمهورية خوارزم الشعبية.", "1934b071"]},
"OLAYLAR_EK8:1920-08-10:0":{"b": ["معاهدة سيفر — نص تقاسم الإمبراطورية", "64980d7b"], "d": ["نص وقعته الحكومة العثمانية مع دول الوفاق وصفّى الإمبراطورية فعليًا. أحكامه: تراقيا الشرقية ومنطقة إزمير لليونان؛ وأُقرّت في شرق الأناضول أرمينيا مستقلة وكردستان ذات حكم ذاتي؛ وتُركت سوريا لفرنسا والعراق وفلسطين لبريطانيا انتدابًا؛ وسُلّمت المضائق إلى لجنة دولية؛ وخُفض الجيش إلى 50.700 فرد، وعادت الامتيازات الأجنبية، ووُضعت المالية تحت رقابة الوفاق. ولم يعترف المجلس الوطني الكبير في أنقرة بالمعاهدة مطلقًا، وأعلن الموقعين عليها خونة للوطن؛ ولم ينفذ النص، وحلّت محله لوزان عام 1923. وهذا هو سبب عدم وجود مقابل له في الخريطة — فسيفر لم تُطبَّق قانونًا قط.", "c9b2648b"]},
"OLAYLAR_EK8:1920-09-02:0":{"b": ["دخول الجيش الأحمر مدينة بخارى — إبعاد آخر أمير، عالم خان، عن العرش", "f8f5bfcf"], "d": ["دخل الجيش الأحمر مدينة بخارى في 2 سبتمبر 1920 وأُبعد آخر أمراء المنغيت، عالم خان، عن العرش. وانسحب الأمير إلى شرق البلاد، إلى دوشنبه، وأدار منها نصف سنة النضال ضد السوفييت؛ واستولى الجيش الأحمر على دوشنبه في 21 فبراير 1921، وانتقل الأمير إلى مناطق أبعد شرقًا ومنها إلى أفغانستان. وأُلغيت الخانية رسميًا في 6 أكتوبر 1920 (انظر جمهورية بخارى الشعبية السوفييتية).", "19580033"]},
"OLAYLAR_EK8:1920-10-08:0":{"b": ["إعلان جمهورية بخارى الشعبية السوفييتية", "ef579627"], "d": ["بعد أن أطاح الجيش الأحمر بإمارة بخارى في 28-31 أغسطس 1920 وهرّب الأمير عالم خان إلى بخارى الشرقية، أُعلنت جمهورية بخارى الشعبية السوفييتية برئاسة فيض الله خوجاييف.", "690bfb2f"]},
"OLAYLAR_EK8:1921-08-14:0":{"b": ["إعلان جمهورية تانو توفا الشعبية استقلالها", "8710ea3d"], "d": ["أُعلن الاستقلال بقيادة الحزب الثوري الشعبي التوفاني؛ وذكرت المادة الأولى من أول دستور أن الدولة تتصرف «في العلاقات الدولية تحت حماية روسيا السوفييتية».", "3c6cec2c"]},
"OLAYLAR_EK8:1921-09-01:0":{"b": ["إقرار الدستور الجديد لجمهورية بخارى الشعبية السوفييتية", "fb17bf39"], "d": ["أُقرّ دستور جديد يسمح، خلافًا للدستور الروسي لعام 1918، بملكية خاصة للأرض والإنتاج ويمنح غير البروليتاريين حق التصويت أيضًا (باستثناء أقارب الأمير المخلوع وكبار ملاك الأراضي).", "91bf1a32"]},
"OLAYLAR_EK8:1921-09-05:0":{"b": ["التحول إلى جمهورية خوارزم الاشتراكية السوفييتية", "14a1d26f"], "d": ["غيّرت البلاد اسمها ووضعها فصارت جمهورية خوارزم الاشتراكية السوفييتية؛ وأُعيد تنظيم البنية الإدارية والقانونية وفق النظام السوفييتي.", "e3e9b939"]},
"OLAYLAR_EK8:1922-03-03:0":{"b": ["بدء حكومة تانو توفا عملها فعليًا", "22ea1516"], "d": ["باشرت الحكومة المشكَّلة بعد أول اجتماع للحزب في فبراير 1922 عملها فعليًا.", "3b3c6c39"]},
"OLAYLAR_EK8:1923-10-12:0":{"b": ["انعقاد أول مجلس خورال كبير في تانو توفا", "80fe15f2"], "d": ["انعقد أول خورال كبير (مجلس الشعب) في البلاد؛ وهو أول اجتماع تمثيلي كبير في مسيرة مأسسة الدولة.", "e8cf06ac"]},
"OLAYLAR_EK8:1924-01-01:0":{"b": ["انتهاء جمهورية خوارزم الاشتراكية السوفييتية وجمهورية بخارى الشعبية السوفييتية بالتحديد القومي — تأسيس جمهوريتي أوزبكستان وتركمانستان الاشتراكيتين السوفييتيتين", "e8c8ab4f"], "d": ["بقرار «التحديد القومي» السوفييتي (natsionalno-territorialnoe razmezhevanie) أُلغيت جمهورية خوارزم الاشتراكية السوفييتية وجمهورية بخارى الشعبية السوفييتية؛ وقُسمت أراضيهما بين جمهوريتي أوزبكستان وتركمانستان الاشتراكيتين السوفييتيتين المؤسستين حديثًا (شرق خيوة لأوزبكستان وغربها لتركمانستان). ومادة `harizm` في TDV: «في عام 1924 تُركت الأجزاء الشرقية من خانية خيوة لجمهورية أوزبكستان الاشتراكية السوفييتية، والجانب الغربي لجمهورية تركمانستان الاشتراكية السوفييتية.» — وهي لا تعطي إلا السنة.", "58053c38"]},
"OLAYLAR_EK9:1427-01-01:0":{"b": ["بيع العلايا إلى السلطان المملوكي برسباي", "c8bd35f2"], "d": ["كانت العلايا، التي استولى عليها القره مان أوغلو مجد الدين محمود بك عام 1293، قد صارت إمارة مستقلة يحكمها فرع من القره مان أوغلو؛ ويسجل ابن بطوطة أن الإدارة كانت عام 1333 بيد القره مان أوغلو يوسف بك. وباع قرمان بن صافجي بك المدينة عام 1427 للسلطان المملوكي برسباي مقابل خمسة آلاف ذهب، ودخلت العلايا في الإدارة المملوكية. وبذلك صار هذا الميناء المتوسطي الحيوي عقبة في يد المماليك على طريق العثمانيين المنفتح نحو الجنوب؛ وحين حاصرها كدك أحمد باشا عام 1471 سلّمها آخر الأمراء قلج أرسلان.", "9be5efe7"]},
"OLAYLAR_EK9:1741-06-12:0":{"b": ["انتزاع طبرقة من الجنويين — نهاية امتياز لوميليني للمرجان", "b1f33eb5"], "d": ["بعد المعاهدة التي أبرمها شارلكان مع باي تونس عام 1544، استقرت أسرة لوميليني الجنوية في جزيرة طبرقة واحتفظت بامتياز المرجان مئتي سنة؛ وبقيت الجزيرة مركزًا تجاريًا مسيحيًا في وسط تونس العثمانية. ولما علم علي باشا من الأسرة الحسينية بمحاولة الأسرة التخلص من الجزيرة أرسل قوة واستولى على الجزيرة في 12 يونيو 1741؛ ونُقل نحو ألف وخمسمئة مسيحي إلى تونس. وصارت طبرقة بعد هذا التاريخ تحت إدارة أوجاق تونس.", "93c8bd7b"]},
"OLAYLAR_EK9:1798-07-21:0":{"b": ["معركة الأهرام واستيلاء الفرنسيين على القاهرة", "3ddd6b96"], "d": ["سار نابليون من الإسكندرية جنوبًا على طول النيل، وفي 21 يوليو 1798 واجه في إمبابة قبالة الجيزة فرسان المماليك بقيادة مراد بك. وكسرت المشاة الفرنسية المصطفة على شكل مربع هجمات الفرسان؛ وتفرق جيش المماليك، وسلمت القاهرة بعد يومين دون مقاومة. وانسحب مراد بك إلى صعيد مصر وإبراهيم بك إلى سوريا. وأقام الفرنسيون في القاهرة ديوانًا وحاولوا إدارة الشؤون بأيدي العلماء؛ ووقع ثورتان كبريان في القاهرة في أكتوبر 1798 ومارس 1800.", "ad9a3113"]},
"OLAYLAR_EK9:1799-03-18:0":{"b": ["حصار نابليون لعكا — إيقاف الحملة على سوريا", "d2a947ad"], "d": ["زحف نابليون إلى سوريا في أوائل عام 1799 يريد تشتيت القوات التي أعدها العثمانيون لاسترداد مصر؛ وأخذ العريش في 18 فبراير ويافا في مارس، وحاصر عكا في 18 مارس 1799. وكسر دفاع أحمد باشا الجزار ودعم الأميرال الإنجليزي سيدني سميث من البحر الحصار شهرين؛ ولم تُتجاوز الأسوار لأن مدافع الحصار قد استولي عليها في البحر. وانسحب نابليون في مايو، وصارت هذه الهزيمة أقصى نقطة بلغها الاحتلال الفرنسي.", "288b9bd9"]},
"OLAYLAR_EK9:1832-11-22:0":{"b": ["تأسيس دولة الأمير عبد القادر — تمركز المقاومة في غرب الجزائر", "9e482383"], "d": ["التفت المقاومة التي تفتتت بعد سقوط الجزائر حول عبد القادر الشاب، ابن الشيخ القادري محيي الدين؛ وفي 22 نوفمبر 1832 بايعه رؤساء القبائل قرب معسكر بلقب «أمير المؤمنين». وكان ما أقامه دولة منظمة لا تحالف قبائل: ففيها دار سكة ومصنع بارود ونظام ضرائب وعاصمة في تاقدمت. واعترفت فرنسا رسميًا بسيادته بمعاهدة التافنة عام 1837. ولم يلتجئ عبد القادر إلى العثمانيين بل إلى سيادة سلطان المغرب عبد الرحمن؛ أي إن هذه الأراضي ليست تابعة للعثمانيين بعد عام 1832. واستسلم في 23 ديسمبر 1847، وأعلنت الدولة العثمانية في العام نفسه انتهاء حقوقها في الجزائر.", "ee2bb181"]},
"OLAYLAR_EK9:1837-10-13:0":{"b": ["سقوط قسنطينة — نهاية بايلك شرق الجزائر", "159fed36"], "d": ["بعد سقوط الجزائر عام 1830 لم ينحل بكلربكية الشرق: فواصل آخر باي، أحمد، إدارته في قسنطينة وأعلن أنه يتصرف باسم العثمانيين. وانتهت حملة الفرنسيين الأولى عام 1836 بهزيمة؛ وحاصرت الحملة الثانية المدينة في 6 أكتوبر 1837، وقُتل القائد دامريمون بنيران المدافع في 12 أكتوبر، وفي 13 أكتوبر اقتُحمت الأسوار وأُخذت المدينة شارعًا شارعًا. وانسحب أحمد باي إلى الجبال ولم يستسلم إلا عام 1848. وهذا التاريخ هو النهاية الفعلية للإدارة العثمانية التركية التي دامت ثلاثة قرون في شرق الجزائر.", "41606785"]},
"OLAYLAR_EK9:1840-01-01:0":{"b": ["فتح منطقة التاكا وتأسيس كسلا", "cc3e0631"], "d": ["ربط حاكم السودان أحمد باشا أبو ودان عام 1840 منطقة التاكا بين نهري عطبرة والقاش بالإدارة المصرية، وأسس مدينة كسلا معسكرًا عسكريًا. وصارت المدينة مركز مديرية تسيطر على طريق القوافل بين سنار وسواكن وعلى حزام الحدود الحبشية.", "b7898c36"]},
"OLAYLAR_EK9:1841-01-01:0":{"b": ["الاحتلال الفرنسي لمعسكر — فقدان عاصمة عبد القادر", "bd363c05"], "d": ["تغيرت الاستراتيجية الفرنسية بتولي بيجو الولاية عام 1841: فبدل التشبث بالساحل صار احتلال المدن الداخلية واحدة بعد أخرى. واستولت الأعمدة المتحركة الخارجة من وهران ومستغانم والمدية على مراكز دولة عبد القادر المنظمة؛ وكانت معسكر، العاصمة الحقيقية بدار سكتها ومصنع بارودها ومخازن حبوبها، أهمها جميعًا. وتخلى الأمير بعد ذلك عن إقامة مركز ثابت وحوّل جيشه إلى مخيم متنقل يُسمى «السمالة» (smala).", "b5e65ffc"]},
"OLAYLAR_EK9:1843-01-01:0":{"b": ["احتلال وادي الشلف وتنس — تأسيس أورليانفيل", "e1eeeb68"], "d": ["لكي يتمكن الفرنسيون من ملاحقة عبد القادر، أسسوا في أبريل 1843 وسط وادي الشلف مدينة جديدة اسمها أورليانفيل؛ واحتُل في العام نفسه ميناء تنس على الساحل. وبذلك دخل الممر الداخلي بين الجزائر ووهران في السيطرة الفرنسية وطُوّقت المقاومة في جبال الظهرة. وفي 16 مايو من العام نفسه عُثر مصادفةً على مخيم عبد القادر المتنقل «السمالة» وشُتّت.", "67e95822"]},
"OLAYLAR_EK9:1843-06-12:0":{"b": ["إقامة المعسكر المحصّن في سيدي بلعباس", "fb33ec29"], "d": ["أصدر بيجو في 12 يونيو 1843 أمرًا للجنرال بيدو بإقامة معسكر محصّن بخندق وأسوار في سيدي بلعباس؛ وبدأ البناء في 18 يونيو، واستقر فيه في نوفمبر من العام نفسه طابور من الفيلق الأجنبي. وصار المعسكر قاعدة دائمة تسيطر على السهل الداخلي بين وهران وتلمسان.", "aab075d5"]},
"OLAYLAR_EK9:1844-01-01:0":{"b": ["انتقال ندرومة والحزام الحدودي مع المغرب إلى السيطرة الفرنسية", "61d821f3"], "d": ["بعد انسحاب عبد القادر إلى المغرب عام 1843، دخلت ندرومة وساحل الترارة شمال غرب تلمسان في السيطرة الفرنسية. وأوقعت معركة إيسلي في 14 أغسطس 1844 الجيش المغربي في الهزيمة، ورُسمت الحدود بين البلدين باتفاقية للا مغنية في 18 مارس 1845؛ وبقيت ندرومة على الجانب الجزائري من هذا الخط.", "0456a776"]},
"OLAYLAR_EK9:1852-12-04:0":{"b": ["سقوط الأغواط (لغواط) — فتح باب الصحراء", "b161b32c"], "d": ["حاصر الجنرال بيليسييه الأغواط في 21 نوفمبر 1852 بقوة من ستة آلاف رجل، وسقطت المدينة في 4 ديسمبر بهجوم دموي. وكانت الأغواط مدينة واحة تمسك بالممر بين التل والصحراء؛ وفتح سقوطها التقدم الفرنسي نحو طرق القوافل الصحراوية ومهّد لفرض الضريبة على اتحاد ميزاب في غضون سنة.", "049b3d0a"]},
"OLAYLAR_EK9:1872-01-01:0":{"b": ["ضم منطقة البوغوس (كرن) إلى مصر", "b2ab83ce"], "d": ["ربط فيرنر مونزنغر باشا، والي ولاية «السودان الشرقي وساحل البحر الأحمر» التي أسسها الخديوي إسماعيل على الساحل الغربي للبحر الأحمر، عام 1872 منطقة البوغوس التي يسكنها شعب البلين ومركزها كرن بمصر. وكان ذلك أكثر تقدم مصر دوامًا على حافة الهضبة الحبشية، وأطلق نزاعًا حدوديًا مع الحبشة دام اثنتي عشرة سنة.", "e52afaf4"]},
"OLAYLAR_EK9:1874-11-02:0":{"b": ["ضم سلطنة دارفور إلى مصر — دخول الزبير باشا الفاشر", "f41268ed"], "d": ["هزم الزبير رحمة باشا، الذي تقوّى بتجارة العاج والرقيق، بقوات جهزها ببنادق ريمنغتون، جيش الفور في منواشي في 25 أكتوبر 1874؛ وقُتل السلطان إبراهيم في المعركة. ودخل الزبير الفاشر في 2 نوفمبر دون قتال، وانتهى فعليًا حكم أسرة كيرا الذي دام منذ عام 1603. وبذلك أُلحقت دارفور بأقاليم السودان في مصر محمد علي؛ لكن مقاومة أسرة كيرا في الجبال استمرت حتى عام 1891.", "b9679678"]},
"OLAYLAR_EK9:1882-01-01:0":{"b": ["ضم واحات ميزاب (غرداية)", "9372959f"], "d": ["كانت مدن ميزاب الإباضية قد قبلت عام 1852 أن تدفع الضريبة لفرنسا لكنها احتفظت بإدارتها الداخلية؛ وبعد ثلاثين سنة، في عام 1882، ضُمت المنطقة مباشرة إلى الأراضي الفرنسية وربطت غرداية بالإدارة العسكرية. وبذلك انتهى قانونيًا آخر حزام ذاتي الحكم في شمال الصحراء.", "8ced1a9f"]},
"OLAYLAR_EK9:1882-07-11:0":{"b": ["قصف الإسكندرية والإنزال البريطاني", "18d57bf8"], "d": ["لما سيطرت حركة الضباط بقيادة عرابي باشا على الخديوي، تدخلت إنجلترا بذريعة أمن طريق السويس. وقصف أسطول الأميرال سيمور الطوابي الساحلية للإسكندرية في 11-12 يوليو 1882؛ وبعد الحريق والنهب اللذين وقعا في المدينة أنزلت القوات البريطانية جنودها في 15 يوليو. ولم تستطع الدولة العثمانية، وهي صاحبة السيادة قانونًا على ولاية من ولاياتها، أن تمنع هذه العملية، وتركت دعوة المشاركة في التدخل دون جواب. وهكذا اتُّخذت الخطوة الأولى من احتلال سيدوم اثنتين وثلاثين سنة.", "d828a872"]},
"OLAYLAR_EK9:1882-09-13:0":{"b": ["معركة التل الكبير — تشتت جيش عرابي", "8e38fecf"], "d": ["أنزل وولسلي قواته عبر قناة السويس في الإسماعيلية وسار بها عبر الصحراء، وفاجأ خنادق المصريين في التل الكبير عند فجر 13 سبتمبر 1882؛ وانتهت المعركة في ساعة. واستسلم عرابي في اليوم التالي ودخلت الفرسان البريطانية القاهرة في اليوم نفسه. ومنذ هذا التاريخ انتقلت شؤون مصر المالية والعسكرية والخارجية فعليًا إلى الرقابة البريطانية؛ واستمرت السيادة العثمانية قانونيًا حتى عام 1914.", "a399d51c"]},
"OLAYLAR_EK9:1883-06-08:0":{"b": ["اتفاقية المرسى (لا مارسا) — اكتمال الحماية على تونس", "71338640"], "d": ["كانت معاهدة باردو (قصر السعيد) المؤرخة في 12 مايو 1881 قد تركت الشؤون الخارجية لتونس لفرنسا لكنها تركت الإدارة الداخلية للباي؛ وبعد سنتين، أخضعت اتفاقية المرسى الموقعة في 8 يونيو 1883 الإصلاحات المالية والإدارية أيضًا للرقابة الفرنسية وأتمّت الحماية. واستمرت الدولة العثمانية في التمسك بدعواها السيادة على تونس ولم تعترف بالاحتلال قط، لكنها لم تستطع اتخاذ خطوة مضادة فعلية. وهكذا دخلت تونس، أوجاق العثمانيين منذ عام 1574، رسميًا في الحماية الفرنسية.", "c04210c4"]},
"OLAYLAR_EK9:1883-11-05:0":{"b": ["كارثة شيكان — إبادة جيش هكس باشا", "a0e08986"], "d": ["كان هكس باشا، الضابط البريطاني المتقاعد الذي قاد قوة مصرية من نحو عشرة آلاف شخص أُرسلت من القاهرة، يتقدم في صحراء كردفان دون ماء ودون أدلاء، فطوّقته قوات المهدي في شيكان في 5 نوفمبر 1883 وأُبيد الجيش تقريبًا بالكامل. وكسرت هذه الكارثة العمود الفقري للإدارة المصرية في السودان: ففي غضون شهر استسلمت دارفور وبحر الغزال، وانتقلت كردفان كلها إلى المهدي. ومن هنا يبدأ الطريق المؤدي إلى سقوط الخرطوم.", "c78a6d57"]},
"OLAYLAR_EK9:1883-12-23:0":{"b": ["انتقال دارفور إلى قوات المهدي — استسلام سلاطين باشا", "6d8992d4"], "d": ["كان الحاكم العام لدارفور سلاطين باشا يواجه منذ عام 1882 تمرد قبيلة الرزيقات المهدوي؛ ولما ظن أن هزائم جنوده تُعزى إلى كونه مسيحيًا، أسلم علنًا عام 1883 وتسمى عبد القادر. وبعد إبادة جيش هكس باشا في كردفان في نوفمبر 1883 لم يعد للمقاومة معنى، فاستسلم للأمير مديبو في 23 ديسمبر 1883. وسارت المخافر المصرية الصغيرة في دارفور في الطريق نفسه سريعًا؛ وانتهت الإدارة التركية المصرية التي دامت عشر سنوات.", "85dcfe97"]},
"OLAYLAR_EK9:1884-01-01:0":{"b": ["انتقال زيلع وساحل الصومال إلى الإدارة البريطانية", "1d649502"], "d": ["لما انهارت حاميات مصر في السودان والبحر الأحمر بتمرد المهدي، اضطرت القاهرة إلى إخلاء مخافرها النائية على الساحل الحبشي. وأنزلت الإدارة البريطانية في عدن جنودًا في زيلع وبربرة عام 1884؛ وفي العام التالي وُقّعت اتفاقيات الحماية مع رؤساء القبائل الصومالية فتأسست الصومال البريطاني. وبذلك خرجت زيلع، التابعة لإيالة الحبشة منذ عام 1559، من اليد.", "3c41ddf4"]},
"OLAYLAR_EK9:1884-01-15:0":{"b": ["استسلام حامية الفاشر للمهديين", "68f0760d"], "d": ["بعد استسلام سلاطين في 23 ديسمبر 1883 قاومت الحامية المصرية في قلعة الفاشر أيضًا. وبعد أن فقدت الحامية الآبار في حصار دام سبعة أيام استسلمت في 15 يناير 1884؛ وسُلّمت الأسلحة وانتقلت القلعة إلى المهديين.", "18287ab0"]},
"OLAYLAR_EK9:1884-06-03:0":{"b": ["معاهدة هيويت (عدوة) — ترك البوغوس للحبشة", "0de1b701"], "d": ["لما حاصر تمرد المهدي الحاميات المصرية في السودان، وقّعت إنجلترا في 3 يونيو 1884 في عدوة معاهدة مع يوحنس الرابع للحصول على مساعدة الحبشة. وتعيد المادة الثانية من المعاهدة البوغوس إلى الحبشة، وفي المقابل تسهّل الحبشة إجلاء الحاميات المحاصَرة عبر مصوع. وبذلك خرجت كرن من الإدارة المصرية التي دامت اثنتي عشرة سنة؛ وبعد خمس سنوات ستُضم المنطقة إلى إريتريا الإيطالية.", "b7e73617"]},
"OLAYLAR_EK9:1896-09-23:0":{"b": ["استرداد دنقلة — بدء حملة امتداد النيل", "f63aa14f"], "d": ["بعد هزيمة الإيطاليين في عدوة، سيّرت إنجلترا الجيش المصري بقيادة كتشنر جنوبًا على طول النيل. وحُلّت مشكلة الإمداد مع تقدم السكة الحديدية في الصحراء، واستُردت ولاية دنقلة في 23 سبتمبر 1896. وانتهى هنا حكم المهدية الذي دام إحدى عشرة سنة؛ وستستمر الحملة سنتين أخريين حتى بلوغ أم درمان.", "ef465d34"]},
"OLAYLAR_EK9:1898-09-02:0":{"b": ["معركة أم درمان — سقوط الدولة المهدية", "28dff7b2"], "d": ["شتت جيش كتشنر الإنجليزي المصري، المجهز بالمدفعية والرشاشات، قوات الخليفة عبد الله التعايشي في ساعات أمام أم درمان في 2 سبتمبر 1898. ودُخلت الخرطوم في اليوم التالي، ورُفع العلم في القصر الذي قُتل فيه غوردون قبل ثلاث عشرة سنة. وسقطت عاصمة الدولة المهدية؛ وقُتل الخليفة في عملية الملاحقة في أواخر 1899. وتنتقل السيادة الفعلية في هذا التاريخ — أما 19 يناير 1899 فهو الاتفاق الذي أسس الإطار القانوني للإدارة.", "ae944d9d"]},
"OLAYLAR_EK9:1899-01-19:0":{"b": ["اتفاقية الحكم الثنائي — الإدارة المشتركة الإنجليزية المصرية للسودان", "8033c688"], "d": ["ربطت الاتفاقية الموقعة في القاهرة بعد أربعة أشهر من أم درمان السودان، باسم «السودان الأنجلو-مصري»، بإدارة مشتركة للدولتين: يُرفع العلمان معًا، ويعيّن الخديوي الحاكم العام بموافقة إنجلترا. وفي التطبيق كانت الإدارة بيد الإنجليز تمامًا. ولم تكن الدولة العثمانية طرفًا في الاتفاقية ولم تعترف بها، متمسكةً بأن حقوقها في السودان تعود إليها عبر مصر؛ لكنها بقيت فعليًا خارج الأمر.", "c642933f"]},
"OLAYLAR_EK9:1911-10-08:0":{"b": ["إنزال إيطالي في طبرق — أول احتلال في طرابلس الغرب", "44780018"], "d": ["أعلنت إيطاليا الحرب في 29 سبتمبر 1911، وفرض أسطولها الحصار على الساحل في 25-26 سبتمبر. وكانت أول عملية برية في طبرق في 8 أكتوبر: فانسحبت الحامية العثمانية الصغيرة إلى الداخل واحتُل الميناء دون قتال. وكانت طبرق أقرب ميناء عثماني إلى الحدود المصرية؛ وفتح سقوطها الجناح الشرقي لبرقة وسهّل زحف القوات الإيطالية غربًا على طول الساحل.", "fa489107"]},
"OLAYLAR_EK9:1911-10-09:0":{"b": ["استسلام مدينة طرابلس للإيطاليين", "785091ad"], "d": ["استسلمت طرابلس في 9 أكتوبر 1911 بعد ثلاثة أيام من القصف. وبدلًا من الدفاع عن المدينة اختارت القوات العثمانية الانسحاب إلى العزيزية وغريان وتنظيم المقاومة في الداخل؛ وهذه المقاومة، التي شارك فيها أنور ومصطفى كمال بك، حبست الإيطاليين في الشريط الساحلي حتى نهاية الحرب. أي إن داخل الولاية بقي تحت السيطرة العثمانية رغم سقوط المدينة.", "7deeaf70"]},
"OLAYLAR_EK9:1911-10-16:0":{"b": ["فقدان درنة بالإنزال الإيطالي", "f014c741"], "d": ["بعد طبرق جاء دور درنة، ثاني موانئ برقة؛ فاحتُلت المدينة في 16 أكتوبر 1911. وكانت الهضبة حول درنة المنطقة التي بلغت فيها الطريقة السنوسية أعلى كثافة، وأبقى المجاهدون الذين اجتمعوا بنداء الشيخ أحمد الشريف للجهاد الإيطاليين محاصَرين حول الميناء. وظل الاحتلال محصورًا في المدينة ولم يتمكن من الامتداد إلى ظهيرها.", "b6ada646"]},
"OLAYLAR_EK9:1911-10-21:0":{"b": ["إنزال إيطالي في بنغازي — فقدان مركز سنجق برقة", "f9183c40"], "d": ["احتُلت بنغازي، مركز برقة، في 21 أكتوبر 1911 بالإنزال الرابع والأهم على الساحل. وهكذا كانت إيطاليا، بعد ثلاثة أسابيع من إعلان الحرب، تمسك بجميع الموانئ الكبرى لولاية طرابلس الغرب (طرابلس وطبرق ودرنة وبنغازي)؛ لكنها لم تستطع التوغل في ظهير أي منها. وانقضت سنة الحرب المتبقية في هجمات عقيمة من هذه النقاط الأربع على الساحل نحو الداخل.", "6181e67f"]},
"OLAYLAR_EK9:1911-11-05:0":{"b": ["مرسوم الضم الإيطالي من جانب واحد", "cfe3f9c2"], "d": ["أصدرت إيطاليا، والحرب مستمرة، مرسومًا في 5 نوفمبر 1911 أعلنت فيه ضم طرابلس الغرب وبرقة. ولم تعترف الدولة العثمانية بذلك واستمرت الحرب سنة أخرى؛ ولم يكتسب الضم الصلاحية القانونية إلا بمعاهدة أوشي في 18 أكتوبر 1912. ولذلك لا يغيّر المرسوم لون العثمانيين في الخريطة — فالملكية القانونية للعثمانيين حتى عام 1912، وتُعرض السيطرة الإيطالية احتلالًا مخططًا.", "23668758"]},
"OLAYLAR_EK:1300-01-01:0":{"b": ["الاستيلاء على كوبروحصار والتمهيد لتأسيس ينيشهير", "39abff03"], "d": ["بإسقاط حصون الممر بين بورصة وإزنيق وُضع أساس المقر المتقدم الذي سيطوّق المدينتين.", "72fa9808"]},
"OLAYLAR_EK:1301-01-01:0":{"b": ["تأسيس ينيشهير", "d3275837"], "d": ["أُنشئ أول مستوطنة حامية عثمانية منتظمة لإدارة حصاري بورصة وإزنيق؛ وفيها وُلد أورخان غازي.", "39c98a4b"]},
"OLAYLAR_EK:1302-08-01:0":{"b": ["الحصار الأول لإزنيق وفتح مرمرجق", "cdca2349"], "d": ["حوصرت إزنيق للمرة الأولى لكنها لم تسقط (الفتح النهائي عام 1331)؛ وأُخذت قلعة مرمرجق القريبة منها في هذه الأثناء.", "31c4c65f"]},
"OLAYLAR_EK:1305-06-01:0":{"b": ["حملة الوحدات القطلانية في الأناضول", "4fd940d5"], "d": ["حقق الفوج القطلاني الذي استأجره البيزنطيون لوقف التقدم التركي نجاحات مؤقتة لكنه لم يدم؛ وبانسحابه تسارع تقدم إمارات الثغور.", "89381e71"]},
"OLAYLAR_EK:1313-01-01:0":{"b": ["إسلام كوسه ميخال وانضمامه إلى العثمانيين", "ca0d86e1"], "d": ["أسلم تكفور هارمانقايا كوسه ميخال وانضم إلى عثمان غازي مع قلعته ورجاله؛ وصار أول قائد عثماني من أصل بيزنطي.", "327b4cdc"]},
"OLAYLAR_EK:1320-01-01:0":{"b": ["تسلّم أورخان بك الإدارة الفعلية", "6dadbefc"], "d": ["انتقلت القيادة والإدارة الفعليتان لحصار بورصة والحملات إلى ابنه أورخان بك بسبب شيخوخة عثمان غازي ومرضه (أما الجلوس الرسمي على العرش فكان عام 1326).", "280c6e0d"]},
"OLAYLAR_EK:1321-01-01:0":{"b": ["حصار ميناء مودانيا", "9aa4520c"], "d": ["قُطع الميناء الذي كان يمدّ بورصة من البحر، فبدأ المشهد الأخير من الحصار الطويل.", "97d6f814"]},
"OLAYLAR_EK:1321-04-01:0":{"b": ["الاستيلاء على مودانيا", "0a623368"], "d": ["أُخذت مودانيا ميناء بورصة فانقطعت صلة المدينة بالبحر؛ ودخل حصار بورصة مرحلة الخنق.", "c13020d5"]},
"OLAYLAR_EK:1323-01-01:0":{"b": ["انضمام يالوفا وقره مورسل", "133cb07a"], "d": ["أُخذت البلدات المينائية على الساحل الجنوبي للخليج لإتمام حصار بورصة.", "6588050d"]},
"OLAYLAR_EK:1324-01-01:0":{"b": ["فتح آق يازي وجزيرة إمرالي", "d041b0c8"], "d": ["أُخذت آق يازي شمال سقاريا؛ وبالاستيلاء على جزيرة إمرالي صار العثمانيون لأول مرة مجاورين لجزيرة مرمرة.", "591424a4"]},
"OLAYLAR_EK:1324-03-01:0":{"b": ["فتح جمليك (كيوس) وأرموتلو", "682d3bac"], "d": ["قُطع آخر اتصال بحري لبورصة، فصارت المدينة مهيأة للاستسلام عام 1326.", "c2b80b4a"]},
"OLAYLAR_EK:1326-01-01:0":{"b": ["آقجة قوجه يستولي على قنديرة وما حولها", "341bb97e"], "d": ["استولى آقجة قوجه، أحد أمراء الثغور لدى أورخان غازي، على قنديرة وما حولها نحو عام 1326 وهو يشن الغارات على ناحية إزميت من مقره غرب بحيرة صبنجة. وكانت إزميت ما تزال بيد البيزنطيين؛ ولن تسقط المدينة إلا عام 1337.", "ed042ad1"]},
"OLAYLAR_EK:1328-01-01:0":{"b": ["آقجة قوجه يأخذ أيدوس وحصن سمندرة", "ce4daa8a"], "d": ["بعد أخذ قنديرة، أخذ آقجة قوجه مع قونورالب وغازي عبد الرحمن قلعة أيدوس قرب قارتال، ثم حصن سمندرة إلى شمالها؛ وأُعطيت ناحية سمندرة له ملكًا. وتوفي آقجة قوجه قرب قنديرة عام 1328؛ وأُعطيت إمارة الثغر هذه المنطقة للأمير مراد.", "f2ef1bde"]},
"OLAYLAR_EK:1330-01-01:0":{"b": ["التحالف العثماني الآيدينلي الصاروخاني", "9df6bb74"], "d": ["تحركت ثلاث إمارات معًا ضد البيزنطيين؛ وأنهك أسطول عمر بك الآيدينلي البيزنطيين على جبهة ثانية بغاراته على سواحل تراقيا.", "32ca49ea"]},
"OLAYLAR_EK:1346-06-01:0":{"b": ["زواج أورخان غازي من تيودورا: التحالف البيزنطي", "9b67a590"], "d": ["تزوج أورخان غازي، الذي دعم كانتاكوزينوس في الصراع على العرش البيزنطي، من ابنته تيودورا؛ وأتاح هذا التحالف للقوات العثمانية التعرف عن قرب على الروملي.", "4f8f52d9"]},
"OLAYLAR_EK:1354-08-01:0":{"b": ["الاستيلاء على أنقرة", "49bf1f6d"], "d": ["دخلت أنقرة، التي كانت تحت إدارة الأخيّة، تحت الإدارة العثمانية؛ وانفتح طريق وسط الأناضول. الأماكن الأخرى التي انضمت في التاريخ نفسه: سيفريحصار، تشانقري.", "eec5d13e"]},
"OLAYLAR_EK:1357-01-01:0":{"b": ["تقدم سليمان باشا في تراقيا: مالقرة وإبسالا وتكيرداغ", "fb31cf02"], "d": ["بعد إقامة رأس الجسر في غاليبولي خرج سليمان باشا شمالًا من شبه الجزيرة فأخذ خطوة خطوة السهل بين ساحل مرمرة ومصب مريج. وهكذا شكّلت مالقرة وإبسالا وردستو (تكيرداغ) ممرًّا متصلًا يربط غاليبولي بوادي مريج. ولم يكن ممكنًا السير على أدرنة قبل إقامة هذا الممر؛ وسيواصل لالا شاهين وحاجي إلبكي التقدم الذي توقف بوفاة الأمير المفاجئة عام 1357.", "721cac95"]},
"OLAYLAR_EK:1357-08-01:0":{"b": ["اختطاف الأمير خليل", "b52ac3d7"], "d": ["اختطف قراصنة فوتشا خليل، الابن الصغير لأورخان غازي؛ وشغلت أزمة الفدية العلاقات العثمانية البيزنطية سنوات.", "812e3cb6"]},
"OLAYLAR_EK:1360-01-01:0":{"b": ["قطع طرق المدد عن أدرنة: قلاع جورلو ولولة برغاز وبابا إسكي وكشان", "8e8ad485"], "d": ["أرسل الأمير مراد، الذي استأنف حملة الفتح بعد إنقاذ خليل، المغيرين حتى مشارف إسطنبول لعزل أدرنة عن المدد القادم من الخارج. وأُخذت قلاع جورلو ولولة برغاز وبابا إسكي على طريق إسطنبول – أدرنة، وكشان عند مفترق الطرق في جنوب تراقيا. وجاء استسلام أدرنة بعد إتمام حلقة الحصار هذه.", "fb171002"]},
"OLAYLAR_EK:1361-01-01:0":{"b": ["الاستيلاء على ديديموتيخون — فتح وادي مريج", "b59aee83"], "d": ["أُخذت ديديموتيخون، القلعة المفتاحية لوادي مريج؛ وبذلك انفتح الطريق إلى فتح أدرنة. ولم يكن ممكنًا السير على أدرنة قبل إتمام الممر الممتد شمالًا من غاليبولي، ولذلك تسبق القلعة أدرنة في ترتيب فتوح الروملي. وصارت المدينة مدة مقرًّا للسلاطين في الروملي. وأخضعت القوات التي أخذت ديديموتيخون، بعدها، منطقة مريج الوسطى كلها مع قلاع صغيرة مثل كوليلي بورغاز (بيثيون).", "88f995b6"]},
"OLAYLAR_EK:1366-08-01:0":{"b": ["فقدان غاليبولي (الحملة الصليبية السافوية)", "00e7e415"], "d": ["أخذ أسطول أميديو السافوي، ابن عم الإمبراطور البيزنطي، غاليبولي وسلّمها إلى البيزنطيين؛ وظل رأس الجسر العثماني في الروملي يُدار عشر سنوات من الجهة المقابلة للمضيق. المواطن الأخرى التي خرجت من اليد في التاريخ نفسه: جمبي.", "b0c24ccd"]},
"OLAYLAR_EK:1371-09-26:0":{"b": ["معركة جرمن — السيطرة على وادي مريج", "cd738d8d"], "d": ["شُتّت جيش الأمراء الصرب في غارة ليلية؛ وبدأ الأمراء المحليون الصرب والبلغار في مقدونيا والرودوب يدفعون الجزية للعثمانيين واحدًا بعد آخر — وهي بداية موجة التبعية لا الفتح المباشر. وتُروى هذه المعركة في الرواية العثمانية أيضًا باسم «صرب سندغي» وفي سنة 1364، بوصفها الغارة الليلية التي شنها حاجي إلبكي على الجيش الصليبي الذي جاء لاستعادة أدرنة؛ ويبيّن TDV أن ذلك التاريخ خاطئ وأن الروايتين تتعلقان بالمعركة نفسها.", "7b2779cd"]},
"OLAYLAR_EK:1372-06-01:0":{"b": ["فتح فيليبه وإسكي زاغرا", "e780c9ae"], "d": ["أُخذت فيليبه في أعلى وادي مريج وإسكي زاغرا إلى شمالها؛ وفُرضت الجزية على القيصرية البلغارية. وبقي طريق تتارباظارجق وإحتيمان بين فيليبه وصوفيا بيد الأمراء المحليين الذين صاروا تابعين بعد جرمن.", "b8131db8"]},
"OLAYLAR_EK:1373-05-01:0":{"b": ["بيزنطة التابعة: يوحنا الخامس في جيش مراد الأول (نتيجة انتصار جرمن 1371)", "13ffe568"], "d": ["بحسب TDV، بعد انتصار جرمن (مريج) في 26 سبتمبر 1371 اعترفت الإمبراطورية البيزنطية بالسيادة العثمانية، وقبلت دفع الجزية والخدمة في الجيش العثماني، فصارت دولة تابعة. وبهذا الالتزام انضم الإمبراطور يوحنا الخامس عام 1373 إلى جيش مراد الأول؛ وثار ابنه أندرونيكوس الرابع، الذي تركه في إسطنبول حينئذ، على أبيه مع الأمير ساوجي بك في بورصة.", "3fe5b636"]},
"OLAYLAR_EK:1376-09-01:0":{"b": ["استعادة غاليبولي", "5f96c0a5"], "d": ["أعاد أندرونيكوس الرابع، الذي نال الدعم العثماني في الصراع البيزنطي على العرش، غاليبولي في المقابل؛ وأُعيد إقامة الجسر بين الروملي والأناضول. الأماكن الأخرى التي انضمت في التاريخ نفسه: جمبي.", "fc79cd5d"]},
"OLAYLAR_EK:1381-01-01:0":{"b": ["جهاز كرميان: انضمام كوتاهية", "d6a6fe61"], "d": ["عند زواج دولت شاه خاتون، ابنة كرميان أوغلو سليمان شاه، من يلدريم بايزيد، انتقلت كوتاهية وسيماو وطاوشانلي وإيغري كوز إلى العثمانيين جهازًا — وهو المثال الكلاسيكي للتوسع دون حرب. الأماكن الأخرى التي انضمت في التاريخ نفسه: أفيون.", "3321bbba"]},
"OLAYLAR_EK:1381-06-01:0":{"b": ["شراء إيالة حميد: انضمام إسبارطة", "4a1b6047"], "d": ["باع حميد أوغلو حسين بك جزءًا من إمارته (أقشهر – بيشهر – إسبارطة) إلى مراد الأول نقدًا؛ وسيضم يلدريم بقية إيالة حميد عام 1391.", "d316dea5"]},
"OLAYLAR_EK:1383-09-19:0":{"b": ["فتح سيريس", "d4d28b60"], "d": ["أُخذت سيريس، مفتاح مقدونيا الشرقية؛ ودخلت سلانيك دائرة الحصار. ولم يكن خط كوستندل – بتريتش – نيفروكوب – دراما بين صوفيا وسيريس قد ضُمّ مباشرة في هذا التاريخ، بل انتقل بالتتابع إلى التبعية في سبعينيات القرن الرابع عشر حتى 1383، وإلى الإدارة المباشرة بعد 1383.", "573cc19c"]},
"OLAYLAR_EK:1385-09-01:0":{"b": ["فتح صوفيا", "96d5f01f"], "d": ["وُضعت ممرات جبال البلقان الغربية تحت السيطرة؛ ولأن سيريس كانت بيد العثمانيين منذ 1383، شكلت أراضي تراقيا ومقدونيا في هذا التاريخ كتلة متصلة بلا انقطاع.", "f358b568"]},
"OLAYLAR_EK:1386-01-01:0":{"b": ["فتح نيش", "77f5d632"], "d": ["بأخذ نيش، قفل وادي مورافا، صارت إمارة الصرب مهددة تهديدًا مباشرًا.", "15f52aaf"]},
"OLAYLAR_EK:1387-04-09:0":{"b": ["الاستسلام الأول لسلانيك", "96010ee9"], "d": ["استسلمت المدينة بعد حصار طويل (وستُعاد إلى البيزنطيين عام 1403 وتُفتح فتحًا نهائيًّا عام 1430). الأماكن الأخرى التي انضمت في التاريخ نفسه: قوالة.", "5ef8bffd"]},
"OLAYLAR_EK:1387-06-08:0":{"b": ["المعاهدة العثمانية الجنوية — تجديد معاهدة 1352", "be11d17a"], "d": ["جُدّدت معاهدة التجارة لعام 1352 الباقية من عهد أورخان غازي مع السفراء الجنويين القادمين من بيرا؛ وأُعيد تحديد الضرائب بين الدولتين ومعاملة الأسرى والتجارة الحرة. وتُعدّ هذه أول عهدنامة صداقة وتجارة معروفة رسميًّا بين العثمانيين والجنويين — وهي ليست تحالفًا عسكريًّا بل اتفاقًا تجاريًّا خالصًا.", "46b0f65b"]},
"OLAYLAR_EK:1388-01-01:0":{"b": ["حملة جاندارلي علي باشا على بلغاريا: الاستيلاء على شومنو وروسجق", "2781c3a9"], "d": ["استُلمت قلاع القيصرية البلغارية على ضفاف الدانوب في حملة واحدة؛ ولا ينبغي الخلط بينها وبين الهزيمة التي لحقت في السنة نفسها في بليتشا بالبوسنة — فقد كان ذلك نجاحًا متزامنًا على جبهة منفصلة. وكانت ترنوفو وفيدين آخر المراكز البلغارية التي بقيت بأيديهم.", "d6eaf4cd"]},
"OLAYLAR_EK:1388-08-27:0":{"b": ["هزيمة بليتشا", "89ba0a64"], "d": ["نُصب كمين لقوة المغيرين المتجهة إلى البوسنة في بليتشا فأُبيدت؛ وشجعت هذه النكسة البلقانية الأولى الكبرى التحالف الذي بلغ كوسوفو.", "9960a7a5"]},
"OLAYLAR_EK:1390-01-01:0":{"b": ["ضم إمارات غرب الأناضول: صاروخان وآيدين ومنتشا", "dcc33b71"], "d": ["انضمت ثلاث إمارات في حملة واحدة: مانيسا مركز الصاروخانيين؛ وآيدين مركز الآيدينيين (بما فيها قلعة إزمير العليا، لكن الميناء والقلعة السفلى ظلا بيد فرسان القديس يوحنا حتى 1402)؛ وموغلا – ميلاس مركز المنتشائيين، بما فيها شريط الساحل داتشا – بدروم – مرمريس – فتحية. واجتمعت سواحل إيجه لأول مرة في يد واحدة. الأماكن الأخرى التي انضمت في التاريخ نفسه: سوكه.", "7f3094f2"]},
"OLAYLAR_EK:1391-10-01:0":{"b": ["بدء الحصار الأول للقسطنطينية", "4441a9e7"], "d": ["حاصر يلدريم بايزيد القسطنطينية بصورة متقطعة عشر سنوات؛ ولم تنجُ المدينة إلا بفضل اقتراب تيمور.", "504fcb33"]},
"OLAYLAR_EK:1392-01-01:0":{"b": ["ضم إيالة تكة: انضمام أنطاليا", "fdbeee5c"], "d": ["انضمت إيالة تكة على ساحل البحر المتوسط إلى الأراضي العثمانية. والتكه أوغلو فرع انفصل عن الحميد أوغلو: فقد ترك فلك الدين دندار بك أنطاليا التي فتحها لأخيه يونس بك ونشأت إمارة منفصلة نحو عام 1321. ولذلك تُعرض أنطاليا وما حولها على الخريطة بعد 1321 بلون التكه أوغلو لا الحميد أوغلو. وأُعيد تأسيس الإمارة بعد معركة أنقرة ولم تُصفَّ نهائيًّا إلا عام 1423.", "09a83d97"]},
"OLAYLAR_EK:1392-01-06:0":{"b": ["فتح أسكوب", "9e5a1af5"], "d": ["أُخذت أسكوب، مركز مقدونيا الفاردارية؛ وصارت أسكوب من أهم مراكز الثغور في الروملي.", "8722b1dd"]},
"OLAYLAR_EK:1392-11-01:0":{"b": ["ضم قسطموني", "876330ba"], "d": ["صُفّي فرع قسطموني من الجاندار أوغلو؛ واستمر فرع سينوب تابعًا. الأماكن الأخرى التي انضمت في التاريخ نفسه: بارتن، صفرانبولو.", "34d8e600"]},
"OLAYLAR_EK:1393-06-17:0":{"b": ["سقوط ترنوفو — ضم بلغاريا", "ff666977"], "d": ["سقطت عاصمة القيصرية البلغارية؛ ودخلت بلغاريا تحت الإدارة العثمانية المباشرة. الأماكن الأخرى التي انضمت في التاريخ نفسه: بليفن، لوفتش.", "182028e2"]},
"OLAYLAR_EK:1393-06-17:1":{"b": ["انتقال قلعة لوفتش (لوفتش) إلى العثمانيين", "a55e87a0"], "d": ["انضمت لوفتش، من قلاع القيصر البلغاري إيفان شيشمان، إلى الأراضي العثمانية مع سائر ولايات شيشمان في حملة 1393 التي سقطت فيها ترنوفو. والمصدر لا يجزم: إذ «يُظن» أن الفتح كان في هذه السنة.", "9430a123"]},
"OLAYLAR_EK:1393-09-01:0":{"b": ["انضمام دوبروجة", "478e36f2"], "d": ["انضمت أراضي دوبروجة الممتدة إلى دلتا الدانوب. الأماكن الأخرى التي انضمت في التاريخ نفسه: سيليستر، كوستنجة.", "05bdabb4"]},
"OLAYLAR_EK:1394-01-01:0":{"b": ["النزول إلى تساليا", "8bec60dd"], "d": ["أُدخل سهل تساليا الذي مركزه ينيشهير (لاريسا) تحت الإدارة العثمانية. الأماكن الأخرى التي انضمت في التاريخ نفسه: تيرهالا، إزدين (لاميا).", "d9f2128c"]},
"OLAYLAR_EK:1395-01-01:0":{"b": ["فتح نيكوبوليس", "b9791717"], "d": ["استولى يلدريم بايزيد على قلعة نيكوبوليس على ضفاف الدانوب إثر معركة روفين عام 1395 ضد الأفلاقيين؛ وتذكر بعض الحوليات البلغارية المجهولة أن الفتح تم في 3 يونيو 1395. وتاريخ الفتح ليس واحدًا في المصادر: فمادة «معركة نيكوبوليس» في TDV İslâm Ansiklopedisi تذكر أن بايزيد أخذ سيليستر ونيكوبوليس في حملة على الدانوب عام 1394. وستُحاصر القلعة في الحملة الصليبية الشهيرة عام 1396 ولكنها لن تسقط. الأماكن الأخرى التي انضمت في التاريخ نفسه: أوهريد.", "bc450a9f"]},
"OLAYLAR_EK:1395-05-17:0":{"b": ["معركة روفين — حملة الأفلاق", "343ae7a9"], "d": ["بعد المعركة الدامية، المختلف في نتيجتها، مع فويفود الأفلاق ميرتشا، قبلت الأفلاق دفع الجزية للعثمانيين؛ وأُقيم نظام التبعية شمال الدانوب.", "dd69200f"]},
"OLAYLAR_EK:1395-08-01:0":{"b": ["بناء قلعة الأناضول", "aa259b00"], "d": ["بُنيت كوزلجه حصار (قلعة الأناضول) على الجانب الأناضولي من البوسفور لدعم حصار القسطنطينية — وهي أول خطوة دائمة للسيطرة على المضيق.", "a1b2f889"]},
"OLAYLAR_EK:1396-10-01:0":{"b": ["ضم فيدين", "ee1ae44b"], "d": ["ضُمّت فيدين، آخر إمارة بلغارية، بعد انتصار نيكوبوليس.", "28f4258d"]},
"OLAYLAR_EK:1397-07-01:0":{"b": ["الضم الأول لقرمان", "3cf07876"], "d": ["بانتصار آق تشاي انضمت أراضي القرمانيين لأول مرة إلى العثمانيين (وستُعاد إمارتهم في فترة الفتنة).", "788bdca3"]},
"OLAYLAR_EK:1398-07-01:0":{"b": ["انضمام سواحل جانيك: سامسون", "af9c40fa"], "d": ["في الفراغ الذي نشأ بوقوع قاضي برهان الدين أسيرًا بيد قره يولوق عثمان بك الآق قويونلو، ضم يلدريم بايزيد أولًا منطقة جانيك على ساحل البحر الأسود إلى الإدارة العثمانية. وهكذا صارت سامسون وما حولها أول ميناء للأسرة على البحر الأسود. أما خط سيواس – طوقات – قيصري في الداخل فسينضم بعد أسبوعين مع تفكك دولة قاضي برهان الدين فعليًّا.", "4b2f9a80"]},
"OLAYLAR_EK:1399-09-01:0":{"b": ["الاستيلاء على ملطية", "7cb6ae16"], "d": ["أُخذت ملطية على الحدود المملوكية — وهي إحدى الخطوات التي زادت التوتر مع تيمور.", "3b7ba002"]},
"OLAYLAR_EK:1400-01-01:0":{"b": ["تيمور يأخذ ملطية ويتركها لقره يولوق عثمان — وعند انسحاب تيمور استعادها الذلقادرية", "ad2ce7d8"], "d": ["كان يلدريم بايزيد قد عاد إلى بورصة بعد أن ترك ملطية، التي أخذها عام 1399، لذلقادر أوغلو ناصر الدين محمد. وأخذ تيمور، الذي دخل الأناضول عام 1400، سيواس وألبستان أولًا ثم ملطية؛ ونُهبت المدينة وما حولها، وتُركت إدارتها لقره يولوق عثمان الذي كان إلى جانب تيمور. ولما غادر تيمور المنطقة عادت الذلقادرية فسيطرت على ملطية؛ وهكذا انتهت السيادة العثمانية قبل أنقرة.", "5889cce9"]},
"OLAYLAR_EK:1403-06-01:0":{"b": ["اتفاقية سليمان جلبي مع بيزنطة: إعادة سلانيك", "cc503cc2"], "d": ["اتفق سليمان جلبي، الذي حكم الروملي في فترة الفتنة، مع الدول البيزنطية واللاتينية، فترك لبيزنطة سلانيك وسواحل البحر الأسود حتى ميسيمفريا (TDV فترة الفتنة: معاهدة غاليبولي، فبراير 1403) — فتنتقل إينه أدا وريزفه وأهتبولو إلى بيزنطة على الخريطة؛ وتخرج سلانيك من العثمانيين في هذا التاريخ على الخريطة.", "ac791637"]},
"OLAYLAR_EK:1416-05-29:0":{"b": ["الهزيمة البحرية في غاليبولي (البندقية)", "b71d4d68"], "d": ["ألحق الأسطول البندقي هزيمة ثقيلة بالأسطول العثماني أمام غاليبولي؛ وكان الحدث دليلًا على حدود البحرية العثمانية في العصر المبكر.", "7166c255"]},
"OLAYLAR_EK:1421-08-15:0":{"b": ["ثورة مصطفى المزيّف", "0ec43138"], "d": ["أعلن مصطفى جلبي، الذي ادعى أنه ابن يلدريم، السلطنة في الروملي بدعم بيزنطي؛ وسيقمع مراد الثاني الثورة عام 1422 ويأمر بإعدام خصمه.", "9bae8d0d"]},
"OLAYLAR_EK:1422-06-10:0":{"b": ["حصار مراد الثاني للقسطنطينية", "4b9d9fba"], "d": ["حاصر مراد الثاني القسطنطينية ردًّا على دعم بيزنطة لمصطفى المزيّف؛ ورُفع الحصار إثر إثارة أخيه مصطفى الصغير ثورة في الأناضول.", "bc254acf"]},
"OLAYLAR_EK:1423-09-14:0":{"b": ["تسليم سلانيك إلى البندقية", "bfa6c4a0"], "d": ["سلّم الحاكم البيزنطي، الواقع تحت الضغط العثماني، المدينة إلى البندقية؛ وبدأ الصراع العثماني البندقي الذي سيدوم سبع سنوات.", "da60fe5f"]},
"OLAYLAR_EK:1425-06-01:0":{"b": ["إعادة ضم إمارات غرب الأناضول: منتشا وآيدين", "aca30a48"], "d": ["انضمت نهائيًّا إلى الأراضي العثمانية في عهد مراد الثاني الإمارتان الإيجيتان اللتان أُعيد تأسيسهما في فترة الفتنة. وبحسب مادة المنتشا أوغلو في TDV أخذ مراد الثاني إيالة منتشا عام 827 (1424) وسجن الأخوين اللذين كانا على رأس الإمارة. وبحسب مادة الآيدين أوغلو، أمر بكلربك الأناضول حمزة بك بالقبض على جنيد بك الذي خرج عن الطاعة من جديد، وأعدمه مع أسرته (829 / 1425–1426)، وانتقلت إيالة آيدين إلى العثمانيين. وكان فرسان القديس يوحنا الذين يحتفظون بقلعة ميناء إزمير منذ 1344 قد فقدوها لتيمور عام 1402، وعادت المنطقة إلى سيطرة الآيدينيين؛ وبهذا الضم انضمت هي أيضًا إلى العثمانيين. أما إيالة تكة (أنطاليا) فليست موضوع هذه المادة: إذ كانت إمارة التكه أوغلو قد صُفّيت على حدة عام 1423. أما كرميان فستنضم عام 1429 بالوصية.", "92fa8d97"]},
"OLAYLAR_EK:1429-01-01:0":{"b": ["ضم كرميان بالوصية", "9eb86b77"], "d": ["ترك بك كرميان يعقوب الثاني، الذي توفي دون أولاد، بلاده للعثمانيين بالوصية — وهو المثال الذي دخل الكتب المدرسية للضم دون حرب. الأماكن الأخرى التي انضمت في التاريخ نفسه: قره حصار صاحب (أفيون).", "9173c7b2"]},
"OLAYLAR_EK:1430-03-29:0":{"b": ["الفتح النهائي لسلانيك", "bc021768"], "d": ["أُخذت المدينة الخاضعة للبندقية بالهجوم؛ وصار ثاني أكبر موانئ الروملي عثمانيًّا نهائيًّا. الأماكن الأخرى التي انضمت في التاريخ نفسه: كاساندرا (Kassandra).", "8853e257"]},
"OLAYLAR_EK:1430-10-09:0":{"b": ["استسلام يانيا", "ee45cb52"], "d": ["استسلمت يانيا، مركز إبيروس، بالاتفاق.", "1aad46c0"]},
"OLAYLAR_EK:1439-08-27:0":{"b": ["الاستيلاء الأول على سمندرة", "c11ca17d"], "d": ["أُخذت عاصمة إمارة الصرب بحصار دام ثلاثة أشهر وضُمّت صربيا لأول مرة (وستُعاد بمعاهدة أدرنة – سيجد عام 1444).", "3dc4dfe5"]},
"OLAYLAR_EK:1440-04-01:0":{"b": ["حصار بلغراد (الفاشل)", "3e05f425"], "d": ["لم يُثمر أول حصار كبير لبلغراد دام ستة أشهر؛ وظلت القلعة قفلًا أمام التقدم العثماني ثمانين سنة.", "2a88be8a"]},
"OLAYLAR_EK:1443-11-24:0":{"b": ["هزيمة إزلادي — «الحملة الطويلة»", "97df1466"], "d": ["تقدم الجيش الذي أدخله هونيادي إلى البلقان في منتصف الشتاء عبر نيش وصوفيا حتى بلغ إزلادي؛ وصمد الدفاع العثماني بصعوبة. وجاء جو الهزيمة هذا بسلام أدرنة – سيجد إلى الطاولة.", "cf103982"]},
"OLAYLAR_EK:1444-06-12:0":{"b": ["معاهدة أدرنة – سيجد", "0aa4e0de"], "d": ["سلام لعشر سنوات: أُعيدت إمارة الصرب، واعتُبر الدانوب حدًّا. وأدى نقض المعاهدة في غضون أشهر بتحريض البابوية إلى كارثة وارنا.", "46b3ced6"]},
"OLAYLAR_EK:1444-08-15:0":{"b": ["إعادة سمندرة والقلاع الصربية إلى صربيا", "cda3cf9e"], "d": ["طُبّق حكم معاهدة أدرنة – سيجد: ففي 15 أغسطس 1444 أعاد مراد الثاني سمندرة مع أربع وعشرين قلعة مهمة وسائر الأراضي الصربية المحتلة إلى جوراج برانكوفيتش (TDV سمندرة)؛ وتُركت نيش (TDV نيش) وألاجه حصار (TDV ألاجه حصار) وشهر كوي (TDV شهر كوي) وبريشتينا (TDV بريشتينا) أيضًا للصرب. ولم تدخل فيدين في الإعادة لأنها ليست أرضًا صربية — وهذا هو مصدر فقدان الأرض في الشمال الغربي الذي يُرى على الخريطة حول انتصار وارنا؛ وبعد أشهر قليلة ستبطل المعاهدة أصلًا مع هزيمة وارنا.", "19c68a1f"]},
"OLAYLAR_EK:1452-08-31:0":{"b": ["اكتمال قلعة الروملي — «قاطع الحلق»", "480e8a76"], "d": ["بالقلعة التي اكتملت ببناء سريع بصورة استثنائية دام أربعة إلى خمسة أشهر بحسب المصادر، انتقلت السيطرة على المضيق كلها إلى العثمانيين؛ وانقطع طريق المدد من البحر الأسود إلى القسطنطينية. وتُعدّ الخطوة الفعلية الأولى للحصار.", "1d84cd36"]},
"OLAYLAR_EK:1453-04-06:0":{"b": ["بدء حصار القسطنطينية", "8af50742"], "d": ["استقر الجيش أمام الأسوار؛ وفي الحصار الذي سيدوم 54 يومًا استُخدمت المدافع العملاقة لأول مرة بصورة منهجية ضد أسوار عاصمة.", "6d71da31"]},
"OLAYLAR_EK:1453-04-22:0":{"b": ["إنزال السفن برًّا إلى القرن الذهبي", "4f2ba07c"], "d": ["أُنزلت نحو 70 سفينة من الأسطول، الذي لم يستطع دخول القرن الذهبي المغلق بالسلسلة، في ليلة واحدة إلى القرن الذهبي بسحبها على زلاجات مدهونة بالزيت فوق تلال غلطة؛ وانقسم الدفاع إلى جبهتين.", "2eb65d41"]},
"OLAYLAR_EK:1456-06-04:0":{"b": ["فتح أثينا", "4f0f1bb2"], "d": ["انتهت دوقية أثينا؛ ورُفع العلم العثماني على الأكروبوليس. الأماكن الأخرى التي انضمت في التاريخ نفسه: إستيفة (طيبة)، ليفاديا.", "a912625d"]},
"OLAYLAR_EK:1459-06-20:0":{"b": ["ضم صربيا (سقوط سمندرة)", "75fd0a62"], "d": ["استسلمت سمندرة، عاصمة إمارة الصرب؛ وصارت صربيا سنجقًا عثمانيًّا.", "29bd2888"]},
"OLAYLAR_EK:1460-05-29:0":{"b": ["فتح المورة", "7d5a3c18"], "d": ["صُفّيت إمارة المورة؛ ودخلت شبه الجزيرة (باستثناء القلاع البندقية) تحت الإدارة العثمانية.", "14aba74c"]},
"OLAYLAR_EK:1461-06-01:0":{"b": ["انضمام سينوب", "e03c2739"], "d": ["استسلم جاندار أوغلو سينوب دون قتال؛ وانفتح الطريق إلى حملة طرابزون. الأماكن الأخرى التي انضمت في التاريخ نفسه: قسطموني، بارتن، صفرانبولو.", "4fa22834"]},
"OLAYLAR_EK:1463-06-01:0":{"b": ["سقوط مملكة البوسنة — حملة الفاتح على البوسنة", "5362e3f2"], "d": ["لما رفض آخر ملوك البوسنة ستيبان توماشيفيتش (1461–1463) دفع الجزية معتمدًا على دعم الغرب، عُدّ خارجًا عن كونه حاكمًا تابعًا، وصفّى الجيش بقيادة السلطان الفاتح محمد مملكة البوسنة في حملة واحدة. وقُبض على الملك وأُعدم، وزالت المملكة، وأُنشئ سنجق البوسنة في المنطقة. غير أن سقوط المملكة ليس هو نفسه فتح البوسنة. فقد كانت الإدارة العثمانية قائمة في السهل منذ خمس عشرة سنة — فقد أُخذت هوديديد وسهل سراي عام 1448، وأُنشئت إمارة الثغر لعيسى بك في وسط المملكة. ولم ينتهِ الفتح عام 1463: فقد أُخذت فوتشا عام 1465، وليفنو عام 1469، ودوقية الهرسك عام 1483، وبانوية سريبرينيك عام 1512، أما يايتسه وبانيالوكا في الشمال فلم يمكن أخذهما إلا عام 1528 بعد موهاج — فقد أقام المجر بانوية صمدت في شمال البوسنة خمسًا وستين سنة بعد 1463. والمكان الذي تغيّرت يده مباشرة في هذا التاريخ هو ترافنيك؛ أما يايتسه فقد انتقلت في هذا التاريخ إلى المجر لا إلى العثمانيين.", "5ac16344"]},
"OLAYLAR_EK:1468-01-01:0":{"b": ["الضم النهائي لقرمان", "f1dcecaa"], "d": ["انضمت الأراضي المركزية للقرمانيين نهائيًّا؛ واستمرت الخلافات الداخلية حتى سبعينيات القرن الخامس عشر. الأماكن الأخرى التي انضمت في التاريخ نفسه: نيغدة، موستار، بيشهر.", "da6cfd4c"]},
"OLAYLAR_EK:1470-07-12:0":{"b": ["فتح إغريبوز", "5c97daf3"], "d": ["سقطت إغريبوز، القاعدة الرئيسة للبندقية في بحر إيجه.", "189cc474"]},
"OLAYLAR_EK:1471-01-01:0":{"b": ["ضم آلانيا وأنامور وسيلفكه (إيچ إيل)", "a0b9d461"], "d": ["انضم شريط ساحل إيچ إيل التابع للقرمانيين (كل ساحل البحر المتوسط بين أنطاليا ومرسين) بحملة قدك أحمد باشا البحرية؛ وكانت آلانيا مهمة بترسانتها الاستراتيجية الباقية من العهد السلجوقي.", "8302df58"]},
"OLAYLAR_EK:1479-01-25:0":{"b": ["معاهدة إسطنبول — ألبانيا وإشقودرة", "b09652f7"], "d": ["انتهت الحرب العثمانية البندقية التي دامت 16 عامًا؛ وبقيت إشقودرة وسواحل ألبانيا عند العثمانيين. الأماكن الأخرى التي انضمت في التاريخ نفسه: ليمنوس، ساموس، بوزجا أطه (آي ستراتي).", "bc2aebf2"]},
"OLAYLAR_EK:1480-08-11:0":{"b": ["إنزال أوترانتو", "7916b89d"], "d": ["حاصرت القوات العثمانية التي نزلت على ساحل كالابريا قلعة أوترانتو وأخذتها؛ ولأن المدينة دُخلت بالقتال أُعدم بعض الوجهاء المقاومين وأُسر بعضهم. وتخلّد التقاليد الكنسية القتلى بوصفهم «شهداء أوترانتو» ويبلغ عددهم نحو 800؛ ويرجع TDV المبالغة في هذا العدد إلى الدعاية الكنسية. ولم يُحتفظ إلا بالقلعة في طرف شبه جزيرة ساليتو وما حولها الضيق؛ ولم تخرج بقية أراضي مملكة نابولي على خط تارانتو – برينديزي – ليتشي من اليد — وكانت رأس الجسر هذه المفتوحة على إيطاليا ستدوم سنة.", "f60d286a"]},
"OLAYLAR_EK:1481-09-10:0":{"b": ["إخلاء أوترانتو", "37371bb0"], "d": ["أخلت حامية أوترانتو، التي لم يبقَ لها أمل في تعزيزات جديدة إثر وفاة السلطان الفاتح محمد (3 مايو 1481)، القلعة باتفاق أمام حصار ألفونسو ولي عهد نابولي؛ وهكذا خرج من اليد بعد سنة رأس الجسر العثماني الوحيد في إيطاليا.", "961ef9c3"]},
"OLAYLAR_EK:1500-08-09:0":{"b": ["فتح مودون وكورون", "38b608c4"], "d": ["أُخذت مودون وكورون، «عينا» البندقية في المورة.", "a11c09d0"]},
"OLAYLAR_EK:1501-08-17:0":{"b": ["فتح دراج", "1f231b98"], "d": ["في أثناء الحرب العثمانية البندقية 1499–1503 أخذت القوات بقيادة محمد بك دراج، آخر ميناء ألباني كبير للبندقية على الأدرياتيكي. وبعد إشقودرة (1479) وأفلونيا (1417)، دخل بهذا الفتح شريط الساحل الألباني كله تحت السيطرة العثمانية.", "ad635bca"]},
"OLAYLAR_EK:1515-09-15:0":{"b": ["انضمام الأناضول الشرقية", "e0cb8f8f"], "d": ["انضمت ديار بكر وما حولها بعد جالديران؛ وارتبطت الإمارات الكردية بالعثمانيين على يد إدريس البدليسي.", "025d3ddc"]},
"OLAYLAR_EK:1526-07-27:0":{"b": ["فتح قلعة فارادين (بتروارادين)", "abf392a5"], "d": ["عبر الجيش الذي خرج في حملة موهاج من بلغراد إلى الأراضي المجرية؛ فأُخذت ضواحي فارادين الخارجية أولًا، ثم سقطت القلعة أيضًا بعد حصار دام أربعة عشر يومًا. وأمر القانوني بألا تُحرق القرى الواقعة على الطريق، لأنها صارت تُعدّ أرضًا عثمانية.", "60a4ae4e"]},
"OLAYLAR_EK:1526-09-01:0":{"b": ["استسلام بودين بعد موهاج — ملكان على العرش المجري", "9d3568a0"], "d": ["قُدّمت مفاتيح المدينة إلى السلطان في 11 سبتمبر 1526 للجيش العثماني الذي زحف إلى بودين بعد انتصار موهاج؛ غير أن القانوني لم يحتفظ ببودين وسحب جيشه. وفي المجر التي بقيت بلا ملك اختار النبلاء ملكين منفصلين: يانوش زابوليا في 10 نوفمبر 1526، والهابسبورغي فرديناند الأول في 17 ديسمبر 1526. وأخذ فرديناند بودين في أغسطس 1527. أما استقرار زابوليا في بودين ملكًا تحت الحماية العثمانية فسيكون بحملة 1529 (انظر مادة 1529)، وستقوم الإدارة العثمانية المباشرة عام 1541.", "d68817d3"]},
"OLAYLAR_EK:1526-11-10:0":{"b": ["انتخاب يانوش زابوليا ملكًا على المجر — الاعتراف العثماني بمملكته على أن يكون تابعًا", "32bc6baf"], "d": ["انتخب جزء من النبلاء يانوش زابوليا، فويفود ترانسلفانيا، للعرش المجري الذي شغر بوفاة الملك في موهاج؛ وتُوّج زابوليا في إستولني بلغراد. واعترف العثمانيون، الذين أخلوا بودين، بمملكة زابوليا بشرط أن يكون تابعًا لهم، ليبقوا المنطقة حاجزًا عازلًا. وتظهر الأماكن التابعة لزابوليا على الخريطة تابعة للعثمانيين اعتبارًا من هذا التاريخ.", "1d697cbd"]},
"OLAYLAR_EK:1526-12-17:0":{"b": ["إعلان فرديناند الأول ملكًا على المجر — غرب المجر وشمالها إلى التاج الهابسبورغي", "b3910a2f"], "d": ["ادّعى الأرشيدوق الهابسبورغي فرديناند حقًّا في العرش المجري استنادًا إلى زواج أخته من لايوش الثاني، وأعلنه جزء من النبلاء ملكًا. وهكذا انقسمت المجر بين ملكين؛ واعترف الجزء الغربي والشمالي بفرديناند. وانتخبه النبلاء الكروات أيضًا في مطلع 1527.", "1484af4c"]},
"OLAYLAR_EK:1530-01-01:0":{"b": ["نزاع الملكين: إسترغوم إلى الحماية الهابسبورغية، وسيجد إلى زابوليا", "da92dee5"], "d": ["انتقلت إسترغوم، التي تبادلتها يد الملكين منذ 1526، إلى الحماية الهابسبورغية بعد أن انتقل رئيس الأساقفة شمالًا بأرشيفه وخزانته. وظلت سيجد تحت سيادة زابوليا منذ السنة نفسها حتى 1541.", "4317e319"]},
"OLAYLAR_EK:1532-01-01:0":{"b": ["أهالي بيتش ينتقلون إلى جانب زابوليا", "3fc4e7f2"], "d": ["انتقلت بيتش، التي نالت امتيازًا من فرديناند عام 1528، بعد فترة وجيزة إلى جانب زابوليا؛ وأقام الملك يانوش في المدينة مدة عام 1533. وبسقوط بودين عام 1541 عادت المدينة إلى جانب فرديناند.", "af03d9f3"]},
"OLAYLAR_EK:1551-08-15:0":{"b": ["فتح طرابلس الغرب", "8c659986"], "d": ["أُخذت طرابلس من فرسان القديس يوحنا؛ وصار الساحل الأوسط لشمال أفريقيا عثمانيًّا. الأماكن الأخرى التي انضمت في التاريخ نفسه: مصراتة.", "f3a5310d"]},
"OLAYLAR_EK:1552-07-27:0":{"b": ["فتح تمشوار", "e9fd4995"], "d": ["أُخذت منطقة بانات وأُنشئت بكلربكية تمشوار.", "1b99085d"]},
"OLAYLAR_EK:1574-08-25:0":{"b": ["الفتح النهائي لتونس", "7bbd11bc"], "d": ["دخلت تونس، التي كانت تحت السيطرة الإسبانية الحفصية، تحت الإدارة العثمانية نهائيًّا؛ واكتمل الخط الشمال أفريقي. الأماكن الأخرى التي انضمت في التاريخ نفسه: القيروان، قابس، صفاقس.", "a92c818a"]},
"OLAYLAR_EK:1600-10-20:0":{"b": ["فتح كانيجة", "0c7b6aa3"], "d": ["أُخذت كانيجة في الحرب الطويلة؛ وصار دفاع تريآكي حسن باشا في السنة التالية ملحمة.", "12042d94"]},
"OLAYLAR_EK:1663-04-13:0":{"b": ["بدء حملة أويوار — فاضل أحمد باشا يزحف من أدرنة نحو النمسا", "306a86db"], "d": ["اتخذت إسطنبول قرار الحملة على الهابسبورغ إثر هجوم النمسا على ترانسلفانيا واستيلائها على قلعتي سيكلهيد وكولوجفار. وتحرك الصدر الأعظم كوبريلي زاده فاضل أحمد باشا من أدرنة في 13 أبريل 1663. وجاء طلب النمسا للسلم في بلغراد، لكن الشروط العثمانية رُفضت في مفاوضتين في أوسيك. وحُدّد الهدف أويوار أيضًا في المشاورة في بودين.", "f77c2f04"]},
"OLAYLAR_EK:1663-09-24:0":{"b": ["فتح أويوار", "ce289470"], "d": ["أُخذت أويوار، القلعة المفتاحية في شمال المجر؛ ودخل التعبير «قوي كتركي أمام أويوار» اللغات الأوروبية. وبعد أويوار استسلمت نيترا وليفا أيضًا بمقاومة قصيرة؛ واستعادهما دي سوش في ربيع 1664.", "80ef48fc"]},
"OLAYLAR_EK:1715-07-01:0":{"b": ["استعادة المورة", "9b6460f1"], "d": ["استُعيدت المورة التي تُركت للبندقية في كارلوفيتس في حملة واحدة. الأماكن الأخرى التي انضمت في التاريخ نفسه: بالياباترا (باتراس)، إينه بختي.", "56dc13ce"]},
"OLAYLAR_EK:1717-08-18:0":{"b": ["فقدان بلغراد للمرة الثانية — حصار الأمير أوجين", "6a194354"], "d": ["حاصر الأمير أوجين بلغراد بعد هزيمة فارادين وفقدان تمشوار؛ ولما هُزم جيش النجدة الذي جاء لإنقاذ المدينة أيضًا استسلمت القلعة. وهكذا خرجت من اليد من جديد المدينة التي استُعيدت عام 1690 بعد كارلوفيتس، وانهار خط دفاع الدانوب. ولن تُستعاد بلغراد إلا بعد اثنتين وعشرين سنة بمعاهدة بلغراد عام 1739. المواطن الأخرى التي خرجت من اليد في التاريخ نفسه: سمندرة.", "3bf3f600"]},
"OLAYLAR_EK:1788-12-17:0":{"b": ["سقوط أوزي", "90a67a6c"], "d": ["سقطت أوزي، القلعة المفتاحية شمال البحر الأسود، بيد روسيا في هجوم دموي؛ وأُعمل السيف في أهل المدينة.", "9d37026c"]},
"OLAYLAR_EK:1812-05-28:0":{"b": ["معاهدة بوخارست — فقدان بسارابيا", "932da4d6"], "d": ["بالمعاهدة التي أنهت الحرب الروسية 1806–1812 تُرك شرق بروت (بسارابيا) لروسيا. المواطن الأخرى التي خرجت من اليد في التاريخ نفسه: أق كرمان، كيلي، خوتين، بندر، إسماعيل.", "a4c3a1fb"]},
"OLAYLAR_EK:1829-09-14:0":{"b": ["معاهدة أدرنة", "b3a8fe4c"], "d": ["في ختام الحرب التي دخل فيها الجيش الروسي أدرنة، فُقدت دلتا الدانوب؛ وقُبل عمليًّا حكم اليونان الذاتي / استقلالها. المواطن الأخرى التي خرجت من اليد في التاريخ نفسه: إبرائيل، أنابا، أخالتسيخه. ورغم أن المعاهدة أعادت الأرض فإنها لم تُنهِ الاحتلال فورًا: فقد بقيت الأفلاق والبغدان وسيليستر رهائن تحت الإدارة الروسية حتى دفع تعويض الحرب — وهذا هو سبب ظهور هذه الأماكن محتلة على الخريطة بعد 1829 أيضًا.", "d09a34fb"]},
"OLAYLAR_EK:1830-10-17:0":{"b": ["فرمان الحكم الذاتي لصربيا — الإمارة الوراثية وشرط الحاميات", "6a5d901d"], "d": ["اعترف الخط الهمايوني الذي صدر عملًا بحكم معاهدة أدرنة المتعلق بصربيا بميلوش أوبرينوفيتش كنيازًا وراثيًّا، وجعل صربيا إمارة ذاتية الحكم حرة في شؤونها الداخلية وتابعة للعثمانيين في الخارج. أحكامه: تنتقل الإمارة من الأب إلى الابن، وتُدفع ضريبة سنوية مقطوعة، ويتولى المجلس الصربي إدارته الداخلية، وتكون الكنيسة ذاتية الحكم؛ وفي المقابل كانت ستبقى حاميات عثمانية في قلاع بلغراد وسمندرة وشاباتس وبوغوردلن وفتح الإسلام. واستمر هذا البناء المزدوج حتى انسحاب الحاميات عام 1867. وتنضم مدينة بلغراد على الخريطة في هذا التاريخ إلى صربيا ذاتية الحكم؛ وتُعرض قلعة كاليمغدان بحاميتها العثمانية حتى 1867.", "b71abc85"]},
"OLAYLAR_EK:1878-06-04:0":{"b": ["ترك قبرص للإدارة البريطانية", "423da3ee"], "d": ["تُركت إدارة قبرص لإنجلترا مقابل تحالف ضد التهديد الروسي؛ وبقيت قانونيًّا أرضًا عثمانية. المواطن الأخرى التي خرجت من اليد في التاريخ نفسه: نيقوسيا، ماغوزا.", "04ce99ee"]},
"OLAYLAR_EK:1881-07-02:0":{"b": ["ترك تساليا لليونان", "ac614d24"], "d": ["عملًا بقرارات مؤتمر برلين، تُركت تساليا وما حول أرطة لليونان. المواطن الأخرى التي خرجت من اليد في التاريخ نفسه: أرطة، ينيشهير (لاريسا)، تيرهالا، إزدين (لاميا).", "850edaa2"]},
"OLAYLAR_EK:1885-09-18:0":{"b": ["ضم الروملي الشرقية إلى بلغاريا", "ee43f137"], "d": ["ضُمّت ولاية الروملي الشرقية ذاتية الحكم إلى بلغاريا بانقلاب؛ وقبلت الباب العالي الأمر الواقع.", "41e57063"]},
"OLAYLAR_EK:1897-05-17:0":{"b": ["معركة دوموقوس", "9c6f29a5"], "d": ["في الحرب العثمانية اليونانية عام 1897 حقق الجيش انتصارًا حاسمًا في دوموقوس؛ وبقي كسب الأراضي محدودًا بالضغط الدبلوماسي.", "aff8be0b"]},
"OLAYLAR_EK:1898-12-22:0":{"b": ["الحكم الذاتي لكريت", "2e764881"], "d": ["رغم أن الحرب العثمانية اليونانية انتهت بانتصار عثماني، أعلنت إنجلترا وروسيا وفرنسا وإيطاليا في 18 ديسمبر 1897 استقلال كريت الذاتي؛ وكان على الجزيرة أن تكون ولاية محايدة ذاتية الحكم تحت السيادة العثمانية. وبعد 6 نوفمبر 1898 لم يُرفع العلم التركي بعد ذلك في كانديا وكيساموس؛ وبتولي الأمير جورج، ابن الملك اليوناني، منصب المفوض فوق العادة في 22 ديسمبر 1898 خرجت كريت عمليًّا من الإدارة العثمانية (وانفصلت رسميًّا عام 1913). المواطن الأخرى التي خرجت من اليد في التاريخ نفسه: كانديا (كريت)، خانيا.", "bc35b2a6"]},
"OLAYLAR_EK:1908-10-05:0":{"b": ["استقلال بلغاريا وضم البوسنة", "393feaa4"], "d": ["في اضطراب المشروطية أعلنت بلغاريا استقلالها، وضمت النمسا والمجر البوسنة والهرسك.", "6b7e2450"]},
"OLAYLAR_EK:1913-07-21:0":{"b": ["استرداد أدرنة", "536e5599"], "d": ["في حرب البلقان الثانية عبر الجيش نهر مريج واستعاد أدرنة دون قتال. الأماكن الأخرى التي انضمت في التاريخ نفسه: قرق كليسة، تكيرداغ.", "e5420880"]},
"OLAYLAR_EK:1916-04-29:0":{"b": ["انتصار كوت العمارة", "98b972bc"], "d": ["استسلم قائد الفرقة البريطانية المحاصرة في الكوت مع 13 ألف جندي — وهو من أكبر الانتصارات العثمانية في الحرب العالمية الأولى.", "20105888"]},
"OLAYLAR_EK:1917-03-11:0":{"b": ["فقدان بغداد", "2c18a816"], "d": ["انتقلت بغداد العثمانية، بعد 383 سنة، إلى الجيش البريطاني. المواطن الأخرى التي خرجت من اليد في التاريخ نفسه: كربلاء.", "4add66da"]},
"OLAYLAR_EK:1917-12-09:0":{"b": ["فقدان القدس", "94067617"], "d": ["سُلّمت القدس العثمانية، بعد 401 سنة، دون أن يمكن الدفاع عنها.", "f2738a38"]},
"OLAYLAR_EK:1918-10-01:0":{"b": ["فقدان دمشق", "ed177b68"], "d": ["أُخليت دمشق بانهيار الجبهة الفلسطينية؛ وانتهى الحكم العثماني في سوريا الذي دام أربعة قرون. المواطن الأخرى التي خرجت من اليد في التاريخ نفسه: حماة، حمص.", "ff6aea3f"]},
"OLAYLAR_EK:1919-01-10:0":{"b": ["تسليم المدينة المنورة", "76b505f6"], "d": ["بعد 72 يومًا من الهدنة، انتهت مقاومة فخري باشا، «نمر الصحراء»، بإرادة السلطان؛ وألقت آخر وحدة عثمانية في الحجاز سلاحها.", "06b180d9"]},
"OLAYLAR_EK:1919-05-15:0":{"b": ["احتلال إزمير", "e32e5e77"], "d": ["نزل الجيش اليوناني في إزمير؛ وأشعلت المقاومة التي بدأت بالرصاصة الأولى فتيل حرب الاستقلال. أما آيدين فاحتُلت في 27 مايو 1919 (مادة منفصلة).", "4cc27e6b"]},
"OLAYLAR_EK:1920-03-16:0":{"b": ["الاحتلال الرسمي لإسطنبول", "a8e98ada"], "d": ["احتلت قوات الوفاق إسطنبول رسميًّا وحُلّ مجلس المبعوثان؛ وتوجه النواب إلى أنقرة.", "09ed005b"]},
"OLAYLAR_EK:1921-10-13:0":{"b": ["معاهدة قارص", "bb32d4e0"], "d": ["رُسمت الحدود الشرقية بين المجلس الوطني الكبير وجمهوريات القفقاس على صورتها الحالية.", "fe736259"]},
"OLAYLAR_H7_ASAMA:1529-05-10:0":{"b": ["خروج القانوني في حملة فيينا — استئناف الحرب مع الهابسبورغ", "f7afd2a9"], "d": ["بعد موهاج انقسم العرش المجري إلى قسمين، وكان فرديناند قد أخذ بودين سنة 1527 وأخرج زابوليا (Szapolyai) من العاصمة. وخرج السلطان في حملته الرابعة لدعم زابوليا ووقف التقدم الهابسبورغي؛ وقبل الحملة مُنح الصدر الأعظم إبراهيم باشا لقب سر عسكر وبكلربكية الروملي فجرى كل التخطيط معه. وأخّرت الأمطار الغزيرة على الطريق تقدم الجيش؛ وتواصلت الحملة بأخذ بودين وتسليمها لزابوليا وحصار فيينا.", "4d80633a"]},
"OLAYLAR_H7_ASAMA:1562-05-05:0":{"b": ["تجديد السلم مع الهابسبورغ — نهاية حرب ترانسلفانيا وتمشوار", "97071975"], "d": ["الحرب التي بدأت بانتقال ترانسلفانيا إلى فرديناند سنة 1551 وتواصلت بحملات مثل فتح تمشوار وحصار إيغري (Eğri)، انتهت بقرار مواصلة السلم مع الهابسبورغ. جدّد الاتفاق التعهدات القديمة للطرفين بصورة متبادلة؛ لكنه لم يأتِ بحل للاضطرابات على الحدود، وزادت الأحداث في ترانسلفانيا مجددًا بعد وفاة فرديناند سنة 1564.", "04cfeca8"]},
"OLAYLAR_H7_ASAMA:1566-05-01:0":{"b": ["حملة القانوني الأخيرة — الخروج من إسطنبول بهدف سيغتفار وإيغري", "31277d21"], "d": ["تزايدت الاشتباكات على حدود ترانسلفانيا بعد وفاة فرديناند سنة 1564 وجلوس ماكسيميليان الثاني على العرش. وفي الحملة التي خطط لها السلطان المسن مع صوقوللو محمد باشا كان الهدف قلعتي سيغتفار وإيغري، وكان المراد كذلك تخويف الإمبراطور. وبعد أن دعا عند ضريح أيوب سلطان غادر إسطنبول بموكب عظيم؛ وبلغ أدرنة في 15 أيار/مايو، وبلغ بلغراد في اليوم الخمسين من حركته. وكان هذا آخر خروج له من عاصمته التي لن يراها ثانية.", "c601608a"]},
"OLAYLAR_H7_ASAMA:1568-02-17:0":{"b": ["معاهدة أدرنة — نهاية حالة الحرب مع الهابسبورغ", "d08883e3"], "d": ["بعد حملة سيغتفار، حضر سفراء الهابسبورغ والصفويين والبولنديين والفرنسيين والبندقية لدى السلطان سليم الثاني الذي قضى الشتاء في أدرنة. وتقرر استمرار السلم مع الصفويين؛ ووُقّعت المعاهدة التي أنهت حالة الحرب مع الهابسبورغ. وكان لتأثير الصدر الأعظم صوقوللو محمد باشا في هذه الأمور وزن كبير.", "27b65c0e"]},
"OLAYLAR_H7_ASAMA:1578-01-02:0":{"b": ["قرار حملة إيران — تعيين سردارين ضد الصفويين المتزعزعين بوفاة طهماسب", "1f09b186"], "d": ["انجرف الصفويون إلى اضطراب كبير سنة 1576 بتسميم الشاه طهماسب الأول إثر الخلافات بين رجال الأسرة والدولة؛ وحدّد هذا اتجاه الحملة المزمعة. وكُلّف لالا مصطفى باشا بالدخول إلى إيران من جهة أرضروم، وقوجه سنان باشا من جهة بغداد. ولما اشتد الخلاف بين الوزيرين تدخل صوقوللو: عُزل سنان باشا، وكُلّف لالا مصطفى باشا بفتح شيروان عبر جورجيا. وهذا القرار افتتاح الحرب العثمانية-الصفوية 1578-1590.", "3157145f"]},
"OLAYLAR_H7_ASAMA:1604-06-15:0":{"b": ["جغالزاده سنان باشا يخرج في حملة إيران", "1e90763e"], "d": ["بينما تدور حرب على جبهتين مع إيران والنمسا، حاصر الشاه عباس يريفان وأخذها ودخل قارص، لكنه أُوقف أمام أخسخة (Ahıska). وانطلق جغالزاده سنان باشا، وقد عُيّن سردار الشرق، من إسطنبول متأخرًا وبلغ قارص في 8 تشرين الثاني/نوفمبر. ورغم ملاءمة الوضع لم يتجه نحو الشاه بل قضى الشتاء في وان، وانتقل إلى أرضروم إثر هجوم الشاه؛ فضاع موسم حملة.", "d155e6f3"]},
"OLAYLAR_H7_ASAMA:1605-11-06:0":{"b": ["هزيمة جغالزاده سنان باشا قرب بحيرة أورمية (صوفيان)", "7438fec4"], "d": ["تزعزع موقف سنان باشا، الذي سار في موسم حملة 1605 لاسترداد تبريز، عندما انفصل والي أرضروم كوسه سفر باشا عن الجيش الرئيس وسقط في الأسر. وألحق هجوم الشاه عباس المفاجئ بالجيش هزيمة ثقيلة في ناحية بحيرة أورمية؛ فانسحب سنان باشا أولًا إلى وان ثم إلى ديار بكر. وإعدامه والي حلب جانبولاد أوغلو حسين باشا بحجة تأخره في النجدة أشعل تمردًا كبيرًا في الأناضول؛ وبعد وفاة سنان باشا أخذ الشاه عباس كنجة وشيروان وشماخي.", "8e130829"]},
"OLAYLAR_H7_ASAMA:1610-03-26:0":{"b": ["حملة قويوجو مراد باشا إلى تبريز — لم يقع لقاء في آجي تشاي", "3c0a0a5d"], "d": ["سار الصدر الأعظم قويوجو مراد باشا، الذي قمع تمردات الجلالية وأرسى السكون في الأناضول، عبر أرضروم وحسن قلعة وجالديران وخوي نحو الشاه عباس الذي بلغ أنه ينتظر في تبريز. وتواجه الجيشان في موضع آجي تشاي شمال تبريز لكن لم يقع قتال؛ واستمرت المراسلات. ولاقتراب الشتاء وقلة العتاد والمؤن انسحب الباشا عبر أخلاط ووان وبتليس إلى ديار بكر، وتوفي هناك وهو يعد لحملة جديدة في الصيف التالي (5 آب/أغسطس 1611).", "289fa3b6"]},
"OLAYLAR_H7_ASAMA:1615-04-23:0":{"b": ["استئناف الحرب العثمانية-الصفوية — الصدر الأعظم أوكوز محمد باشا يخرج في حملة الشرق", "ef32fa31"], "d": ["بعد معاهدة ناصوح باشا 1612، ولعدم ورود خبر من إنجيلي مصطفى جاووش الذي أُرسل سفيرًا إلى إيران، كُلّف الصدر الأعظم محمد باشا بحملة الشرق وأتم استعداداته وعبر إلى أسكدار. وعند الشروع في المسير ورد خبر أن إنجيلي جاووش وسفير إيران بورون قاسم خان بلغا وان باتفاق وهدايا، لكن الحملة لم تؤجَّل. وقضى الصدر الأعظم الشتاء في حلب.", "5c279a1a"]},
"OLAYLAR_H7_ASAMA:1616-09-12:0":{"b": ["حصار يريفان — رُفع بعد خمسة وخمسين يومًا بلا نتيجة", "64a4ecb6"], "d": ["في نيسان/أبريل 1616 خرج الصدر الأعظم من حلب بجيش كبير وبلغ يريفان عبر طريق أرضروم-قارص. ولظن أن القلعة ستسلم بسهولة لم تُجلب المدافع الثقيلة؛ فاستمر الحصار خمسة وخمسين يومًا دون عتاد. ورُفع الحصار إثر استشهاد أغا الإنكشارية موسلو أغا وتكلي محمد باشا، وعزوف الجند، وتقدم الفصل، وانسحب الجيش إلى أرضروم. وعُزل محمد باشا في تشرين الثاني/نوفمبر 1616 وحل محله خليل باشا.", "823b20af"]},
"OLAYLAR_H7_ASAMA:1618-09-10:0":{"b": ["هزيمة سراب (بول-إ شكسته) — حملة خليل باشا على إيران", "d323ed03"], "d": ["سار خليل باشا، الذي صار سردارًا بدل أوكوز محمد باشا، على إيران من جديد سنة 1618. وانتهت المعركة في موضع بول-إ شكسته بين تبريز وأردبيل بهزيمة الجيش العثماني. وبعد هذه الهزيمة، التي تُذكر في المصادر كذلك باسم معركة سراب، وُقّعت معاهدة سراب في الشهر نفسه.", "f2c187de"]},
"OLAYLAR_H7_ASAMA:1625-11-13:0":{"b": ["حصار بغداد على يد حافظ أحمد باشا — استمر سبعة أشهر وعشرين يومًا دون نتيجة", "764acb0a"], "d": ["سار العثمانيون، الذين فقدوا بغداد سنة 1623، بقيادة الصدر الأعظم والسردار حافظ أحمد باشا لاستعادتها. وفي المجلس المنعقد في كركوك لم يُقبل أولًا اقتراح إمساك المضائق، فحاصر الجيش بغداد مباشرة. وكان الباشا يدخل الخنادق بنفسه؛ ودُخلت المدينة في اليوم الثاني والسبعين من لغم فُجّر، لكن الجند صُدّوا. وفي آذار/مارس 1626 جاء الشاه عباس بـ30.000 رجل نجدةً فبقي الجيش بين نارين؛ وتكبد خسائر فادحة في هجوم الشاه في 7 حزيران/يونيو. ولما نفدت المؤن وفتك الحر والحمى بالجند رُفع الحصار وانسحب الجيش إلى ديار بكر.", "350e3f52"]},
"OLAYLAR_H7_ASAMA:1630-10-06:0":{"b": ["حصار بغداد على يد خسرو باشا — رُفع بعد تسعة وثلاثين يومًا", "18de5581"], "d": ["بعد انتصار مهربان (Mihriban) (5 أيار/مايو 1630) دخل الصدر الأعظم خسرو باشا همذان وأحرقها ودمّرها، ثم بدل المسير إلى قزوين عاد إلى الهدف الأصلي بغداد بقرار مجلس الحرب المنعقد في درگزين (Dergezîn). وبلغ الجيش ضواحي بغداد في أوائل آب/أغسطس وحاصر المدينة في 6 تشرين الأول/أكتوبر. وتكبد خسائر كبيرة في الغارة الخارجة من الحامية الإيرانية في 26 تشرين الأول/أكتوبر وفي الهجوم العام في 9 تشرين الثاني/نوفمبر؛ ورُفع هذا الحصار الثاني بعد فقدان بغداد دون أن يحقق نتيجة. وانسحب الجيش إلى الموصل.", "4b3ed1a0"]},
"OLAYLAR_H7_ASAMA:1700-01-01:0":{"b": ["ردّ إينه بختي (ليبانتو) إلى العثمانيين بموجب كارلوفتش", "9ca4f9dd"], "d": ["ظلت إينه بختي، التي سقطت بيد البندقية في تموز/يوليو 1687 مع القلاع المجاورة بعد مقاومة طويلة خلال حروب 1683-1699، في يد البنادقة حتى بعد سنة من معاهدة كارلوفتش، ثم عادت إلى العثمانيين. فصارت القلعة عند مدخل خليج كورنثة بذلك في الإدارة العثمانية قبل المورة بخمس عشرة سنة.", "782654b8"]},
"OLAYLAR_H7_ASAMA:1733-07-19:0":{"b": ["طوبال عثمان باشا يهزم نادر في دوجوم — رُفع حصار بغداد", "7ae1fc9e"], "d": ["في مواجهة نادر الذي حاصر بغداد في كانون الثاني/يناير 1733، هزم الجيش بقيادة طوبال عثمان باشا الذي أُرسل لنجدة بغداد قوات نادر في دوجوم قرب سامراء؛ وانسحب نادر المصاب إلى همذان، ورُفع الحصار الذي استمر شهورًا. لكن النصر لم يدم: فقد دخل نادر العراق ثانية في نهاية العام نفسه وهزم القوات العثمانية في أكدربند شمال كركوك؛ وقُتل طوبال عثمان باشا خلال هذه الحروب ودُفن في كركوك.", "6444aec6"]},
"OLAYLAR_H7_ASAMA:1743-02-25:0":{"b": ["حملة نادر شاه على العراق — بدأت آخر حرب عثمانية-إيرانية وسقطت كركوك", "ba014bf5"], "d": ["شنّ نادر شاه، الذي أقام ثمانية عشر شهرًا في داغستان وجورجيا، وقد رفض العثمانيون طلب الاعتراف بالجعفرية مذهبًا خامسًا، حملة جديدة على العثمانيين سنة 1743 ودخل كركوك بجيش كبير. ولم يستطع تحقيق النجاح نفسه في الموصل؛ واضطر إلى رفع الحصار. وهذه الحرب هي آخر حرب عثمانية-إيرانية، وانتهت بمعاهدة كردان 1746.", "5515afec"]},
"OLAYLAR_H7_ASAMA:1744-07-29:0":{"b": ["حصار نادر شاه لقارص — دام شهرين دون نتيجة", "a3ea61d9"], "d": ["كان الأمير الصفوي صافي ميرزا، الذي لجأ إلى العثمانيين، يدّعي الحق في عرش إيران؛ وبحسب الخطة كان سر عسكر قارص سيأخذه عبر تبريز إلى أصفهان ويُجلسه على العرش، وكان العثمانيون قد فتحوا ثلاث جبهات على إيران. فسار نادر شاه إلى قارص وحاصر القلعة. ولم يحصل من الحصار الذي دام شهرين على نتيجة.", "42fc48b5"]},
"OLAYLAR_H7_ASAMA:1745-08-21:0":{"b": ["هزيمة كاغافرد (Kağaverd) — تفرق جيش يغن محمد باشا", "7caf6f22"], "d": ["في العام التالي لحصار قارص ألحق نادر شاه بالقوات العثمانية بقيادة يغن محمد باشا هزيمة في موضع كاغافرد. ثم عاد إلى أصفهان. وتخليه عن إصراره على الاعتراف بالجعفرية مهّد الطريق لمعاهدة كردان في العام التالي.", "3992b8ed"]},
"OLAYLAR_ILIRYA0072:1779-01-01:0":{"b": ["استيلاء القوات السعودية الوهابية على إمارة حائل — كانت الإدارة بيد أسرة ابن علي من عشيرة عبدة", "2d29ceb9"], "d": ["حين استولت قوات الدولة السعودية الأولى على إمارة حائل، كانت إدارة المدينة بيد أسرة ابن علي من عشيرة عبدة من قبيلة شمر. وظلت هذه الأسرة تحكم حائل حتى استيلاء عبد الله بن رشيد على الإمارة عام 1835؛ ولم تتأسس أسرة آل رشيد إلا في ذلك التاريخ. ويظهر حائل في الأطلس حتى اليوم بلا صاحب حتى عام 1836، مع أن المصدر يذكر أمير المدينة باسمه في عام 1820.", "bc2aa4ea"]},
"OLAYLAR_ILIRYA0072:1806-01-01:0":{"b": ["انتقال جزر كفارنر إلى مملكة نابليون الإيطالية وانتقال خليج كوتور إلى الإدارة الروسية", "c5e411c8"], "d": ["بعد معاهدة بوجون، ألحقت جزر كفارنر — خلافًا لدالماسيا — لا بفرنسا مباشرة بل بمملكة نابليون الإيطالية؛ ولم تدخل في الولايات الإليرية إلا عام 1809. أما في خليج كوتور فقد انتهت الإدارة النمساوية وأُقيمت إدارة روسية بين عامي 1806 و1807؛ ولم ينتقل الخليج إلى فرنسا إلا عام 1807. وهذان التمييزان لا يمكن أن تفي بهما نافذة «فرنسا» الواحدة في الأطلس.", "ec06d97d"]},
"OLAYLAR_ILIRYA0072:1806-02-01:0":{"b": ["انتقال دالماسيا إلى الإدارة الفرنسية — تطبيق معاهدة بوجون (براتيسلافا)", "00bfe4f6"], "d": ["ألزمت معاهدة بوجون (براتيسلافا/برسبورغ) المؤرخة في 26 ديسمبر 1805 النمسا بالتخلي عن إستريا ودالماسيا وجميع جزر الأدرياتيك. وتسلّمت فرنسا الإدارة فعليًا في فبراير 1806؛ وبقيت زادار مركزًا للمندوب العام، وتولى هذه المهمة بين عامي 1806 و1810 البندقي فيتشنزو داندولو. وضُمّت دالماسيا إلى الولايات الإليرية بعد معاهدة شونبرون عام 1809. وبذلك انتهت الإدارة النمساوية الأولى التي استمرت منذ عام 1797 — وكان هذا العهد يظهر في الأطلس حتى اليوم نمساويًا دون انقطاع.", "b8a55f1c"]},
"OLAYLAR_ILIRYA0072:1813-01-01:0":{"b": ["استرداد النمسا للولايات الإليرية ودالماسيا — نهاية إدارة نابليون", "1b2ac942"], "d": ["في أواخر عام 1813 استردت القوات الهابسبورغية المنطقة الواقعة جنوب نهر سافا وأُعيد تأسيس تنظيم الحدود القديم؛ ودخل الجيش النمساوي إستريا في أكتوبر 1813. وصارت كارلوفاتس منذ ذلك التاريخ جزءًا من مملكة إليريا النمساوية. وطُويت كذلك فترة الإدارة الفرنسية في دالماسيا عام 1813. وأُقرّ رسميًا انتماء المنطقة إلى النمسا بصلح باريس عام 1814 وقرارات مؤتمر فيينا عام 1815.", "a5c337df"]},
"OLAYLAR_KURULUS_GERI_1021:0630-01-11:0":{"b": ["فتح مكة: المدينة تنتقل إلى دولة المدينة", "8435e73c"], "d": ["فتح النبي مكة (20 رمضان 8 / 11 كانون الثاني 630).", "865a73bd"]},
"OLAYLAR_KURULUS_GERI_1021:0632-06-08:0":{"b": ["وفاة النبي: مكة تتبع الخلفاء الراشدين", "b65e8cd1"], "d": ["توفي النبي محمد في 13 ربيع الأول 11 / 8 حزيران 632؛ ودخلت مكة في إدارة الخلفاء الراشدين.", "99716bea"]},
"OLAYLAR_KURULUS_GERI_1021:0638-01-01:0":{"b": ["تأسيس الكوفة", "617d0f35"], "d": ["أُسست الكوفة مدينة حامية، وغالبًا في سنة 17 (638)؛ وصارت مركز الخلافة الراشدة في العراق (اليوم غير معروف).", "abaf8837"]},
"OLAYLAR_KURULUS_GERI_1021:0661-01-01:0":{"b": ["استشهاد الإمام علي في الكوفة؛ والكوفة تنتقل إلى الحكم الأموي", "94fb307d"], "d": ["استشهد الإمام علي في مسجد الكوفة على يد ابن ملجم (661)؛ وانتهى العهد الراشدي، ودخلت المدينة في الإدارة الأموية (دقة السنة؛ ولم تُكتب فترة الزبيريين 680-691 منفصلة في السجل).", "a58ed98f"]},
"OLAYLAR_KURULUS_GERI_1021:0661-07-29:0":{"b": ["معاوية يأخذ البيعة: مكة تدخل في الحكم الأموي", "d6dcc232"], "d": ["أخذ معاوية البيعة في 25 ربيع الأول 41 / 29 تموز 661؛ وارتبطت مكة بالولاة الأمويين (لا يوجد يوم خاص بمكة، بل يوم الدولة).", "16cecb18"]},
"OLAYLAR_KURULUS_GERI_1021:0670-01-01:0":{"b": ["تأسيس القيروان (عقبة بن نافع، الأمويون)", "7409e9ae"], "d": ["أسس الوالي الأموي عقبة بن نافع القيروان عام 670 قاعدةً لإفريقية.", "b2240f4e"]},
"OLAYLAR_KURULUS_GERI_1021:0683-11-27:0":{"b": ["ابن الزبير يعلن خلافته في مكة: مكة تخرج من الأمويين", "9e31ca5c"], "d": ["بلغ مكة نبأ وفاة يزيد (27 تشرين الثاني 683)؛ وأعلن عبد الله بن الزبير الخلافة ومركزها مكة (64/683).", "212a96b5"]},
"OLAYLAR_KURULUS_GERI_1021:0692-10-01:0":{"b": ["الحجاج يستولي على مكة: المدينة تعود إلى الحكم الأموي", "48dd6e68"], "d": ["في نهاية حصار الحجاج بن يوسف عادت مكة إلى الحكم الأموي في 14 جمادى الأولى 73 / 1 تشرين الأول 692.", "25eedec5"]},
"OLAYLAR_KURULUS_GERI_1021:0745-01-01:0":{"b": ["عبد الرحمن بن حبيب يثور: القيروان تخرج من الإدارة الأموية", "4c7a0da0"], "d": ["بثورة عبد الرحمن بن حبيب عام 745 خرجت القيروان من الولاية الأموية؛ وحتى 761 فترة وسيطة حبيبية/خارجية (فراغ مع بيان المالك).", "69dac839"]},
"OLAYLAR_KURULUS_GERI_1021:0749-09-02:0":{"b": ["الجيش العباسي يستولي على الكوفة", "0191709e"], "d": ["استولى الجيش العباسي على الكوفة في 14 محرم 132 (2 أيلول 749)؛ وانتقلت المدينة من الأمويين إلى العباسيين.", "998fc494"]},
"OLAYLAR_KURULUS_GERI_1021:0750-08-05:0":{"b": ["سقوط الدولة الأموية: مكة تنتقل إلى الحكم العباسي", "382e4d6e"], "d": ["قُتل آخر الخلفاء الأمويين مروان الثاني في 26 ذي الحجة 132 / 5 آب 750؛ ودخلت مكة في ولاية الحرمين العباسية (لا يوجد يوم خاص بمكة — يوم نهاية الدولة، تقريب مبيَّن).", "710c6ec7"]},
"OLAYLAR_KURULUS_GERI_1021:0761-01-01:0":{"b": ["محمد بن الأشعث المعيَّن من العباسيين يستولي على القيروان", "71af9f79"], "d": ["استولى محمد بن الأشعث على القيروان باسم العباسيين في سنة 144 (761).", "a71fe419"]},
"OLAYLAR_KURULUS_GERI_1021:0762-01-01:0":{"b": ["الخليفة المنصور يبدأ بناء بغداد (مدينة السلام)", "844a94d5"], "d": ["بدأت أعمال بناء المدينة المقامة على ضفة دجلة عام 762؛ وصارت العاصمة الدائمة للعباسيين (اليوم غير معروف، والسنة وحدها مؤكدة).", "750c6eb1"]},
"OLAYLAR_KURULUS_GERI_1021:0800-01-01:0":{"b": ["إبراهيم بن الأغلب يصبح واليًا: الأغالبة في القيروان", "f7279ba9"], "d": ["عيّن هارون الرشيد إبراهيم بن الأغلب واليًا على إفريقية؛ وجعل الأغالبة (800-909) القيروان عاصمة.", "3b6e9426"]},
"OLAYLAR_KURULUS_GERI_1021:0909-01-01:0":{"b": ["الفاطميون يستولون على القيروان؛ وينتهي الأغالبة", "021693e0"], "d": ["فرّ زيادة الله الثالث إلى مصر عام 909؛ وانتقلت القيروان إلى الفاطميين.", "a6422efd"]},
"OLAYLAR_KURULUS_GERI_1021:0945-12-19:0":{"b": ["البويهي أحمد (معز الدولة) يدخل بغداد؛ وتنتقل المدينة إلى الحكم البويهي", "31accd4a"], "d": ["دخل أحمد بغداد في 11 جمادى الأولى 334 (19 كانون الأول 945)؛ وجعله الخليفة المستكفي أمير الأمراء، وانتقلت المدينة إلى حكم البويهيين (ودخلت الكوفة أيضًا في حكم البويهيين 945-1055؛ وأُخذ يوم الكوفة من بغداد الجارة).", "11f31be7"]},
"OLAYLAR_KURULUS_GERI_1021:0969-01-01:0":{"b": ["الخطبة في مكة باسم الفاطميين (358/969)", "3f069fea"], "d": ["أمر أمير مكة جعفر بن محمد بالخطبة باسم الفاطميين (358/969، دقة السنة)؛ والدولة المتبوعة هي الفاطميون.", "2256892c"]},
"OLAYLAR_KURULUS_GERI_1021:0972-10-02:0":{"b": ["الزيريون في القيروان (بلكين بن زيري والي إفريقية)", "5494e662"], "d": ["حكم بلكين بن زيري إفريقية باسم الخليفة الفاطمي؛ وسيطر الزيريون (972-1057) على القيروان (يذكر TDV السنة، واليوم من نهاية بطاقة الأسرة).", "ffcba4c5"]},
"OLAYLAR_KURULUS_GERI_1021:1057-01-01:0":{"b": ["نهب الهلاليين: المعز بن باديس ينسحب إلى المهدية وتنتهي السيادة الزيرية على القيروان", "4dbbdff5"], "d": ["نحو سنة 449 (1057) نهب الهلاليون القيروان؛ وانسحب الزيريون إلى المهدية؛ ولا يمكن تتبع مالك المدينة سنةً بسنة في المصادر حتى 1229 (فراغ مبيَّن).", "8bebfdc7"]},
"OLAYLAR_KURULUS_GERI_1021:1085-05-25:0":{"b": ["ألفونسو السادس يدخل طليطلة: المدينة تنتقل إلى حكم قشتالة", "3b72bb5f"], "d": ["Treccani: دخل ألفونسو السادس طليطلة في 25 أيار 1085؛ وصارت المدينة بعد سنتين عاصمة قشتالة (يذكر TDV في مادة طليطلة السنة وحدها: 478/1085؛ ويوم التسليم 8 أيار 1085 مسجل في سجل آخر في الكرونولوجيا).", "fa2c9677"]},
"OLAYLAR_MISIR1801:1801-05-14:0":{"b": ["استرداد دمياط من الفرنسيين — إخلاء قلعة اللسبة", "06b1e7b0"], "d": ["أُرسلت إلى دمياط قوة بقيادة إبراهيم باشا من جيش الصدر الأعظم. وفي صباح 14 أيار/مايو، حين كان الهجوم على قلعة اللسبة التي تحمي دمياط قد أُعدّ، تبيّن أن الفرنسيين أخلوا القلعة وأن الحامية انسحبت؛ وأُخذ أيضًا قلعتان صغيرتان تابعتان لها. وصارت دمياط ثاني مدينة على مصبات النيل تخرج من السيطرة الفرنسية بعد رشيد التي سقطت في نيسان/أبريل.", "2eb4936c"]},
"OLAYLAR_MISIR1801:1801-06-27:0":{"b": ["تسلّم القاهرة من الفرنسيين — استسلام بيليار", "7a11bb5e"], "d": ["في أثناء العملية المشتركة للقوات العثمانية والبريطانية على مصر وقّع الجنرال بيليار، قائد القوات الفرنسية في القاهرة، الاستسلام. وخرجت مع القاهرة السويس أيضًا من السيطرة الفرنسية، وكان الفرنسيون قد استولوا عليها في تشرين الثاني/نوفمبر 1798. وسيكتمل بعد شهرين إغلاق الاحتلال في الإسكندرية، وسيستمر الإخلاء من البلاد حتى تشرين الأول/أكتوبر.", "e8dac3f4"]},
"OLAYLAR_MISIR1801:1801-08-31:0":{"b": ["تسلّم الإسكندرية من الفرنسيين — استسلام مينو", "cd50663c"], "d": ["حوصر الجنرال مينو، القائد العام لجيش الشرق، في الإسكندرية في 17 آب/أغسطس؛ وفي 21 آب/أغسطس أخذ الإنجليز قلعة المعبد (مارابو) قرب المدينة، وفي 31 آب/أغسطس وقّع مينو استسلام الجيش. وبدأت عودة القوات الفرنسية إلى فرنسا في 2 أيلول/سبتمبر. وهكذا انتهى الاحتلال الذي بدأ بالنزول في الإسكندرية في حزيران/يونيو 1798 في المدينة التي بدأ منها.", "22e807c1"]},
"OLAYLAR_OK106:1571-01-01:0":{"b": ["تقدّم بولندا بخط دنيبر — تأسيس كريمنتشوك", "1bc86966"], "d": ["أقامت بولندا-ليتوانيا بلدة حدودية جديدة عند ملتقى دنيبر الأوسط الذي كان معبرًا لغارات القرم؛ وبعد خمس وعشرين سنة أضيفت إليها قلعة. وبذلك نزل خط السيطرة البولندي إلى الشاطئ الشمالي لسهوب زابوروجيه، وارتبط هذا الممر من النهر لأول مرة بحامية دائمة لدولة. وستنتقل البلدة في القرن التالي إلى نظام الهتمانية بوصفها مركز فوج قوزاقي.", "4d022f2b"]},
"OLAYLAR_OK106:1616-01-01:0":{"b": ["ظهور أومان على خط يديسان الحدودي البولندي", "2e6551ab"], "d": ["وردت أومان في الوثائق لأول مرة بوصفها مستوطنة في الطرف الجنوبي الشرقي لمنطقة براتسلاف الخاضعة لإدارة بولندا. وكان موقعها على طرق الغارات المتجهة شمالًا لخانية القرم؛ واستقرار بلدة دائمة فيها يدل على أن الشريط الخالي من السهوب بين الدولتين بدأ يضيق من الشمال. وبقيت المدينة طوال القرنين التاليين أقصى مستوطنة بولندية كبيرة جنوبًا على هذا الخط.", "7a425b4c"]},
"OLAYLAR_OK106:1638-01-01:0":{"b": ["تقدّم خط دفاع موسكو في السهوب — تشوغويف", "c68d36d3"], "d": ["أقام الزعيم القوزاقي ياكيف أوستريانين ورجاله، وقد لجؤوا إلى موسكو بعد تمردهم في بولندا، مستوطنة حدودية على نهر دونيتس. وكانت هذه من أولى القفزات الكبرى لخط الدفاع الذي بنته موسكو ضد غارات القرم نحو السهوب؛ وفي نصف القرن التالي نشأت على الخط نفسه بلدات سومي وإيزيوم وباخموت تباعًا. واستمرت المستوطنة مركز سرية تابعة لفوج خاركوف حتى 1765.", "3fdefaaa"]},
"OLAYLAR_OK106:1652-01-01:0":{"b": ["تأسيس أوكرانيا السلوبودية — سومي وحزام المستوطنات السهبية", "ab7abf59"], "d": ["أقام فلاحون وقوزاق جاؤوا من فوج بيلا تسيركفا في أوكرانيا الضفة اليمنى، بقيادة العقيد هيراسيم كوندراتيف، بلدة جديدة على نهر بسيول؛ وبعد أربع سنوات حصّن حاكم موسكو القلعة. وكانت موجة الهجرة هذه بداية نظام أوكرانيا السلوبودية الذي فتح للاستيطان السهوب الخالية على الحدود الجنوبية لموسكو: أُعطي القادمون إعفاءً ضريبيًّا مقابل أداء حراسة الحدود. وصارت سومي من 1658 إلى 1765 مركز الفوج الذي يحمل اسمها.", "fc9a8983"]},
"OLAYLAR_OK106:1703-05-17:0":{"b": ["بناء ينيكالة — إغلاق مضيق كرتش", "d9067015"], "d": ["بعد تنازل 1700 عن آزاق لروسيا، تحول المدخل الوحيد للبحر الأسود إلى بحر آزوف إلى خط حدودي استراتيجي. فأنشأت الدولة العثمانية حصنًا جديدًا على بعد عشرة كيلومترات شمال شرق مدينة كرتش، في موضع رأس أقنتي (Akıntı Burnu)، لتضع عبور المضيق في مدى المدافع؛ وسُمّيت القلعة ينيكالة، أي «القلعة الجديدة» بعينها. وبقيت القلعة سبعين سنة قفل القرم الشرقي، وتُنازل عنها مع كرتش لروسيا بالمادة التاسعة عشرة من معاهدة قينارجة الصغرى سنة 1774.", "8f8533a1"]},
"OLAYLAR_OK106:1754-01-01:0":{"b": ["قلعة القديسة إليزابيث — الحدود الجنوبية لروسيا تبلغ خط الغارات العثماني-القرمي", "b9097272"], "d": ["بنت روسيا على أرض القوزاق الزابوروجيين قلعة جديدة تحمل اسم القديسة إليزابيث. وكان مبررها المعلن حماية المهاجرين البلقانيين المستقرين في صربيا الجديدة من الغارات العثمانية والقرمية؛ أي أن الخط الحدودي الروسي نزل لأول مرة إلى وسط السهوب حتى طرق الغارات. وصار هذا المخفر المتقدم بعد عشرين سنة نقطة انطلاق التوسع في شمال البحر الأسود الذي سيبدأ بقينارجة الصغرى.", "8ac6527e"]},
"OLAYLAR_OK106:1847-05-31:0":{"b": ["معاهدة أرضروم الثانية — حدود شط العرب وترك ساحل خوزستان", "5d1f9103"], "d": ["سُوّي النزاع الحدودي العثماني-الإيراني الذي لم يُحلّ منذ أكثر من قرن بمعاهدة ثانية وُقّعت في أرضروم بعد مفاوضات طويلة جرت بوساطة بريطانية وروسية. فبقي مجرى شط العرب كله عثمانيًّا؛ وفي المقابل تُركت المستوطنات على الضفة الشرقية للنهر — ومنها ميناء المحمرة وجزيرة عبادان المقابلة له — للقاجار. وهكذا خرج الشريط الساحلي لخوزستان، الذي عُدّ تحت الإدارة العثمانية منذ ضم البصرة سنة 1546، من اليد بعد ثلاثمئة سنة. أما محمد خورشيد باشا، عضو لجنة الحدود التي أُنشئت لتثبيت الخط الذي رسمته المعاهدة على الأرض، فجال في المنطقة بين 1848 و1852 وكتب «سياحتنامة حدود» (Seyâhatnâme-i Hudûd).", "8fe2f887"]},
"OLAYLAR_OK107:1514-09-15:0":{"b": ["الانسحاب من تبريز — نهاية احتلال دام أسبوعًا والعودة عبر قارص وبايبورت", "fd1542e3"], "d": ["بعد انتصار جالديران دخل السلطان ياووز سليم تبريز في 6 أيلول/سبتمبر وبقي في المدينة نحو أسبوع؛ ورحّل إلى إسطنبول خزينة الشاه إسماعيل وبعضًا من صناع المدينة وعلمائها مع أسرهم. وأراد قضاء الشتاء في قره باغ ومتابعة الحملة في العام التالي، لكنه عدل عن هذا المخطط إثر معارضة الإنكشارية، فعاد الجيش عبر قارص وبايبورت. وهكذا لم تبقَ تبريز في يد العثمانيين: فجالديران كانت انتصار ميدان، أما المكسب الإقليمي الدائم فجاء في العام التالي بحملة كماخ وديار بكر وشرق الأناضول.", "9cc5fc19"]},
"OLAYLAR_OK107:1515-09-19:0":{"b": ["ضم نصيبين وديريك وسيلوبي إلى الدولة العثمانية — الذراع الجنوبي لديار بكر", "c3621d22"], "d": ["بعد تسلّم آمد وإنشاء بكلربك ديار بكر، وباستمالة إدريس البدليسي أمراء الكرد في المنطقة، انتقلت نصيبين وديريك وسيلوبي جنوب سهل ماردين إلى الإدارة العثمانية. ونُظّمت هذه المواضع مراكز نواحٍ وأقضية للبكلربك الجديد؛ وتُرك بعضها، مثل جزيرة ابن عمر (Cizre)، لأمرائها المحليين بوضع «يورتلوك-أوجاقلك». وبذلك بلغت الحملة في شرق الأناضول التي بدأت بعد جالديران الجزيرة العليا.", "f975424e"]},
"OLAYLAR_OK109:1918-10-28:0":{"b": ["إعلان استقلال تشيكوسلوفاكيا — أولى الدول الخلف للإرث الهابسبورغي", "8f40155f"], "d": ["إثر فقدان النمسا-المجر قوتها في الحرب وما شهدته البلاد من إضرابات ومظاهرات وانتفاضات، أعلن المجلس الوطني في 28 تشرين الأول/أكتوبر 1918 استقلال تشيكوسلوفاكيا. وتشكّلت جمعية وطنية مؤقتة على أساس وضع انتخابات 1911، وباشرت الحكومة عملها في 14 تشرين الثاني/نوفمبر 1918 وقد أُسندت رئاستها إلى ماساريك. وحازت الدولة الجديدة مكانتها في القانون الدولي بمعاهدة سان جرمان أون لاي (10 أيلول/سبتمبر 1919). وفي الخريطة تظهر تشيكوسلوفاكيا في 11 تشرين الثاني/نوفمبر 1918؛ وإعلان الاستقلال يسبق ذلك بأسبوعين.", "80a8405f"]},
"OLAYLAR_OK109:1918-10-29:0":{"b": ["إعلان دولة السلوفين والكروات والصرب — البرلمان الكرواتي (الساببور) يقطع الصلات الهابسبورغية", "2e5ae559"], "d": ["أعلن البرلمان الكرواتي (الساببور) في 29 تشرين الأول/أكتوبر 1918 قطع جميع الروابط الدستورية-القانونية لكرواتيا وسلافونيا ودلماسيا مع النمسا-المجر؛ وفي اليوم نفسه احتُفل في ليوبليانا بتأسيس دولة السلوفين والكروات والصرب. وفي البوسنة والهرسك سلّمت إدارة النمسا-المجر السلطة في 1 تشرين الثاني/نوفمبر 1918 إلى حكومة المجلس الوطني. واستمرت هذه الدولة إلى أن أُعلنت مملكة الصرب والكروات والسلوفين في بلغراد في 1 كانون الأول/ديسمبر 1918.", "9e0cf3b3"]},
"OLAYLAR_OK109:1918-10-30:0":{"b": ["تأسيس جمهورية النمسا — النواة الألمانية للإرث الهابسبورغي", "1ec8b06f"], "d": ["إثر إعلان قيام تشيكوسلوفاكيا في براغ في 29 تشرين الأول/أكتوبر، ودولة الصرب والكروات والسلوفين في زغرب، أقام ألمان النمسا جمهورية النمسا في 30 تشرين الأول/أكتوبر. وفي اليوم نفسه كانت الدولة العثمانية توقّع هدنة مودروس؛ فتجاور نهاية الإمبراطوريتين في التقويم.", "3772c9f7"]},
"OLAYLAR_OK109:1918-10-31:0":{"b": ["ثورة الأقحوان — كارولي رئيسًا للوزراء وبدء تفكك الملكية في المجر (أُعلنت الجمهورية الشعبية في 16 تشرين الثاني/نوفمبر)", "d7780d2e"], "d": ["لما تبيّن انهزام الدول المركزية قويت المشاعر المعادية للملكية في المجر وحدث انزياح نحو اليسار. وفي 31 تشرين الأول/أكتوبر 1918 أصبح الكونت ميهاي كارولي، ذو الآراء الراديكالية، رئيسًا للوزراء إثر «ثورة الأقحوان»، ثم أُعلنت الجمهورية الشعبية؛ وانتُخب كارولي رئيسًا أصيلًا للجمهورية في 11 كانون الثاني/يناير 1919.", "0a48f4b7"]},
"OLAYLAR_OK109:1918-11-03:0":{"b": ["هدنة فيلا جوستي — النمسا-المجر تلقي السلاح وترينتو وتريستي تنتقلان إلى إيطاليا", "75da65fb"], "d": ["عجّل توقيع الإمبراطور كارل هدنة مع الإيطاليين في فيلا جوستي في 3 تشرين الثاني/نوفمبر 1918 في تفكك الإمبراطورية. ويسجل TDV هذا اليوم صراحة بوصفه يوم إلقاء النمسا السلاح: «قبلت النمسا المهزومة إلقاء السلاح في 3 تشرين الثاني/نوفمبر، وألمانيا في 11 تشرين الثاني/نوفمبر.» وفي الخريطة تنتقل ترينتو وتريستي في هذا اليوم من النمسا إلى إيطاليا — وهذا أول انتقال إقليمي ظاهر في الخريطة للتفكك.", "a86d1725"]},
"OLAYLAR_OK109:1918-11-11:0":{"b": ["استقلال بولندا — مجلس الوصاية يسلّم قيادة الجيش إلى بيلسودسكي", "e8b546cf"], "d": ["عاد يوزف بيلسودسكي إلى وارسو في 10 تشرين الثاني/نوفمبر 1918. وفي 11 تشرين الثاني/نوفمبر سلّمه مجلس الوصاية قيادة الجيش؛ وبعد أيام تخلى له أيضًا عن مهمة تشكيل الحكومة الوطنية.", "578314ea"]},
"OLAYLAR_OK109:1918-11-14:0":{"b": ["الجيش الصربي يحتل بيتش (بيچوي Peçuy) — بدء الاحتلال الصربي لبارانيا", "68f0695f"], "d": ["وقعت بيتش، ذات الأهمية الاستراتيجية بسبب مناجم الفحم، تحت الاحتلال الصربي في 14 تشرين الثاني/نوفمبر 1918. واستمر الاحتلال الصربي لبيتش وولاية بارانيا حتى آب/أغسطس 1921.", "7222b6bd"]},
"OLAYLAR_OK109:1918-11-14:1":{"b": ["الجيش الصربي يحتل تيميشوارا (تمشفار) — بدء الإدارة العسكرية الصربية لبانات", "3cc85350"], "d": ["احتلت القوات الصربية تيميشوارا في 14 تشرين الثاني/نوفمبر 1918، وحلّت الحرس الوطني، وتولت الإدارة العسكرية لبانات، وبعد وقت قصير الإدارة المدنية أيضًا. وفي مطلع كانون الأول/ديسمبر دخلت المدينة قوات فرنسية كذلك؛ ولم تُقَم الإدارة الرومانية إلا في تموز/يوليو-آب/أغسطس 1919.", "78697a6b"]},
"OLAYLAR_OK109:1918-11-19:0":{"b": ["القوات الصربية تدخل سيغتفار — احتلال جنوب شومغي", "a06b1907"], "d": ["تقدّم الجيش الصربي شمال الخط الذي رسمه الاتفاق العسكري في بلغراد، فدخل 220 جنديًّا بقيادة أوبرين بتروفيتش، في الليلة الفاصلة بين 18 و19، مدينة سيغتفار مركز قضاء شومغي؛ وأُمسكت قرى القضاء كذلك بهذه القوة. واستمر الاحتلال حتى آب/أغسطس 1921؛ وتركت تريانون سيغتفار في المجر.", "9485d5ab"]},
"OLAYLAR_OK109:1918-12-01:0":{"b": ["تأسيس مملكة الصرب والكروات والسلوفين ورومانيا الكبرى — في اليوم نفسه، دولتان", "6fd85345"], "d": ["نتيجة انفصال السلاف عن الإمبراطورية إثر تفكك النمسا-المجر واتحادهم مع صربيا، تأسست مملكة الصرب والكروات والسلوفين في 1 كانون الأول/ديسمبر 1918؛ وتبلغ مساحتها نحو 250.000 كم2 وسكانها 12.000.000 نسمة. وكان أساسها قد وُضع في إعلان كورفو في 20 تموز/يوليو 1917، وكانت مجالس بودغوريتسا في 26 تشرين الأول/أكتوبر، والبوسنة والهرسك في 28 تشرين الأول/أكتوبر، ونوفي ساد في 25 تشرين الثاني/نوفمبر قد اتخذت قرار الانضمام. وفي اليوم نفسه تكونت رومانيا الكبرى بانضمام ترانسلفانيا وبوكوفينا وبيسارابيا بقرار شعوبها. وفي الخريطة تنتقل أراضي مملكة صربيا إلى يوغوسلافيا.", "4565e7a6"]},
"OLAYLAR_OK109:1918-12-01:1":{"b": ["الجيش الروماني يدخل براشوف (برَسو Brassó) ويُستقبل باحتفال", "4a917d27"], "d": ["دخل الجيش الروماني براشوف في كانون الأول/ديسمبر 1918؛ واستقبل وجهاء المدينة الرومان الجيش والجنرال برتيلو باحتفال.", "96d03f2f"]},
"OLAYLAR_OK109:1918-12-19:0":{"b": ["الجيش الإيطالي يحتل كنين", "7949dd0f"], "d": ["احتل الجيش الإيطالي كنين في 19 كانون الأول/ديسمبر 1918. واستمر الاحتلال حتى 4 نيسان/أبريل 1921 حين انسحب الجيش الإيطالي من المدينة بعد معاهدة رابالو.", "f4363313"]},
"OLAYLAR_OK109:1918-12-29:0":{"b": ["القوات التشيكوسلوفاكية تأخذ كوشيتسه (Kassa)", "0989490f"], "d": ["حين احتل الفوج 30 للمشاة الحامل اسم ألويس ييراسيك المدينة في 29 كانون الأول/ديسمبر 1918، انضمت كوشيتسه فعليًّا إلى الجمهورية التشيكوسلوفاكية.", "2453b355"]},
"OLAYLAR_OK109:1919-04-20:0":{"b": ["الجيش الروماني يدخل ساتمار (19 نيسان/أبريل) وأوراديا (فاراد، 20 نيسان/أبريل)", "3ee2bd72"], "d": ["في 19 نيسان/أبريل 1919، سبت الفصح، استقبل الوفد المحلي في ساتو مارِه برئاسة الدكتور إيلي كارول بربول الدورية الأولى للفرقة الثانية للفرسان بقيادة العقيد ريسيل عند جسر سوميش. وفي اليوم التالي، 20 نيسان/أبريل 1919، دخلت القوات الرومانية بقيادة الجنرال تراين موشويو أوراديا.", "9249e364"]},
"OLAYLAR_OK109:1919-06-28:0":{"b": ["معاهدة فرساي — إعادة الألزاس واللورين إلى فرنسا تتحول إلى قانون", "3babdfcb"], "d": ["انعقد مؤتمر باريس للسلام في 18 كانون الثاني/يناير 1919، ووُقّعت معاهدة فرساي مع ألمانيا في 28 حزيران/يونيو. وأعادت المادة 51 من المعاهدة الألزاس واللورين (ستراسبورغ، ميتز، كولمار، مولهاوس) الألمانية منذ 1871 إلى السيادة الفرنسية — لكنها ربطت الانتقال لا بيوم التوقيع بل بأثر رجعي بهدنة 11 تشرين الثاني/نوفمبر 1918. وأنتجت سلسلة المؤتمر نفسه سان جرمان مع النمسا (10 أيلول/سبتمبر 1919)، ونويي مع بلغاريا (27 تشرين الثاني/نوفمبر 1919)، وتريانون مع المجر (4 حزيران/يونيو 1920)، وسيفر مع الدولة العثمانية (10 آب/أغسطس 1920).", "4ab970de"]},
"OLAYLAR_OK109:1919-07-22:0":{"b": ["القوات الرومانية تبلغ لوغوج (لوغوش) — إدارة رومانية في شرق بانات", "f65fc73c"], "d": ["بلغ القطار الذي يحمل القوات الرومانية لوغوج في 22 تموز/يوليو 1919 الساعة 14؛ واستقبل أهل المدينة الجيش في المحطة، وألقى كلمة الاستقبال جورج دوبرين محافظ كاراش-سيفيرين، ورد الجنرال جيتيانو. وأُقيمت الإدارة الرومانية في الجزء الذي صار لرومانيا من بانات في تموز/يوليو 1919؛ وتم الانتقال القانوني بمعاهدة تريانون 1920.", "b228ed28"]},
"OLAYLAR_OK109:1919-08-03:0":{"b": ["الجيش الروماني يدخل تيميشوارا (تمشفار) — قيام الإدارة الرومانية في المدينة", "8728e1d1"], "d": ["دخلت تيميشوارا، التي دخلتها القوات الصربية في 14 تشرين الثاني/نوفمبر 1918 والفرنسية في مطلع كانون الأول/ديسمبر، الوحدات الأولى للجيش الروماني بقيادة العقيد فيرجيل إكونومو صباح 3 آب/أغسطس 1919، وقامت في المدينة الإدارة الرومانية.", "0b1627d3"]},
"OLAYLAR_OK109:1919-08-12:0":{"b": ["جيش مملكة الصرب والكروات والسلوفين (SHS) يدخل بريكموريه — موربسكا سوبوتا ولندافا تخرجان من الإدارة المجرية", "21b2ba08"], "d": ["دخلت قوات مملكة الصرب والكروات والسلوفين في 12 آب/أغسطس 1919 بريكموريه وراء نهر مورا؛ وانتهت الإدارة المجرية في المنطقة في ذلك اليوم. وتم الانتقال القانوني بمعاهدة تريانون 1920.", "3ce8a913"]},
"OLAYLAR_OK109:1919-09-10:0":{"b": ["معاهدة سان جرمان — تقلّص النمسا يتحول إلى قانون", "e7b722d5"], "d": ["وقّعت النمسا بعد الحرب مع الحلفاء معاهدة سان جرمان للسلام. وبموجب المعاهدة تعترف النمسا باستقلال المجر وتشيكوسلوفاكيا ويوغوسلافيا، وتقبل ألّا تتحد مع ألمانيا دون موافقة عصبة الأمم، وإلغاء التجنيد الإجباري، وحصر الجيش في 30.000 رجل. وهي الوثيقة التي نالت بها تشيكوسلوفاكيا مكانتها في القانون الدولي. وكان الانتقال في الخريطة قد حدث قبل سنة؛ وجاءت هذه المعاهدة فقيّدته رسميًّا.", "482c2ef4"]},
"OLAYLAR_OK109:1919-11-27:0":{"b": ["معاهدة نويي — بلغاريا تفقد تراقيا الغربية وساحل إيجه", "01f2b8c8"], "d": ["إثر انتهاء الحرب بالهزيمة اضطر القيصر فرديناند إلى طلب الهدنة والتنازل عن العرش لمصلحة ابنه بوريس (29 أيلول/سبتمبر 1918). وبمعاهدة نويي التي أنهت الحرب خسرت بلغاريا أرضًا استراتيجية لمصلحة الصرب، وفقدت تراقيا الغربية بأكملها، واضطرت إلى ترك ساحل بحر إيجه لليونان، وصادقت على أحكام معاهدة بوخارست التي أعطت دوبروجا الجنوبية لرومانيا. ومقابل هذا الانتقال في الخريطة ليس في يوم المعاهدة بل في أيار/مايو 1920 حين تبدّلت الإدارة فعليًّا: ديديأغاج (Dedeağaç) وسوفلي (Sofulu) وأوريستياذا (Orestiada) وجرمن (Çirmen) في 14 أيار/مايو، وغوموليجينه (Gümülcine) وإسكيجه (İskeçe) وديموتيقا (Dimetoka) وفريجيك (Ferecik) في 27 أيار/مايو تنتقل إلى اليونان.", "d61eb549"]},
"OLAYLAR_OK109:1920-06-04:0":{"b": ["معاهدة تريانون — المجر تفقد ثلثي أراضيها", "84aff507"], "d": ["بموجب معاهدة تريانون التي وُقّعت بعد ثلاثة أشهر من تنصيب هورتي وصيًّا على العرش في 1 آذار/مارس 1920، لحقت بالمجر خسارة جسيمة في الأرض والسكان: بقي خارج الحدود ثلثا أراضيها البالغة 283.000 كم2 دون كرواتيا، وستون في المئة من سكانها ومنهم أكثر من ثلاثة ملايين مجري، وخُفّض جيشها إلى 35.000 رجل. وتظهر المجر في عهد الوصاية في الخريطة بهذه الحدود المصغّرة؛ وتنتقل ترانسلفانيا والمجر العليا في هذا اليوم بالذات إلى لون رومانيا وتشيكوسلوفاكيا.", "6073745e"]},
"OLAYLAR_OK109:1920-06-04:1":{"b": ["تقسيم بانات وترك تيميشوارا لرومانيا (تريانون المادتان 27/3 و45)", "256b4aca"], "d": ["رسمت معاهدة تريانون الحدود المجرية-الرومانية بالمادة 27/3، وتنازلت المجر بالمادة 45 لمصلحة رومانيا عن كل حقوقها وألقابها في أراضي الملكية السابقة وراء هذه الحدود؛ فاعتُرف في القانون الدولي باتحاد ترانسلفانيا وبانات وكريشانا ومارامورش برومانيا. وقُسّمت منطقة بانات بين رومانيا وصربيا؛ وضُمت مدينة تيميشوارا إلى مملكة رومانيا. وكانت الإدارة الرومانية في تيميشوارا تعمل فعليًّا منذ 3 آب/أغسطس 1919؛ وأضفت المعاهدة على هذا الوضع صفة قانونية.", "5ec9c446"]},
"OLAYLAR_OK109:1921-04-04:0":{"b": ["الجيش الإيطالي ينسحب من كنين", "a1d2e846"], "d": ["بعد معاهدة رابالو انسحب الجيش الإيطالي من كنين في 4 نيسان/أبريل 1921؛ وانتهى الاحتلال الذي بدأ في 19 كانون الأول/ديسمبر 1918.", "0af4a592"]},
"OLAYLAR_OK109:1921-06-12:0":{"b": ["إيطاليا تسلّم شيبينيك إلى مملكة SHS", "9d07b12a"], "d": ["انتهى الاحتلال الإيطالي الذي بدأ في 6 تشرين الثاني/نوفمبر 1918 في 12 حزيران/يونيو 1921 بحفل شارك فيه ممثلون عسكريون عن إيطاليا ومملكة SHS.", "3d4d272c"]},
"OLAYLAR_OK109:1921-08-20:0":{"b": ["القوات الصربية تنسحب من سيغتفار — الدرك المجري يتسلّم المدينة", "97781b77"], "d": ["بعد دخول تريانون حيّز النفاذ بدأت القوات الصربية في 17 آب/أغسطس الانسحاب من بارتش وسيغتفار وحملت معها كل ما يمكن حمله. وفي 20 آب/أغسطس قرابة الظهر دخلت وحدات الدرك المجري؛ وبعد الظهر أدّى مجلس البلدية والموظفون اليمين، وفي الساعة الخامسة جرى التسليم العسكري في مبنى البلدية.", "1db599da"]},
"OLAYLAR_OK109:1921-08-22:0":{"b": ["انتهاء الاحتلال الصربي لبيتش (بيچوي Peçuy) — الجيش الوطني المجري يدخل المدينة", "f437115a"], "d": ["بدأت القوات الصربية في 18 آب/أغسطس 1921 إخلاء المنطقة؛ وفي 20-21 آب/أغسطس سُلّمت إدارة المدينة والولاية إلى ممثلي الحكومة المجرية، وفي 22 آب/أغسطس دخلت وحدات الجيش الوطني المجري المدينة.", "0210d518"]},
"OLAYLAR_OK109:1921-11-13:0":{"b": ["الجيش الاتحادي النمساوي (Bundesheer) يدخل بورغنلاند — تسلّم فعلي للأرض التي تركتها تريانون للنمسا", "7bfd6915"], "d": ["كانت تريانون (1920) وسان جرمان (1919) قد تركتا للنمسا الشريط الناطق بالألمانية من غرب المجر؛ وفشلت محاولة التسلّم الأولى في 28 آب/أغسطس 1921 بمقاومة الوحدات المجرية غير النظامية. وبعد بروتوكول البندقية (13 تشرين الأول/أكتوبر 1921) وافقت اللجنة العامة للحلفاء في 11 تشرين الثاني/نوفمبر على دخول الجيش الاتحادي، وبدأ تسلّم شمال بورغنلاند بعد يومين؛ وتسلّم الجنوب في 6 كانون الأول/ديسمبر 1921، وبقيت منطقة شوبرون في المجر باستفتاء شعبي.", "c78d0f81"]},
"OLAYLAR_ONCE1000_1019:0330-05-11:0":{"b": ["افتتاح القسطنطينية بمراسم؛ ينتقل مركز الإمبراطورية فعليًا إلى الشرق", "e4d78842"], "d": ["افتُتحت العاصمة الجديدة التي أسسها قسطنطين الأول بمراسم في 11 أيار 330؛ وصارت القسطنطينية عاصمة الإمبراطورية البيزنطية (الرومانية الشرقية).", "482503e4"]},
"OLAYLAR_ONCE1000_1019:0969-07-06:0":{"b": ["القائد جوهر الصقلي يدخل الفسطاط ويفتح مصر؛ وتنتهي الدولة الإخشيدية", "fd0410b1"], "d": ["دخل جوهر الصقلي الفسطاط باسم الخليفة الفاطمي المعز لدين الله (17 شعبان 358 / 6 تموز 969)؛ وانتقلت مصر من الإخشيديين إلى الفاطميين، ودخلت المنطقة التي ستُبنى فيها القاهرة تحت الحكم الفاطمي.", "4aee6045"]},
"OLAYLAR_ONCE1000_1019:0990-03-31:0":{"b": ["أبو الذواد يستولي على الموصل؛ وتقوم أسرة العقيليين", "c3032f55"], "d": ["استولى العقيلي أبو الذواد محمد بن المسيب على الموصل (380 / 990)؛ واختير 31 آذار 990 وهو أول يوم في تقاطع 380 هـ مع 990 م (جدول هجري-ميلادي، ±1-2 يوم)، واليوم غير موجود في المصدر.", "ecd80cfe"]},
"OLAYLAR_ONCE1281_GERIYE:1147-10-24:0":{"b": ["ألفونسو هنريكيس يستولي على لشبونة (الأشبونة)؛ وتصبح المدينة مركز مملكة البرتغال الجديدة", "24fddde8"], "d": ["أُخذت الأشبونة من المرابطين وانتقلت إلى البرتغال (27 جمادى الأولى 542 / 24 تشرين الأول 1147).", "bd3b3add"]},
"OLAYLAR_ONCE1281_GERIYE:1229-12-31:0":{"b": ["خايمي الأول يستولي على مدينة ميورقة (مدينة مايورقة)", "47fd675c"], "d": ["استولى ملك أراغون خايمي الأول على مدينة ميورقة من المسلمين؛ وانتقلت بالما إلى تاج أراغون.", "462f0592"]},
"OLAYLAR_ONCE1281_GERIYE:1238-05-12:0":{"b": ["محمد بن يوسف ابن الأحمر يؤسس الدولة النصرية في غرناطة", "23f66f33"], "d": ["قامت الدولة النصرية وعاصمتها غرناطة (26 رمضان 635 / 12 أيار 1238).", "04a01554"]},
"OLAYLAR_ONCE1281_GERIYE:1238-06-01:0":{"b": ["اتفاقية ستينسبي: النظام التوتوني يعيد شمال إستونيا (ريفال) إلى ملك الدنمارك فالديمار الثاني", "b64c584d"], "d": ["بالاتفاق الذي أُبرم في ستينسبي في سيلاند في حزيران 1238 عادت ريفال وشمال إستونيا إلى السيادة الدنماركية (اليوم غير موجود في المصدر).", "e8ad663d"]},
"OLAYLAR_ONCE1281_GERIYE:1238-09-28:0":{"b": ["معاهدة تسليم بلنسية: خايمي الأول يستولي على المدينة", "977120b3"], "d": ["انتقلت بلنسية (فالنسيا) في 28 أيلول 1238 بمعاهدة التسليم إلى ملك أراغون خايمي الأول (الدخول الاحتفالي في 9 تشرين الأول).", "c3465b4f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1054-11-05:0":{"b": ["العُقيلي قريش يقيم الخطبة باسم طغرل بك", "9fb65fc0"], "d": ["عندما قدم طغرل بك إلى المنطقة بمناسبة حملة بغداد، أقام الأمير العُقيلي قريش الخطبة باسم طغرل بك في شعبان 446 / تشرين الثاني/نوفمبر 1054؛ وبعد مقتل المرواني سليمان أُصيب بجراح بالغة عام 447/1055.", "43df7313"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1064-01-01:0":{"b": ["السلطان ألب أرسلان يفتح آني ويسلّم إدارة المدينة إلى الشدّادي أبي شجاع مَنوچهر", "f2c51a49"], "d": ["فتح ألب أرسلان آني عام 456/1064 وسلّم إدارة المدينة إلى أبي شجاع مَنوچهر بن أبي الأسوار شاور من الشدّاديين. وضم مَنوچهر قارص أيضًا إلى أراضيه، وخشيةً من الجيش البيزنطي المقترب رمّم الأسوار التي خُرّبت أثناء الفتح؛ وحكم آني أربعة وخمسين عامًا تابعًا للسلاجقة.", "6ddc5837"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1068-01-01:0":{"b": ["ألب أرسلان يستولي على أخالتسيخه", "31b9964f"], "d": ["أخالتسيخه، التي استولى عليها ألب أرسلان في عهد السلاجقة (1068)، دخلت في عامي 1267-1268 تحت سيطرة المغول.", "f2d87d84"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1068-01-01:1":{"b": ["ألب أرسلان وحلفاؤه يدمرون تفليس وكارتلي", "ff50ab5d"], "d": ["كان الملك باغرات قد استرد معظم قلاعه؛ غير أن ألب أرسلان وحلفاءه دمروا تفليس وكارتلي عام 1068.", "753e1b62"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1073-01-01:0":{"b": ["فيلاريتوس يجمع رهبانًا أرمن في مدينة هونو (ناحية البستان) فيُنتخب كاثوليكوس ويجعل المدينة مركز الكاثوليكوسية", "66005693"], "d": ["اغتنم فيلاريتوس أسر رومانوس ديوجينيس في معركة ملاذكرد عام 1071، فجمع رهبانًا أرمن في مدينة هونو وجعلهم ينتخبون كاثوليكوسًا. وبذلك أُقيم المركز الديني لإدارة أرمنية منفصلة عن بيزنطة في منطقة مرعش - البستان - ملطية.", "146d6889"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1076-01-01:0":{"b": ["السلطان ملكشاه يصل إلى كارتلي في حملته على جورجيا ويكلّف سرهنك ساوتكين بمسؤولية المنطقة", "830b979a"], "d": ["قام ملكشاه بحملة على جورجيا مع القائد الجورجي يوانه بن ليباريت الذي بقي تابعًا له، فبلغ كارتلي، وعاد بأسرى وغنائم كثيرة، وكلّف سرهنك ساوتكين بمسؤولية المنطقة (1076). وانتصر الملك جيورجي الثاني في حروبه مع ساوتكين واسترد بعض الأماكن.", "8a5912c3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1078-07-14:0":{"b": ["ملكشاه يدخل جورجيا عبر نهر أراس وينهب منطقة سومخيتي ويأسر يوانه", "e62fd603"], "d": ["لما هزم الملك جيورجي الثاني ساوتكين واسترد بعض الأماكن، خرج السلطان ملكشاه في حملة جديدة ودخل جورجيا عبر نهر أراس (471/1078-79)؛ ونهب منطقة سومخيتي وأسر يوانه، وتركَ ساوتكين هناك مع قوات معززة وعاد. وألحق الأمير أحمد بالملك هزيمة ثقيلة في كويل واستعاد قارص.", "57f4ff76"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1083-01-01:0":{"b": ["سليمان شاه الأول يغزو جوكوروفا ويفتح طرسوس وأضنة وعين زربة والمصيصة", "c443ee8b"], "d": ["اتخذ سليمان شاه لقب السلطان عام 1082، وفي السنة نفسها قام بحملة على جوكوروفا ففتح مدن طرسوس وأضنة وعين زربة والمصيصة وقلاعها (1082-1083)؛ ثم سار إلى أنطاكية بدعوة من أهلها مع ولديه قلج أرسلان وداود.", "e617bea2"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1085-01-01:0":{"b": ["جوبوك بك يفتح خربوت ويؤسس إمارة الجوبوك أوغلو التي ضمت منطقتي بالو وجميشكزك", "1f333d7d"], "d": ["في أثناء الغارات التركية على الأناضول بعد عام 1071، فتح جوبوك بك خربوت وأسس الإمارة التي شملت منطقتي بالو وجميشكزك. وكان عمر الإمارة قصيرًا؛ إذ استولى الأرتقي بلك على المدينة في عقد 1110.", "5c951bf7"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1085-04-29:0":{"b": ["السلطان ملكشاه يمنح بتليس وما حولها إقطاعًا لدلماج أوغلو محمد بك؛ بداية إمارة الدلماج أوغلو", "7cdcb46f"], "d": ["بعد أن استولى القائد العام للجيش السلجوقي فخر الدولة ابن جهير على بتليس وما حولها، منحها السلطان ملكشاه إقطاعًا لدلماج أوغلو محمد بك الذي شارك في ملاذكرد (478/1085). وحكمت الإمارة بتليس وأرزن بين عامي 1085 و1394.", "da296fec"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1085-06-20:0":{"b": ["مسلم بن قريش يُهزم ويُقتل أمام سليمان شاه في قرزاحل", "fc482adb"], "d": ["حارب سليمان شاه العُقيلي مسلم بن قريش، الذي أراد تأسيس دولة عربية موحدة مستقلة عن السلطان السلجوقي الأكبر، حين أباح ما حول أنطاكية للنهب؛ فهُزم وقُتل في موضع قرزاحل (24 صفر 478 / 20 حزيران/يونيو 1085) ودُفن عند باب حلب.", "9f4da840"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1086-01-01:0":{"b": ["السلطان ملكشاه يأتي إلى القفقاس بجيش كبير ويُخضع المنطقة كليًّا", "79dd07e4"], "d": ["بعد ذهاب الملك جيورجي الثاني إلى أصفهان وقبوله سيادة ملكشاه، جاء ملكشاه إلى القفقاس مرة أخرى، وهي الأخيرة، عام 1086 بجيش كبير وأخضع المنطقة كليًّا؛ وكانت جورجيا الشرقية قد سُميت «ديدي توركوبا» (التركمان الكبرى).", "a15ba581"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1095-01-01:0":{"b": ["قتل جاكا بك على يد صهره قلج أرسلان الأول في مأدبة", "20cdcec9"], "d": ["تذكر آنا كومنينا أن جاكا بك قُتل في مأدبة على يد صهره قلج أرسلان، وتورّخ وفاته بعام 1097، غير أن هذا خطأ بالنظر إلى حصار ملطية عام 1096 وسقوط إزنيق عام 1097؛ ويجب أن يكون تاريخ الوفاة 1095 (ت. 488/1095 [؟]).", "9a287bc8"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1097-01-01:0":{"b": ["قلج أرسلان الأول يحاصر ملطية التي أراد الدانشمنديون أيضًا الاستيلاء عليها؛ ويرفع الحصار حين توجه الصليبيون نحو إزنيق", "4f036db3"], "d": ["سار قلج أرسلان في شتاء 490/1097 على ملطية التي طمع فيها الدانشمنديون أيضًا، وحاصرها فترة؛ ولما علم بخروج الجيوش الصليبية اتجه إلى إزنيق وفُقدت إزنيق (حزيران/يونيو 1097).", "4282aef8"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1100-07-01:0":{"b": ["كمشتكين غازي يوقع بوهيموند أمير أنطاكية في كمين ويأسره ويسجنه في نكسار", "c43f8a71"], "d": ["نصب الدانشمندي كمشتكين، الذي كان يحاصر ملطية، كمينًا لقوات بوهيموند أمير أنطاكية التي جاءت للنجدة وهزمها؛ وسيق بوهيموند أولًا إلى سيواس ثم إلى نكسار وسُجن. ورُفع الحصار عند اقتراب بلدوين كونت الرها.", "543833c3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1101-06-23:0":{"b": ["أنقرة تُترك لبيزنطة بموجب الاتفاق بين الصليبيين والإمبراطور ألكسيوس كومنينوس", "d64f8668"], "d": ["كان ريموند الطولوزي قد احتل أنقرة في الحملة الصليبية الأولى دون مقاومة جدية، وأُعمل السيف في الأتراك الذين في القلعة؛ وبموجب الاتفاق بين الصليبيين وألكسيوس كومنينوس تُركت المدينة للإمبراطورية البيزنطية في 23 حزيران/يونيو 1101. واستمرت الإدارة البيزنطية نحو عشرين عامًا.", "f8a37732"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1101-08-01:0":{"b": ["كمشتكين وقلج أرسلان الأول ورضوان يهزمون جيش اللومبارد الصليبي قرب مرزيفون", "f2703ea8"], "d": ["هُزم الصليبيون اللومبارديون، الذين استولوا على أنقرة لتخليص بوهيموند من الأسر وتقدموا نحو جانقري، قرب مرزيفون في آب/أغسطس 1101 أمام الجيش التركي المشترك البالغ 20.000 رجل بقيادة كمشتكين وقلج أرسلان الأول ورضوان صاحب حلب وقرجا أمير حران.", "ddaa77e1"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1102-01-01:0":{"b": ["سقمان يتسلم حصن كيفا؛ تأسيس فرع الأرتقيين في حصن كيفا", "07e6f974"], "d": ["عند وفاة أمير الموصل كربوغا، ساعد سقمان، الذي دعم موسى في الموصل، موسى على هزيمة جكرمش مقابل وعده؛ ولما قُتل موسى ذهب إلى حصن كيفا وتسلم المدينة. وبذلك تأسس فرع الأرتقيين في حصن كيفا (1102-1232).", "fccc615e"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1103-01-01:0":{"b": ["سقمان يستولي على ماردين بعد وفاة ابن أخيه ياقوتي", "a5099d54"], "d": ["كانت ماردين تحت سيطرة ياقوتي ابن أخي سقمان؛ ولما توفي استغل سقمان الخلاف الذي نشأ بعد وفاته فاستولى على المدينة عام 1103، وضم إليه معظم نواحي ديار بكر.", "43484644"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1103-08-01:0":{"b": ["قلج أرسلان الأول يهزم كمشتكين غازي قرب مرعش", "15ec5217"], "d": ["أدى إطلاق كمشتكين بوهيموند مقابل فدية، وسخط قلج أرسلان الذي طلب حصة من الفدية، إلى وقوع الخلاف بين الحليفين؛ فهزم قلج أرسلان كمشتكين هزيمة ساحقة قرب مرعش.", "64f2df55"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1104-01-01:0":{"b": ["وفاة كمشتكين غازي في سيواس؛ ابنه الأمير غازي يتولى رأس الأسرة الدانشمندية", "75915f65"], "d": ["أصيب الدانشمنديون بهزة كبيرة بوفاة كمشتكين؛ وسُلمت ملطية إلى السلاجقة، ونشبت صراعات على العرش بين أفراد الأسرة. وتولى ابنه الأكبر الأمير غازي الحكم.", "f184fc73"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1104-05-07:0":{"b": ["سقمان القطبي وجكرمش يهزمان بلدوين دي بورغ كونت الرها وجوسلين ويأسرانهما قرب حران (البليخ)", "5240d89c"], "d": ["هُزم بلدوين دي بورغ كونت الرها الصليبي وجوسلين كونت تل باشر أمام المسلمين في معركة حران في 9 شعبان 497 / 7 أيار/مايو 1104 ووقعا في الأسر. وفي تشرين الأول/أكتوبر من السنة نفسها مرض سقمان، بطل النصر، وتوفي.", "3b141414"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1104-10-01:0":{"b": ["وفاة سقمان؛ ابنه إبراهيم يخلفه", "c40e3436"], "d": ["مرض سقمان بعد نصر حران بوقت قصير وتوفي في تشرين الأول/أكتوبر 1104؛ وتولى ابنه إبراهيم فرع حصن كيفا، وبوفاة إبراهيم عام 1108 أصبح أخوه داود حاكم الأرتقيين.", "3fb73425"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1110-01-01:0":{"b": ["محمد تاپار يهزم القوات الجورجية ويخرّب بعض المدن", "372cbcc6"], "d": ["حين بدأ الملك داود الثاني حملة غزو جديدة بجيش كبير جمعه من القفجاق وبلغ كنجة، سار السلطان السلجوقي محمد تاپار على جورجيا، فهزم القوات الجورجية وخرّب بعض المدن (503/1110).", "f381ea2e"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1110-01-01:1":{"b": ["ملكشاه (شاهنشاه) الذي أرسله السلطان السلجوقي الأكبر محمد تاپار يجلس على عرش سلاجقة الأناضول في قونية", "b8987991"], "d": ["بعد وفاة قلج أرسلان الأول، وإثر هجمات ألكسيوس كومنينوس، أرسل محمد تاپار إلى الأناضول ملكشاه الابن الأكبر لقلج أرسلان؛ فجاء ملكشاه إلى قونية وجلس على العرش، وقاتل ألكسيوس ست سنوات.", "a8488c23"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1111-09-01:0":{"b": ["وفاة سقمان القطبي في بالس على ضفة الفرات؛ ابنه ظهير الدين إبراهيم يخلفه", "510ea223"], "d": ["انضم سقمان إلى جيش مودود بن ألتونتكين الذي أرسله محمد تاپار على الصليبيين، ثم غادر الجيش لاشتداد مرضه، وتوفي في بالس في أيلول/سبتمبر 1111. وتولى ابنه إبراهيم رأس أسرة شاه أرمن، وبقي حتى 1126/1127.", "1ca34ea9"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1112-01-01:0":{"b": ["بلك الأرتقي يتخذ بالو مركزًا ويستولي على أراضي الجوبوك أوغلو", "624ab91f"], "d": ["بتولي بلك بن بهرام السيطرة على خربوت عام 1112، انتقلت بالو من الجوبوك أوغلو إلى فرع خربوت من الأرتقيين؛ وجعلها بلك عاصمة.", "2d7c33df"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1118-01-01:0":{"b": ["داود الرابع يبدأ إسكان 45.000 أسرة قفجاقية في جورجيا", "559894b0"], "d": ["اتفق داود مع 45.000 أسرة قفجاقية من شمال القفقاس وسهوب جنوب روسيا وجاء بها إلى جورجيا ابتداءً من عام 1118، وأنهى بمساعدتها الهيمنة السلجوقية على تفليس عام 1121.", "d4bc7246"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1119-01-01:0":{"b": ["الأمير غازي يهزم روجر أمير أنطاكية ويغير على أنطاكية", "7bd138a2"], "d": ["أغار الأمير غازي على أنطاكية في أيار/مايو 1119 بجيش من 7000 رجل، وهزم روجر أمير أنطاكية الذي سار عليه.", "c575e81b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1121-08-12:0":{"b": ["الملك الجورجي داود يهزم الجيش المسلم في ديدغوري؛ الطريق إلى تفليس وآني يُفتح", "03b19a6d"], "d": ["هُزم تغرل أمير كنجة الذي أرسله السلطان السلجوقي العراقي محمود، والأتابك كندوغدي، ودبيس بن صدقة، والأرتقي إيلغازي، ودلماج أوغلو طغان أرسلان أمام الجيش الكبير الذي جمعه الملك الجورجي داود (داود الثاني في TDV؛ وفي المصادر الجورجية داود الرابع «البنّاء») من القفجاق، قرب ديدغوري في 12 آب/أغسطس 1121. ثم احتل الجورجيون تفليس، التي كانت تحت الحكم الإسلامي منذ قرون، وجعلوها عاصمة.", "d186cc45"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1122-11-19:0":{"b": ["وفاة نجم الدين إيلغازي؛ ابناه سليمان في ميافارقين وتيمورتاش في ماردين يحكمان", "5e1a6c08"], "d": ["مرض إيلغازي، حاكم ماردين الأرتقي الذي خاض صراعًا كبيرًا ضد الصليبيين من حلب، في حملة قلعة زردنا مع ابن أخيه بلك وأتابك دمشق طغتكين، وتوفي في 19 تشرين الثاني/نوفمبر 1122. وحكم من أبنائه سليمان في ميافارقين وتيمورتاش في ماردين، وحكم ابن أخيه سليمان في حلب.", "6f429e0c"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1124-01-01:0":{"b": ["البستان تدخل الإدارة الدانشمندية باستيلاء الأمير غازي على منطقة ملطية", "5be35d74"], "d": ["البستان، التي دمرها زلزال كبير عام 1114، دخلت تحت إدارة الدانشمنديين عام 1124 باستيلاء الدانشمندي الأمير غازي على منطقة ملطية.", "a81725b1"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1129-01-01:0":{"b": ["الدانشمنديون يسيطرون على منطقة قسطموني", "e1be4a42"], "d": ["دخلت أنقرة وجانقري وقسطموني وسواحل البحر الأسود عام 1129 تحت سيطرة الأمير غازي؛ وانضمت منطقة قسطموني إلى حدود الدانشمنديين.", "df047345"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1129-01-01:1":{"b": ["الدانشمنديون يسيطرون على جانقري وقسطموني وسواحل البحر الأسود", "db4c771a"], "d": ["سيطر الدانشمنديون، وكانوا أقوى دولة في الأناضول في عهد الأمير غازي، عام 1129 على أنقرة وجانقري وقسطموني وسواحل البحر الأسود؛ ودخل معظم الأراضي الممتدة من ملطية إلى سقاريا تحت الإدارة الدانشمندية.", "1d1edb93"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1130-01-01:0":{"b": ["الشدّادي فضل الرابع يُقتل في الحرب التي خاضها أمير أرزن كورتي لاسترداد دفين", "d8a7ad18"], "d": ["استرد فضل الرابع آني بعد حصارها، وضم كنجة ودفين إلى أراضيه، وقُتل عام 524/1130 في الحرب التي خاضها أمير أرزن كورتي لاسترداد دفين؛ وخلفه أخوه، لكن ابنه محمودًا جاء إلى آني واستولى على الحكم.", "7810bf30"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1131-01-01:0":{"b": ["السلطوقي ضياء الدين غازي يهزم الملك الجورجي إيفاني", "5ba067d6"], "d": ["شارك ضياء الدين غازي في الحملة التي نُظمت على الجورجيين حين تجاوزوا إسبير وبسين عام 1126 وبلغوا أولتو، وهزم الملك إيفاني عام 1131.", "d91b0282"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1132-01-01:0":{"b": ["بوفاة ضياء الدين غازي يتولى ابن أخيه عز الدين سلطوق الثاني رأس إمارة السلطوقيين", "726791ef"], "d": ["توفي ضياء الدين غازي، قريب الأرتقي تيمورتاش، عام 526/1132؛ وتولى ابن أخيه عز الدين سلطوق الثاني رأس الإمارة.", "a7412435"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1134-01-01:0":{"b": ["وفاة الأمير غازي؛ ابنه الأكبر الملك محمد يُعلن حاكمًا في ملطية", "1cf04ea6"], "d": ["توفي الأمير غازي (الملك غازي)، أنفذ حكام الأناضول نفوذًا، عام 528/1134. وأُعطي الملك محمد المنشور والصولجان الذهبي والهدايا التي أرسلها الخليفة العباسي المسترشد بالله والسلطان سنجر، وأُعلن حاكمًا في ملطية. وثار إخوته عين الدولة ويغان.", "e39192f6"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1142-01-01:0":{"b": ["السلطان مسعود يستولي على سيواس؛ ينتزع أنقرة وجانقري وقسطموني من الدانشمنديين ويعطيها لابنه شاهنشاه", "cc439683"], "d": ["لما انقسم الدانشمنديون إلى ثلاثة فروع بوفاة الملك محمد، سار سلطان سلاجقة الأناضول مسعود الأول على سيواس واستولى عليها، وعيّن ابنه الأصغر شاهنشاه واليًا على أنقرة وجانقري وقسطموني.", "6b775908"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1142-01-01:1":{"b": ["السلطان مسعود ينتزع قسطموني من الدانشمنديين ويتركها لابنه شاهنشاه", "ae895779"], "d": ["أعطى السلطان مسعود، الذي استولى على سيواس، قسطموني مع أنقرة وجانقري إلى ولاية ابنه الأصغر شاهنشاه.", "f8cfb811"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1142-01-01:2":{"b": ["السلطان مسعود ينتزع جانقري من الدانشمنديين ويتركها لابنه شاهنشاه", "8047e8a8"], "d": ["استغل مسعود الأول الصراعات الدانشمندية على العرش فاستولى على أنقرة وجانقري وقسطموني، وترك إدارة هذه المدن الثلاث لابنه شاهنشاه.", "07d66793"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1143-06-17:0":{"b": ["السلطان مسعود يبدأ حصار ملطية الذي دام ثلاثة أشهر؛ ولما لم يظفر بنتيجة رفعه في 14 أيلول/سبتمبر 1143", "4c2d2d2b"], "d": ["حاصر السلطان مسعود، الذي استولى على سيواس من الأسرة التي انقسمت إلى ثلاثة بوفاة الدانشمندي الملك محمد (537/1142)، ملطية في 1 ذي الحجة 537 / 17 حزيران/يونيو 1143؛ ولما لم يظفر بنتيجة طوال ثلاثة أشهر رفع الحصار في 2 ربيع الأول 538 / 14 أيلول/سبتمبر 1143 وعاد إلى قونية.", "2dc53da5"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1143-12-06:0":{"b": ["وفاة الملك محمد في قيصرية؛ انقسام الدانشمنديين إلى فروع سيواس وملطية وقيصرية", "1ee92ff3"], "d": ["بعد وفاة الملك محمد في قيصرية في 6 كانون الأول/ديسمبر 1143 بحسب ميخائيل السرياني، أقام أخوه ياغي باسان سلطانه في سيواس، وابنه ذو النون في قيصرية، وعين الدولة في ملطية والبستان؛ وانقسم الدانشمنديون إلى ثلاثة فروع ودخلوا في صراع مدمر فيما بينهم.", "b07a9299"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1144-08-01:0":{"b": ["وفاة داود الأرتقي حاكم حصن كيفا؛ ابنه فخر الدين قرا أرسلان يخلفه", "4782f166"], "d": ["توفي داود، الذي تحالف مع الأرتقي تيمورتاش صاحب ماردين ضد أتابك الموصل زنكي، في 1 آب/أغسطس 1144؛ واتفق ابنه فخر الدين قرا أرسلان مع سلطان سلاجقة الأناضول مسعود الأول ضد زنكي.", "48a2c46f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1153-03-29:0":{"b": ["بمؤامرة دبرها أمير آني فخر الدين شدّاد يُهزم الجيش السلطوقي أمام الملك الجورجي ديميتري؛ عز الدين سلطوق يقع في الأسر", "f936d922"], "d": ["عرض شدّاد أمير آني، الذي خطب ابنة سلطوق فرُفض، أن يبيع المدينة لسلطوق ويدخل في خدمته؛ فلما جاء سلطوق بجيشه أخبر الملك الجورجي. وألحق الملك ديميتري بالجيش السلطوقي هزيمة ثقيلة، ووقع سلطوق في الأسر ونجا بفدية قدرها 100.000 دينار.", "0d47e21f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1155-01-01:0":{"b": ["بعد وفاة السلطان مسعود يُمنح صهره الدانشمندي ياغي باسان أماسيا وأنقرة وكبادوكيا", "295fac37"], "d": ["حين اعتلى قلج أرسلان الثاني العرش بعد وفاة مسعود (1155)، مُنح ياغي باسان، أحد صهري مسعود من الأسرة الدانشمندية، أماسيا وأنقرة وكبادوكيا، ومُنح ذو النون مدينتي قيصرية وسيواس؛ وثار إخوته مدّعين الحق في العرش.", "b6540bd8"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1155-03-07:0":{"b": ["فخر الدين شدّاد يقع في أسر الجورجيين؛ ثورة الراهبات الأرمنيات في آني تقيم أخاه فضل الخامس مكانه", "2e64eb02"], "d": ["بعد هزيمة الملك الجورجي ديميتري الجيش السلطوقي، ثارت الراهبات الأرمنيات احتجاجًا على تصرف فخر الدين شدّاد، فأقمن في آني أخاه فضل الخامس بدلًا من سلطوق (550/1155)؛ وانتهت إمارة فضل الخامس بتسليم آني إلى الملك الجورجي عام 1161.", "56cd50fc"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1161-01-01:0":{"b": ["الملك الجورجي جيورجي يستولي على آني", "8081e228"], "d": ["استولى الملك الجورجي جيورجي على مدينة آني عام 1161، بعد أن ألحق عام 1154 هزيمة ثقيلة بحاكم السلطوقيين عز الدين سلطوق؛ وانتهت الإمارة الشدّادية بثورة رجال الدين وتسليمهم المدينة إلى الملك الجورجي.", "357c7a97"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1161-08-01:0":{"b": ["شاه أرمن سقمان وعز الدين سلطوق ودولتشاه يحاصرون آني؛ بترك سلطوق المعسكر يُهزم المسلمون", "d651d8fe"], "d": ["بعد استيلاء الملك الجورجي جيورجي على آني، اتحد شاه أخلاط سقمان الثاني وعز الدين سلطوق الثاني وفخر الدولة دولتشاه أمير أرزن وبتليس وغيرهم من الأمراء الأتراك وحاصروا المدينة. ولما جاء الملك جيورجي ترك سلطوق المعسكر دون أن يُعلم الأمراء الآخرين؛ فهُزم المسلمون وقُتل منهم كثيرون ووقع 9000 في الأسر.", "2345b0e8"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1162-01-01:0":{"b": ["الجورجيون يغزون دفين", "e8f2a041"], "d": ["غزا الجورجيون الذين استولوا على آني عام 1161 قارص ودفين في العام التالي؛ ثم هزمت حملة الأمراء المسلمين المشتركة جورجيا عام 1163.", "b28be1b3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1162-01-01:1":{"b": ["الجورجيون يغزون قارص ودفين", "a7388ca5"], "d": ["غزا الجورجيون قارص ودفين في العام التالي لاستيلائهم على آني عام 1161؛ وبعد أن قتلوا عددًا كبيرًا من المسلمين وأحرقوا المساجد والبيوت عادوا إلى تفليس.", "2a892f7b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1163-01-01:0":{"b": ["الجيش المشترك للأمراء المسلمين يهزم الملك الجورجي جيورجي؛ جيورجي يُجبر على رد آني", "346b30b1"], "d": ["ألحق الجيش الكبير الذي تشكل بمبادرة السلطان طغرل والأتابك شمس الدين إيلديكز هزيمة ثقيلة بملك جورجيا جيورجي عام 558/1163، فاضطر جيورجي إلى رد آني.", "a59e4ef4"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1163-07-01:0":{"b": ["الجيش المتحالف للأمراء الأتراك يهزم الجيش الجورجي قرب قلعة لوكري", "58d3a0d5"], "d": ["غزا جورجيا أكثر من 50.000 مجاهد شارك فيهم إيلديكز وسقمان وعز الدين سلطوق وابن آق سنقر وأرسلان شاه؛ وهُزم الجورجيون قرب قلعة لوكري في تموز/يوليو 1163، وفرّ الملك جيورجي تاركًا أثقاله، واضطر إلى رد آني.", "7ac70a0b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1164-08-04:0":{"b": ["وفاة ياغي باسان ملك سيواس في جانقري؛ بداية صراع جديد بين الدانشمنديين", "59448eb7"], "d": ["توفي ياغي باسان، الذي ذهب إلى جانقري لطلب العون من الملك السلجوقي شاهنشاه ضد قلج أرسلان الثاني، في جانقري في 4 آب/أغسطس 1164؛ ودُفن في حظيرة المدرسة التي بناها في نكسار. والخلاف قائم فيمن خلفه بعد وفاته.", "0efd18be"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1165-01-01:0":{"b": ["قلج أرسلان الثاني ينتزع منطقتي دارنده وكدوك (شارقشلا) من الدانشمنديين", "917ee1e6"], "d": ["استغل قلج أرسلان الثاني الصراع داخل الأسرة بعد وفاة ياغي باسان، فضم عام 1165 منطقة البستان ودارنده وكدوك.", "7f39a47e"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1168-01-01:0":{"b": ["وفاة عز الدين سلطوق الثاني؛ ابنه ناصر الدين محمد يعتلي العرش", "40c0ab87"], "d": ["بعد وفاة عز الدين سلطوق عام 563/1168، اعتلى ابنه ناصر الدين محمد عرش السلطوقيين؛ وبُني جامع أرضروم الكبير باسمه عام 1179.", "18b4b682"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1170-09-14:0":{"b": ["قلج أرسلان الثاني يعيد بناء أكسراي ويجعلها قاعدة عسكرية باسم دار الظفر", "e0f2e591"], "d": ["أعاد قلج أرسلان الثاني بناء مدينة أكسراي عام 566 (1170-71) وسماها دار الظفر، وجعلها قاعدة عسكرية؛ وبنى فيها مساجد وزوايا ومدارس وخانًا، وأسكن فيها الغزاة والعلماء الذين جاء بهم من أذربيجان.", "0ddd80f6"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1172-01-01:0":{"b": ["أهل سيواس يثورون ويقتلون إسماعيل؛ ذو النون يعتلي العرش الدانشمندي في سيواس بدعم نور الدين زنكي", "ab96caf2"], "d": ["ثار الأهالي في سيواس بسبب القحط وضد إسماعيل الذي لم يوزع مخزون المستودعات؛ وقُتل إسماعيل وزوجته. ودعا أعيان المدينة ذا النون الذي كان قد لجأ إلى نور الدين؛ فاعتلى ذو النون العرش الدانشمندي في سيواس عام 567/1172 بمساعدة نور الدين، لكنه فرّ بعد قليل إلى نكسار بضغط من قلج أرسلان الثاني.", "374133e0"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1175-01-01:0":{"b": ["قلج أرسلان الثاني ينتزع نكسار من الدانشمنديين ويضمها إلى الحكم السلجوقي", "e49e3971"], "d": ["استولى قلج أرسلان الثاني في صيف 1175 على سيواس ونكسار وكومانا وطوقات وسائر الأراضي الدانشمندية؛ وانتقلت إلى أيدي السلاجقة نكسار، وهي أحد المراكز الدانشمندية التي دُفن فيها ياغي باسان في حظيرة مدرسته.", "aa58d509"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1175-01-01:1":{"b": ["قلج أرسلان الثاني ينتزع طوقات من الإمارة الدانشمندية الزائلة ويضمها إلى الحكم السلجوقي", "1894c403"], "d": ["بعد وفاة الأتابك نور الدين محمود زنكي عام 569/1174، تجاهل قلج أرسلان الثاني شروط المعاهدة، واستولى في صيف 1175 على سيواس ونكسار وكومانا وطوقات وسائر الأراضي الدانشمندية؛ ولجأ ذو النون وشاهنشاه إلى بيزنطة، وزال فرع سيواس من الدانشمنديين.", "dbfcc454"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1180-05-28:0":{"b": ["قلج أرسلان الثاني ينتزع أولوبورلو وكوتاهية ومنطقة دوريلايون (إسكي شهير) من بيزنطة", "807be33d"], "d": ["لما لم يلتزم الإمبراطور مانويل بشروط المعاهدة ولم يهدم قلعة دوريلايون، خرّب قلج أرسلان الثاني وادي المندريس عام 573/1177؛ وانتقلت أولوبورلو وكوتاهية ودوريلايون إلى الحكم السلجوقي عام 576/1180.", "60e80418"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1184-01-01:0":{"b": ["الملك الجورجي داود يسير على أرضروم؛ يعود بمقاومة الأهالي", "07419985"], "d": ["سار الملك الجورجي داود على أرضروم فهزم ناصر الدين محمد وأجبره على الانسحاب إلى المدينة؛ ثم نهب ما حولها وانسحب أمام شجاعة الأهالي الأتراك وعزمهم (580/1184-85).", "85711193"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1184-04-14:0":{"b": ["قلج أرسلان الثاني يقسم بلاده بين أبنائه الأحد عشر", "b1ee119d"], "d": ["قسّم قلج أرسلان الثاني البلاد بين أبنائه في شيخوخته؛ وكانت طوقات من نصيب ابنه الأكبر ركن الدين سليمان شاه. وانقسمت البلاد السلجوقية إلى أحد عشر جزءًا.", "09e83cd3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1185-01-01:0":{"b": ["الوالي إسحاق دوكاس كومنينوس يثور على الإمبراطور أندرونيكوس ويعلن استقلال قبرص", "445f5db0"], "d": ["بينما كانت قبرص ولاية بيزنطية، ثار الوالي إسحاق دوكاس كومنينوس على الإمبراطور أندرونيكوس كومنينوس وأعلن استقلالها، وخرجت قبرص من الحكم البيزنطي عام 1185.", "00f3ca97"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1185-07-10:0":{"b": ["وفاة شاه أرمن سقمان الثاني، شاه أخلاط، أثناء حصار الموصل", "f492f6ba"], "d": ["حين حاصر صلاح الدين الموصل ثانية عام 1185، بلغه نبأ وفاة حليفه سقمان (9 ربيع الآخر 581 / 10 تموز/يوليو 1185). ولم يعد صلاح الدين من حملة أخلاط خالي الوفاض، فاستولى على ميافارقين التي بقيت بلا حاكم.", "2692f19a"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1190-05-17:0":{"b": ["الجيش الصليبي بقيادة فريدريك بربروسا يهزم الجيش السلجوقي ويدخل قونية", "f1f901b6"], "d": ["عبر الإمبراطور الألماني بربروسا إلى الأناضول من غاليبولي في آذار/مارس 1190، ودخل الأراضي السلجوقية قرب أولوبورلو، وهزم في 17 أيار/مايو 1190 جيش قطب الدين ملكشاه وسائر الملوك السلاجقة، ودخل العاصمة قونية التي أخلاها السلطان.", "0d30744a"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1192-08-26:0":{"b": ["وفاة قلج أرسلان الثاني أثناء حصار أكسراي؛ كيخسرو الأول يخلفه", "083f9fae"], "d": ["مرض قلج أرسلان الثاني، الذي كان يحاصر أكسراي مع غياث الدين كيخسرو أثناء صراعه مع أبنائه، وتوفي في 15 شعبان 588 / 26 آب/أغسطس 1192؛ واعتلى كيخسرو العرش في قونية.", "1f04ea47"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1193-05-18:0":{"b": ["مقتل شاه أخلاط بكتمر على يد صهره هزار ديناري", "12078a3c"], "d": ["بعد نحو شهرين ونصف من وفاة صلاح الدين، قُتل سيف الدين بكتمر في 18 أيار/مايو 1193 على يد صهره، أحد قادته، بدر الدين آق سنقر هزار ديناري. وسجن هزار ديناري ابن بكتمر البالغ سبع سنين وزوجته في قلعة بمنطقة أرزاس.", "e0117ffd"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1196-11-24:0":{"b": ["غياث الدين كيخسرو يترك العرش لأخيه ركن الدين سليمان شاه ويبدأ حياة الغربة", "557c281e"], "d": ["اضطر كيخسرو الأول، الذي صارع إخوته، إلى ترك العرش لسليمان شاه الثاني (ركن الدين) (593/1196) وغادر قونية؛ واستولى سليمان شاه على أراضي إخوته وأعاد وحدة البلاد.", "129847ea"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1197-01-01:0":{"b": ["أموري دي لوزينيان يتخذ لقب ملك قبرص؛ ويعترف به الصليبيون في عكا في السنة نفسها ملكًا على القدس", "c38ed247"], "d": ["اتخذ أموري لقب الملك عام 1197، واعترف به الصليبيون في عكا في السنة نفسها ملكًا على القدس؛ وصارت مملكة قبرص قاعدة بحرية للشرق الصليبي.", "1d28312c"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1199-01-06:0":{"b": ["ليفون يرتدي في كاتدرائية طرسوس التاج الذي أرسله الإمبراطور الروماني المقدس هاينريش السادس ويصبح أول ملك لمملكة أرمينيا القيليقية", "99ceea3a"], "d": ["ارتدى ليفون أمير الروبينيين في كاتدرائية طرسوس التاج الذي أرسله الإمبراطور الروماني المقدس هاينريش السادس، وباركه مندوب البابا؛ وتحولت إمارة الروبينيين إلى مملكة أرمينيا القيليقية.", "05fe804d"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1201-06-23:0":{"b": ["سليمان شاه الثاني يستولي على ملطية من أخيه معز الدين قيصر شاه", "fff1df20"], "d": ["تحرك سليمان شاه على أخيه ملك ملطية معز الدين قيصر شاه الذي أبى الخضوع له، واستولى على المدينة في 19 رمضان 597 / 23 حزيران/يونيو 1201.", "65e22bbb"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1202-01-01:0":{"b": ["حملة سليمان شاه الثاني على جورجيا: السلاجقة يتكبدون خسائر ثقيلة في غارة جورجية على المعسكر؛ أمير أرزنجان المنكوجكي بهرام شاه يقع في الأسر", "3ee9e922"], "d": ["خرج سليمان شاه الثاني عام 1202 في حملة على الجورجيين الذين هاجموا الأراضي التركية، فتعرض وهو يستريح في المعسكر لغارة جورجية وتكبد خسائر ثقيلة؛ وكان بين الأسرى أمير أرزنجان المنكوجكي بهرام شاه.", "4151b3d2"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1202-06-25:0":{"b": ["سليمان شاه الثاني ينهي أسرة السلطوقيين ويقطع أرضروم لأخيه طغرل شاه", "37a63791"], "d": ["حبس سلطان سلاجقة الأناضول سليمان شاه الثاني، الذي قدم إلى أرضروم أثناء حملة جورجيا، ملكشاه وألغى إمارة السلطوقيين (2 شوال 598 / 25 حزيران/يونيو 1202)، وأعطى أرضروم لأخيه ملك البستان مغيث الدين طغرل شاه. وبقيت أراضي السلطوقيين بيد طغرل شاه حتى عام 1225.", "6d717627"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1204-01-01:0":{"b": ["وفاة سليمان شاه الثاني؛ ابنه الصغير قلج أرسلان الثالث يعتلي العرش", "838d74dd"], "d": ["لم يظفر سليمان شاه الثاني بنتيجة من حملة جورجيا عام 1202، وتوفي في الطريق وهو يسير في حملته الثانية على جورجيا عام 1204 (600/1204). وخلفه ابنه الصغير قلج أرسلان الثالث؛ وفُتحت منطقة إسبرطة (إسپارطة) في أثناء حكمه الذي دام سبعة أو ثمانية أشهر.", "6d8da37d"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1204-08-29:0":{"b": ["الجورجيون يغيرون على أذربيجان ويدخلون بلاد شاهات أخلاط وينهبون ملاذكرد وأرجيش", "beb13519"], "d": ["بعد أن أغار الجورجيون إغارة ناجحة على أذربيجان في 601/1204-05، دخلوا بلاد شاهات أخلاط وتقدموا إلى ملاذكرد ثم إلى نواحي أرجيش، فأحرقوا كل مكان وخرّبوه؛ ولم يخرج أمامهم جيش.", "5c1e0212"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1205-03-01:0":{"b": ["غياث الدين كيخسرو الأول يذهب إلى قونية ويجلس على عرش سلاجقة الأناضول للمرة الثانية", "f6332e53"], "d": ["اضطر كيخسرو، إثر احتلال الصليبيين القسطنطينية (يُذكر شباط/فبراير 1204)، إلى الذهاب إلى قلعة حميه في منطقة طرابزون؛ فجاء إلى المدينة في صغر سن قلج أرسلان الثالث وجلس على العرش للمرة الثانية (رجب 601 / آذار/مارس 1205).", "59c0db32"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1207-01-01:0":{"b": ["كيخسرو الأول يستولي على منطقة دينزلي", "47cabadd"], "d": ["في عهد سلطنة غياث الدين كيخسرو الأول الثانية (1205-1211) استُولي على منطقتي دينزلي وأنطاليا (603/1207)؛ وأُخذت أنطاليا في 5 آذار/مارس 1207.", "190b906c"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1211-06-01:0":{"b": ["وفاة كيخسرو الأول في حرب مع الجيش البيزنطي قرب ألاشهر؛ الجيش البيزنطي أيضًا يتكبد خسائر فادحة", "fdac0ce7"], "d": ["توفي كيخسرو في حرب مع الجيش البيزنطي قرب ألاشهر؛ وتكبد الجيش البيزنطي أيضًا خسائر فادحة. ودُفن جثمانه أولًا في ألاشهر، ثم نُقل إلى قونية ودُفن في ضريح السلاطين بجوار جامع علاء الدين (أواخر حزيران/يونيو 1211).", "fd58f9bc"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1211-06-15:0":{"b": ["أركان الدولة يجتمعون في قونية ويقررون إجلاس ملك ملطية عز الدين كيكاوس على العرش السلجوقي؛ كيكاوس الأول يُعلن سلطانًا في قيصرية", "f80be390"], "d": ["إثر وفاة كيخسرو الأول (608/1211)، قرر أركان الدولة إجلاس ملك ملطية عز الدين كيكاوس على العرش لأنه الابن الأكبر، وأرسلوا إليه رسولًا ليأتي إلى قيصرية؛ ولم يعترف أخوه علاء الدين كيقباد بسلطنته.", "09e0f400"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1212-01-01:0":{"b": ["كيقباد لا يعترف بسلطنة أخيه الأكبر كيكاوس الأول ويثور؛ يتحصن في قلعة أنقرة ثم يستسلم", "13cc17e2"], "d": ["حاصر علاء الدين كيقباد، الذي ثار على عز الدين كيكاوس الذي أُعلن سلطانًا في قيصرية بوفاة أبيه، قيصرية مع الملك الأرمني ليون وعمه ملك أرضروم طغرل شاه؛ ولما لم يظفر بنتيجة انسحب إلى قلعة أنقرة، ولما نفد الزاد استسلم بشرط ألا يُمَس هو ولا الأهالي بسوء (608/1212).", "7b48bb7a"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1220-01-01:0":{"b": ["وفاة عز الدين كيكاوس الأول في فيرانشهر قرب ملطية أثناء الإعداد لحملة حلب", "61f16209"], "d": ["بعد وفاة الأيوبي الملك الظاهر صاحب حلب (1216) وجلوس ابنه الطفل على العرش، سار عز الدين كيكاوس على حلب وتحالف مع الأرتقي ناصر الدين محمود صاحب آمد وكوكبري صاحب إربل؛ وبينما كان قد جاء إلى ملطية مرض وتوفي في فيرانشهر قرب ملطية (شوال 616 / كانون الثاني/يناير 1220).", "a8264a2f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1220-01-01:1":{"b": ["إخراج علاء الدين كيقباد من السجن وإعلانه سلطانًا في سيواس", "2e697d48"], "d": ["أُخرج كيقباد من السجن إثر وفاة عز الدين كيكاوس الأول وأُعلن سلطانًا في سيواس (616/1220). وأحاط قونية وسيواس وقيصرية بالأسوار في مواجهة الغزو المغولي.", "c731bdd7"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1220-01-01:2":{"b": ["المغول يهزمون الجورجيين للمرة الأولى", "b869830b"], "d": ["هزم المغول الجورجيين للمرة الأولى عام 1220، ودخلوا جورجيا عام 1231.", "7f39fa9d"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1225-01-13:0":{"b": ["الملك الأرمني هيتوم يطلب الصلح من كيقباد؛ يُعقد الصلح مقابل جزية سنوية قدرها 40.000 قطعة ذهبية ومساعدة عسكرية", "0d137195"], "d": ["إثر شكوى التجار من الفرنجة والأرمن، أعلن كيقباد عام 622 (1225) الحرب على الأرمن والصليبيين؛ فأرسل الملك الأرمني هيتوم رسولًا وطلب الصلح. وتعهد الملك بأن يدفع للسلطان كل سنة 40.000 قطعة ذهبية، وأن يرسل السلطان متى شاء 1000 فارس و500 من رماة المنجنيق (الجرخية).", "9d0f1a8e"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1228-01-01:0":{"b": ["علاء الدين كيقباد يستولي على أرزنجان وينهي فرع أرزنجان من المنكوجكيين", "edfdc566"], "d": ["تحرك كيقباد ضد المنكوجكيين الذين أرادوا الاستقلال، وضم أرزنجان إلى أراضي سلاجقة الأناضول عام 625/1228؛ وأُعطي ملك شبين قره حصار من الأسرة مظفر الدين قرشهر إقطاعًا، ومعها بعض الأماكن، وأُعطي أفسوس ملكًا.", "ba31e942"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1228-01-01:1":{"b": ["انتهاء حكم الملك مظفر الدين حاكم فرع شبين قره حصار من المنكوجكيين؛ قرشهر تُقطع له", "1ec2fd55"], "d": ["أنهى علاء الدين كيقباد عام 1228 فرع أرزنجان من المنكوجكيين؛ وأُعطي حاكم شبين قره حصار من الأسرة الملك مظفر الدين قرشهر إقطاعًا، ومعها بعض الأماكن، وأُعطي بلدة أفسوس ملكًا.", "e17ab2ba"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1232-01-01:0":{"b": ["الجيوش السلجوقية تستولي على بعض القلاع في جورجيا؛ الملكة روسودان تعرض الصلح وتقبل تزويج ابنتها تامارا من كيخسرو الثاني", "2a057d64"], "d": ["في عهد علاء الدين كيقباد الأول، قام كمال الدين كاميار ومبارز الدين جاولي عام 1232 بحملة على جورجيا واستوليا على بعض القلاع؛ ولم تستطع الملكة روسودان مقاومة الجيش السلجوقي فعرضت الصلح، وقبلت تزويج ابنتها تامارا من غياث الدين كيخسرو الثاني ابن كيقباد.", "c8ce3253"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1234-01-01:0":{"b": ["فرع خربوت يقع في يد سلاجقة الأناضول", "f2572ad0"], "d": ["استولى علاء الدين كيقباد على خربوت عام 631/1234 في مواجهة زحف الأيوبيين إلى الأناضول؛ وانتهى حكم فرع خربوت من الأرتقيين (وبعد كوسه داغ وقعت المدينة في يد الإيلخانيين).", "b0bea54d"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1236-01-01:0":{"b": ["المغول يحتلون جورجيا ثانية ويرسلون أعيان الجورجيين إلى منغوليا", "245ae81a"], "d": ["لما احتل المغول جورجيا ثانية في 633/1235-36، أرسلوا أعيان الجورجيين إلى منغوليا؛ فبقوا هناك سنوات. واستخدم المغول أعدادًا كبيرة من الجنود الجورجيين في حملاتهم.", "159ea654"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1237-05-31:0":{"b": ["وفاة علاء الدين كيقباد الأول مسمومًا بلحم صيد؛ ابنه غياث الدين كيخسرو الثاني يخلفه", "5d74714c"], "d": ["توفي كيقباد، الذي أنهى عصر صعود السلاجقة، في اليوم التالي مسمومًا بلحم صيد أكله في المأدبة التي أقامها للرسل في عيد الفطر (4 شوال 634 / 31 أيار/مايو 1237)؛ واعتلى كيخسرو الثاني العرش بجهد رجال الدولة بدلًا من ولي العهد عز الدين قلج أرسلان.", "7b42c0c6"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1239-01-01:0":{"b": ["الجيش المغولي بقيادة جورماغان نويان يستولي على قارص ويخرّبها أثناء حملة جورجيا", "f510f715"], "d": ["استولى الجيش المغولي بقيادة جورماغان نويان على قارص وخرّبها عام 636/1239 أثناء حملة جورجيا؛ وبقيت المدينة تحت إدارة الإيلخانيين حتى عام 1336.", "38d144da"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1242-01-01:0":{"b": ["القائد المغولي بايجو نويان يستولي على أرضروم ويُعمل السيف في أهلها", "118b9e3a"], "d": ["استغل القائد المغولي في أذربيجان بايجو نويان ضعف السلاجقة بثورة البابائيين، فاستولى على أرضروم في أواخر عام 1242 وأعمل السيف في أهلها، وعاد إلى موغان ليهاجم الأناضول مرة أخرى في الربيع.", "dcfa189c"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1243-01-01:0":{"b": ["المغول، بعد احتلالهم الأناضول عقب كوسه داغ، يستولون على أماسيا ويحكمونها بولاة مغول", "3b39a0ad"], "d": ["استولى المغول، الذين احتلوا الأناضول بعد معركة كوسه داغ عام 1243، على أماسيا، وبدأ ولاة مغول يديرون المدينة.", "a9d1a1e2"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1243-01-01:1":{"b": ["قيصرية تقع في يد المغول بعد مقاومة دامت عشرة أيام إثر هزيمة كوسه داغ", "5600cbe9"], "d": ["وقعت قيصرية بعد معركة كوسه داغ (1243) في يد المغول إثر مقاومة دامت عشرة أيام، ولحق بها دمار كبير.", "924187ac"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1243-01-01:2":{"b": ["الملكة روسودان تقبل دفع الجزية للمغول وتعترف رسميًّا بالخان الأعظم سيدًا", "99d19c31"], "d": ["أدركت الملكة روسودان أنها لن تقوى على المغول، فقبلت التبعية لهم بدفع الجزية، واعترفت رسميًّا عام 1243 بالخان الأعظم سيدًا. وبعد وفاة روسودان قسم المغول القفقاس إلى ثماني ولايات.", "c61c6116"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1243-01-01:3":{"b": ["الإيلخانيون يعطون إمارة طوقات لمعين الدين سليمان البرواناه بعد كوسه داغ", "f2938da6"], "d": ["أعطى الإيلخانيون، الذين هيمنوا على دولة سلاجقة الأناضول بعد معركة كوسه داغ، إمارة طوقات لمعين الدين سليمان البرواناه؛ وفي عام 1276 كانت طوقات تحت إدارة نور الدين جبريل.", "d931de12"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1244-01-01:0":{"b": ["القائد المغولي ياسافور نويان يستولي على ملطية فترة وجيزة", "98759910"], "d": ["لم يظفر المغول بنتيجة من أولى محاولاتهم على ملطية بعد نصرهم في كوسه داغ (1243)؛ واستولى ياسافور نويان على المدينة فترة وجيزة عام 1244، وخرّبها بايجو نويان عام 1258.", "78c903ae"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1246-01-01:0":{"b": ["رجال الدولة يعلنون ملك أولوبورلو عز الدين كيكاوس سلطانًا في قرية ألطون طاش من أقشهر", "20d6f3e7"], "d": ["أعلن رجال الدولة عز الدين كيكاوس، الذي كان ملك أولوبورلو (بورغولو) عند وفاة غياث الدين كيخسرو الثاني، سلطانًا في قرية ألطون طاش من أقشهر (643/1246).", "e7c6a924"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1247-01-01:0":{"b": ["الملك هيتوم الأول يرسل أخاه سمباد إلى قراقورم ويعقد مع أخي مونكه خان تحالفًا ضد المماليك", "7413b5e5"], "d": ["أرسل الملك هيتوم الأول أخاه سمباد إلى قراقورم، فبدأ التحالف الرسمي مع الإمبراطورية المغولية.", "769d4bcf"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1251-01-01:0":{"b": ["داود (ديفيد) اللذان عادا من منغوليا بعد اعتلاء منكو خان العرش يحكمان معًا في جورجيا", "f1640157"], "d": ["بعد اعتلاء الخان المغولي الأعظم منكو خان العرش (1251)، عاد إلى بلدهما من قراقورم جورجيان اسم كل منهما داود، كان قد ولّاهما، وحكما معًا؛ ثم حاول باتو خان وهولاكو إقرار السيادة في جورجيا.", "96249933"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1255-01-01:0":{"b": ["قلج أرسلان الرابع يُهزم أمام كيكاوس الثاني في معركة أحمد حصار قرب قيصرية", "edac92e9"], "d": ["بعد وفاة جلال الدين قراطاي، أعلن قلج أرسلان نفسه سلطانًا مستقلًّا في قيصرية (652/1254)؛ وفي العام التالي هُزم أمام كيكاوس في معركة في موضع يسمى أحمد حصار قرب قيصرية.", "d64649d2"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1257-01-01:0":{"b": ["المغول بقيادة ياشموت يستولون على ميافارقين بعد حصار طويل؛ ماردين تصمد ثمانية أشهر", "c2328a27"], "d": ["كلّف هولاكو، وهو في طريقه إلى حملة سوريا عام 1257، فرقةً بقيادة ياشموت بالاستيلاء على ماردين وميافارقين؛ فسقطت ميافارقين بعد حصار طويل، وصمدت ماردين المحصنة أكثر من ثمانية أشهر.", "18f326a7"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1257-03-05:0":{"b": ["قلج أرسلان الرابع، الذي جيء به من بورغولو إلى قونية، يُجلس وحده على العرش السلجوقي", "cb3eced9"], "d": ["جيء بقلج أرسلان الرابع، الذي كان في بورغولو (أولوبورلو) بعد هزيمة سلطان خان (654/1256)، إلى قونية، وأُجلس وحده على العرش السلجوقي في 16 صفر 655 / 5 آذار/مارس 1257؛ ولما جاء كيكاوس الثاني إلى قونية في 14 ربيع الآخر 655 / 1 أيار/مايو 1257 أرسل قائده علي بهادر على قلج أرسلان.", "32f17269"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1258-01-08:0":{"b": ["كيكاوس الثاني يخضع ملطية وسيواس وطوقات وأماسيا لحكمه؛ قلج أرسلان ينسحب إلى أرزنجان", "d4834ad1"], "d": ["لما أخضع عز الدين كيكاوس ملطية وسيواس وطوقات وأماسيا لحكمه بمساعدة قادته المشهورين، اضطر قلج أرسلان الرابع إلى الانسحاب إلى أرزنجان (656/1258)؛ ثم قُسمت البلاد إلى قسمين بيرليغ منكو خان (657/1259).", "5954d32b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1259-01-01:0":{"b": ["تقسيم البلاد السلجوقية بين كيكاوس الثاني وقلج أرسلان الرابع بيرليغ منكو خان", "4dacbe83"], "d": ["بعد مغادرة بايجو الأناضول، أُعيد كيكاوس الثاني إلى العرش في قونية (1 أيار/مايو 1257)؛ وبيرليغ منكو خان قُسمت البلاد بين كيكاوس وقلج أرسلان. ولجأ كيكاوس، الذي لم يقبل السيادة المغولية، إلى بيزنطة عام 660/1262.", "c7df29bf"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1260-01-01:0":{"b": ["كرا أرسلان الأرتقي حاكم ماردين يقبل السيادة الإيلخانية", "c6b7b1a6"], "d": ["عانت ماردين الجوع والطاعون في الحصار المغولي الذي دام أكثر من 8 أشهر؛ واعترف قرا أرسلان، الذي تولى الحكم بوفاة نجم الدين غازي، بالسيادة المغولية مقابل رد دارا والخابور ونصيبين ورأس العين إلى الأرتقيين، وأقره هولاكو حاكمًا على ماردين عام 659/1261.", "ff8d14de"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1260-01-01:1":{"b": ["المغول يُهزمون أمام المماليك وينسحبون إلى فارس فيهاجم المماليك قيليقية ويخربونها", "505db4aa"], "d": ["حين هُزم المغول الإيلخانيون أمام المماليك وانسحبوا إلى فارس، هاجم المماليك قيليقية وخربوا البلاد؛ وهذه هي البداية الفعلية للهجمات المملوكية.", "89ccf21b"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1266-01-01:0":{"b": ["معين الدين برواناه يقتل قلج أرسلان الرابع بأيدي المغول ويُجلس ابنه الصغير كيخسرو الثالث على العرش", "27f0dc7a"], "d": ["لما أُجبر قلج أرسلان على القبول بأن تُعطى له سينوب ملكًا، قتله الوزير معين الدين برواناه بأيدي المغول (664/1266) وأجلس مكانه ابنه الطفل كيخسرو الثالث؛ وصار برواناه المسيطر على الدولة بلا منازع.", "4aa91de1"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1266-01-01:1":{"b": ["بيبرس ينزل إلى قيليقية ويأسر ليفون ابن الملك هيتوم صاحب سيس", "2cefee6a"], "d": ["نزل السلطان المملوكي بيبرس إلى قيليقية عام 1266 وأسر ليفون ابن الملك هيتوم صاحب سيس؛ وبموجب الاتفاق اللاحق يرد الملك الأرمني المدن والقلاع التي احتلها ويُطلق سراح ليفون (وفي عام 1268 لم تبقَ في يد الأرمن سوى بهسنى).", "e5f53d00"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1266-01-01:2":{"b": ["بركة خان، خان القبيلة الذهبية، يصل إلى تفليس", "23866ba3"], "d": ["وصل بركة خان إلى تفليس عام 1266؛ وكان مستوى الرخاء في جورجيا الخاضعة للإيلخانيين مع ذلك مرتفعًا إلى حد كبير.", "013e2621"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1268-01-01:0":{"b": ["الأتابكة الذين حكموا نواحي أخالتسيخه وأردهان وأرتفين (أتابكية سامتسخي/مسخيتي) يتولون إدارة المنطقة", "71bb5a86"], "d": ["تولى الأتابكة، حكام نواحي أخالتسيخه وأردهان وأرتفين بين عامي 1268 و1578، إدارة المنطقة، وبقوا في هذه الفترة تابعين للدول الإيلخانية وقره قويونلو وآق قويونلو.", "44bea8bb"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1269-01-01:0":{"b": ["هيتوم الأول يتنازل عن العرش لابنه ليفون الثاني؛ المملكة تصبح فعليًّا تابعة للمماليك", "3d94aadc"], "d": ["تنازل هيتوم الأول عن العرش لابنه ليفون الثاني؛ واضطر ليفون الثاني إلى دفع جزية سنوية كبيرة وصارت المملكة فعليًّا تابعة للمماليك.", "cd7ade63"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1271-01-01:0":{"b": ["السلطان المملوكي بيبرس يرسل أسطولًا من سبع عشرة سفينة على قبرص؛ الهجوم يفشل بسبب عاصفة", "cfeb4521"], "d": ["أرسل بيبرس عام 1271، وهو يستولي على آخر القلاع والمدن التابعة للصليبيين في فلسطين وسوريا، أسطولًا من سبع عشرة سفينة على قبرص، لكن الهجوم فشل بسبب عاصفة هبّت.", "c0ba5344"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1275-01-01:0":{"b": ["تأسيس إمارة صاحب آتا أوغلو في أفيون قره حصار وما حولها", "c909e2f5"], "d": ["أسس أبناء وزير سلاجقة الأناضول صاحب آتا وأحفاده إمارة في أفيون قره حصار وما حولها (1275-1341).", "26972b2f"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1277-06-04:0":{"b": ["الإيلخانيون يدركون خيانة معين الدين سليمان البرواناه وينهون حياته", "9a7cc34e"], "d": ["بعد مغادرة بيبرس الأناضول، جاء الإيلخان أباقا خان بجيش كبير وأمر بقتل 200.000 شخص بحجة التعاون مع المماليك، وأدرك خيانة البرواناه فأنهى حياته، وبدأ الإيلخانيون يديرون دولة سلاجقة الأناضول بموظفين يرسلونهم من تبريز (وفاة البرواناه 676/1277).", "c7bb6ee3"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1280-05-03:0":{"b": ["مسعود الثاني ابن كيكاوس الثاني يأتي إلى سينوب ثم يذهب إلى عاصمة الإيلخانيين للمثول بين يدي أباقا خان", "9b43e13f"], "d": ["جاء مسعود الثاني ابن كيكاوس الثاني وولي عهده إلى سينوب عام 679/1280، ثم ذهب إلى عاصمة الإيلخانيين ومثل بين يدي أباقا خان؛ فأعطاه أباقا خان إدارة أرضروم وأرزنجان وسيواس وديار بكر وخربوت.", "0ddb3753"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1282-04-11:0":{"b": ["أرغون خان يعلن مسعود الثاني سلطانًا ويقتل كيخسرو الثالث", "0afda15b"], "d": ["بعد أن قسم أحمد تكودر الأراضي السلجوقية بين مسعود الثاني وكيخسرو الثالث، أعلن أرغون خان، الذي انتصر في الصراع على العرش الإيلخاني، مسعود الثاني الذي كان في تبريز سلطانًا (681/1282)، وأمر بقتل كيخسرو الثالث الذي كان ينتظر في أرضروم.", "ffa63120"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1284-03-20:0":{"b": ["مسعود الثاني يعود إلى الأناضول ويجلس سلطانًا سلجوقيًّا على العرش أولًا في قيصرية ثم في قونية", "ca5c28f4"], "d": ["عاد مسعود الثاني إلى الأناضول بموافقة أرغون وجلس على العرش في قيصرية وقونية عام 683/1284؛ وبقي «حاكمًا ظلًّا» تحت هيمنة القادة والولاة المغول، وحارب القرمانيين والأشرفيين والجرميانيين.", "c089c457"]},
"OLAYLAR_ORTACAG_ANADOLU_KAFKASYA:1288-11-22:0":{"b": ["وفاة الوزير السلجوقي صاحب آتا فخر الدين علي قرب أقشهر", "9c7034f1"], "d": ["توفي صاحب آتا، الذي خدم كيكاوس نائبًا للسلطنة (657/1259)، وسُجن في قلعة عثمانجق عام 670/1271-72، وأعيد تعيينه وزيرًا عام 674/1275-76، في قرية نادر التابعة لأقشهر في 25 شوال 687 / 22 تشرين الثاني/نوفمبر 1288 بعد حملة بجيش سلجوقي - مغولي متحالف على القرمانيين في أواخر 686 / مطلع 1288؛ ودُفن في ضريحه في قونية.", "f8bf5f4a"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0481-01-01:0":{"b": ["كلوفيس يخلف أباه شيلديريك ملكًا على الفرنجة السالِيين؛ ومركز سلطته تورناي", "e4d35fd1"], "d": ["صار كلوفيس سنة 481، وهو في الخامسة عشرة من عمره، ملكًا على الفرنجة السالِيين خلفًا لأبيه شيلديريك الأول. وكان الفرنجة السالِيون قد تقدموا حينئذ حتى نهر السوم، وكان مركز قوتهم تورناي.", "d4c684f8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0486-01-01:0":{"b": ["كلوفيس يهزم سياغريوس في معركة سواسون؛ الإمارة الرومانية الباقية جنوب السوم تنتقل إلى الفرنجة", "afa05aa7"], "d": ["هاجم كلوفيس سنة 486 القائد الروماني سياغريوس؛ ولجأ سياغريوس المهزوم في معركة سواسون إلى ملك القوط الغربيين ألاريك الثاني، وسُلّم إليه. ثم نقل كلوفيس إقامته إلى سواسون، وأخذ بلجيكا الثانية (وعاصمتها ريمس) قطعة قطعة.", "f20e6e70"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0496-12-25:0":{"b": ["كلوفيس يُعمَّد في ريمس على يد الأسقف ريميجيوس (عيد الميلاد)", "16299c9a"], "d": ["ذهب كلوفيس إلى ريمس بعد انتصاره على الألامان، وعُمّد على يد القديس ريميجيوس يوم عيد الميلاد سنة 496 مع ثلاثة آلاف من الفرنجة. وجذب التعميد أنظار الكاثوليك في مملكتي بورغندي والقوط الغربيين إلى كلوفيس.", "2d58bf65"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0507-01-01:0":{"b": ["كلوفيس يقتل ملك القوط الغربيين ألاريك الثاني في فويه (قرب بواتييه)؛ أراضي القوط حتى البرانس تنتقل إلى الفرنجة", "e8ea0c78"], "d": ["بعد أن أتم كلوفيس إخضاع الألامان سنة 506، زحف في العام التالي على ملك القوط الغربيين ألاريك الثاني. وقتل ألاريك بيده في فويه قرب بواتييه؛ وضُمّ جزء مملكة القوط الغربيين الممتد حتى البرانس، عدا سبتمانيا، إلى الدولة الفرنجية.", "e632a672"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0511-11-27:0":{"b": ["وفاة كلوفيس؛ يُدفن في باريس التي جعلها عاصمة في سنواته الأخيرة؛ ووحدة المملكة تبقى ميراثًا للميروفنجيين", "c6c9caa4"], "d": ["قضى كلوفيس سنواته الأخيرة في باريس وجعلها عاصمة المملكة؛ وبقضائه على صغار ملوك الفرنجة في مراكز مثل كامبريه وكولونيا صار الملك الوحيد لجميع قبائل الفرنجة. وتوفي سنة 511.", "eeb42f8c"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0756-01-01:0":{"b": ["بيبين الثالث يأخذ إكسرخسية رافينا من اللومبارديين في حملاته على إيطاليا ويهبها للبابا؛ نشأة الدولة البابوية", "f6bbc975"], "d": ["قام بيبين الثالث بحملتين على إيطاليا في 754 و756 بدعوة من البابا استفانوس الثاني؛ ووهب للبابا إكسرخسية رافينا التي أخذها من ملك اللومبارديين أيستولف، فصار منشئ الدولة الدنيوية للبابوية. ومنح بيبين البابا لقب «بطريق الرومان».", "0e4f19d8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0800-12-25:0":{"b": ["شارلمان يُعلَن إمبراطورًا ويتوَّج في روما في كنيسة القديس بطرس على يد البابا ليو الثالث", "3d72f37d"], "d": ["ذهب شارلمان إلى روما سنة 800 بقصد الإصلاح؛ وفي يوم عيد الميلاد التالي، بينما كان ينهض من الصلاة في كنيسة القديس بطرس، توّجه البابا ليو الثالث وأعلنه إمبراطورًا وأغسطس.", "d6956767"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0814-01-28:0":{"b": ["شارلمان يموت في آخن ويُدفن في اليوم نفسه في كنيسة السيدة العذراء", "915d6f61"], "d": ["قضى شارلمان معظم سنواته الأخيرة في آخن (إكس). وأصابته الحمى في مطلع 814، وتوفي في 28 يناير 814 بعد أن تناول القربان إثر ذات الجنب، ودُفن في اليوم نفسه في كنيسة السيدة العذراء في آخن؛ وخلفه ابنه لويس التقي.", "8ce37094"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0842-02-14:0":{"b": ["قسم ستراسبورغ: شارل الأصلع ولويس الجرماني يتعاهدان في ستراسبورغ", "b462f12a"], "d": ["في السنة التالية لنصر فونتنوي، ثبّت شارل الأصلع ولويس الجرماني تحالفهما بقسم ستراسبورغ؛ فأقسم شارل بلغة شعب لويس الجرمانية، وأقسم لويس بلغة رعايا شارل الرومانية.", "02ceae89"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0843-08-10:0":{"b": ["معاهدة فردان: تقسيم الإمبراطورية الكارولنجية إلى ثلاثة أقسام (فرنسا الغربية وفرنسا الوسطى وفرنسا الشرقية)", "1b628d03"], "d": ["اقتسم أبناء لويس التقي الإمبراطورية بالمعاهدة التي أُبرمت في فردان في أغسطس 843: أخذ شارل الأصلع غرب خط ميز-سون-رون (فرنسا الغربية، بما فيها الثغر الإسباني)، وأخذ لويس الجرماني شرق الراين (بافاريا وتورينغن وفرانكن وساكسونيا، وكذلك محيط شباير-فورمس-ماينتس)، وأخذ لوثير إيطاليا واللقب الإمبراطوري والشريط الممتد في واديي الراين والرون.", "5bda08ed"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0875-12-25:0":{"b": ["شارل الأصلع يتوَّج بالتاج الإمبراطوري في روما", "49f42456"], "d": ["نزل شارل الأصلع إلى إيطاليا بدعم من البابا يوحنا الثامن بعد وفاة لويس الثاني، فنال تاج ملك إيطاليا في بافيا وتاج الإمبراطورية في روما.", "d63d65ae"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0893-01-28:0":{"b": ["شارل البسيط يتوَّج ملكًا في ريمس؛ بداية مملكة منافسة لأودو", "ccc4acd5"], "d": ["أُقصي شارل الثالث «البسيط» بسبب حداثة سنه حين خُلع شارل السمين سنة 887؛ وفي عهد ملك أودو توّج في ريمس في 28 يناير 893 باعتراف بعض الأعيان، وبتحالفه مع الإمبراطور أجبر أودو على التخلي عن جزء من نوستريا. وبوفاة أودو سنة 898 ملك المملكة كلها.", "cd52d1cb"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0911-01-01:0":{"b": ["معاهدة سان كلير سور إيبت: شارل البسيط يترك للنورمان نورماندي الحالية", "fd0306b0"], "d": ["أبرم شارل الثالث سنة 911 معاهدة مع النورمان في سان كلير سور إيبت؛ وعُمّد جزء من النورمان، وتُركت لهم الأرض التي ستُعرف لاحقًا بدوقية نورماندي. وقصة زواج رولو من أخت الملك من رواية دودو، وهي مشكوك فيها جدًّا.", "5798ced7"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0923-06-15:0":{"b": ["معركة سواسون: مقتل الملك روبير الأول وانتخاب راؤول دوق بورغندي ملكًا", "4430302d"], "d": ["قُتل روبير، الذي انتُخب سنة 922 ملكًا ضد شارل البسيط، في معركة سواسون؛ وانتخب أنصار روبير المنتصرون راؤول (رودولف) دوق بورغندي ملكًا. ووثق شارل بهربرت كونت فيرماندوا فوقع في الأسر، وتوفي في بيرون سنة 929.", "9c2c291f"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0955-08-10:0":{"b": ["معركة ليشفلد: أوتو الأول ينهي الغارات المجرية", "7bd31ba4"], "d": ["زحف أوتو على المجريين الذين كانوا يحاصرون أوغسبورغ، وخلّص ألمانيا من غارات المجر بنصره الكبير في ليشفلد في 10 أغسطس 955؛ وهزم السلاف أيضًا في السنة نفسها.", "fbb1b763"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:0962-02-02:0":{"b": ["أوتو الأول يتوَّج بالتاج الإمبراطوري في روما؛ بداية الإمبراطورية الرومانية المقدسة الجرمانية", "24571f97"], "d": ["عبر أوتو إلى إيطاليا بنداء من البابا يوحنا الثاني عشر لنصرته ضد برنجار؛ وبعد وصوله إلى بافيا في عيد الميلاد سنة 961، توّج بالتاج الإمبراطوري في روما في 2 فبراير 962، وأقرّ الحقوق والامتيازات البابوية. وحلف أهل روما أن ينالوا موافقة الإمبراطور عند انتخاب البابا.", "6e725f97"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1016-04-23:0":{"b": ["وفاة إثلريد الثاني؛ كنوت يُنتخب ملكًا من الأعيان المجتمعين في ساوثهامبتون", "35653e3c"], "d": ["بعد وفاة إثلريد الثاني في 23 أبريل 1016، انتخب مجلس الأعيان في ساوثهامبتون الدنماركي كنوت ملكًا؛ وبقيت لندن على ولائها لإدموند. وانتصر كنوت في المعركة الكبرى في أسَندون، وبعد وفاة إدموند في نوفمبر 1016 انتُخب في مطلع 1017 ملكًا على إنجلترا كلها.", "3a49dfc2"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1032-01-01:0":{"b": ["الملك هنري الأول يمنح أخاه روبير دوقية بورغندي؛ بداية دوقية بورغندي الكابيتية (أول بيت دوقي)", "18dcd0ab"], "d": ["منح هنري الأول، ملك فرنسا، سنة 1032 دوقية بورغندي لأخيه روبير؛ ومن روبير انحدر أول بيت دوقي كابيتي، الذي استمر حتى 1361.", "cbb03a09"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1032-01-01:1":{"b": ["وفاة رودولف الثالث آخر ملوك مملكة بورغندي (آرل)؛ بلاده تؤول إلى كونراد الثاني (الإمبراطور الألماني) — بازل تدخل أراضي الإمبراطورية", "4dc8eb08"], "d": ["ترك رودولف الثالث (993-1032)، آخر ملوك مملكة بورغندي (بورغندي جورا/آرل)، أراضيه للإمبراطور كونراد الثاني حين مات بلا وريث. وهذا الميراث هو مصدر الحقوق الإمبراطورية التي عُرفت بعد القرن 13 بمملكة آرل، وتشمل جزءًا من سويسرا الحالية الممتد من جورا إلى نهر آر، وفرانش-كونته وليونيه ودوفينيه وسافوي وبروفانس. ومنذ 888 كانت سلطة المملكة معترفًا بها في أسقفيات بيزانسون وبازل ولوزان وجنيف وسيون.", "54aa5fa8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1032-01-01:2":{"b": ["وفاة رودولف الثالث آخر ملوك مملكة بورغندي (آرل)؛ بلاده تؤول إلى كونراد الثاني (الإمبراطور الألماني) — جنيف تدخل أراضي الإمبراطورية", "be189789"], "d": ["ترك رودولف الثالث (993-1032)، آخر ملوك مملكة بورغندي (بورغندي جورا/آرل)، أراضيه للإمبراطور كونراد الثاني حين مات بلا وريث. وهذا الميراث هو مصدر الحقوق الإمبراطورية التي عُرفت بعد القرن 13 بمملكة آرل، وتشمل جزءًا من سويسرا الحالية الممتد من جورا إلى نهر آر، وفرانش-كونته وليونيه ودوفينيه وسافوي وبروفانس. ومنذ 888 كانت سلطة المملكة معترفًا بها في أسقفيات بيزانسون وبازل ولوزان وجنيف وسيون.", "54aa5fa8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1032-01-01:3":{"b": ["وفاة رودولف الثالث آخر ملوك مملكة بورغندي (آرل)؛ بلاده تؤول إلى كونراد الثاني (الإمبراطور الألماني) — ليون تدخل أراضي الإمبراطورية", "78601ea1"], "d": ["ترك رودولف الثالث (993-1032)، آخر ملوك مملكة بورغندي (بورغندي جورا/آرل)، أراضيه للإمبراطور كونراد الثاني حين مات بلا وريث. وهذا الميراث هو مصدر الحقوق الإمبراطورية التي عُرفت بعد القرن 13 بمملكة آرل، وتشمل جزءًا من سويسرا الحالية الممتد من جورا إلى نهر آر، وفرانش-كونته وليونيه ودوفينيه وسافوي وبروفانس. ومنذ 888 كانت سلطة المملكة معترفًا بها في أسقفيات بيزانسون وبازل ولوزان وجنيف وسيون.", "54aa5fa8"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1066-01-05:0":{"b": ["وفاة إدوارد المعترف؛ هارولد غودوينسون يُنتخب ملكًا ويتوَّج في لندن", "3ff7af82"], "d": ["توفي إدوارد المعترف، الذي لم يستطع حضور تكريس دير وستمنستر، في 5 يناير 1066؛ وأوصى وهو يحتضر بهارولد خلفًا له. فانتُخب هارولد وتوّج على الفور؛ وبعد أن رفضته نورثمبريا أول الأمر انصاعت له أيضًا. وطالب وليم بالعرش محتجًّا بوصية إدوارد وبوعد هارولد نحو سنة 1064، واستعد للغزو.", "c67100ae"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1066-12-25:0":{"b": ["دوق نورماندي وليم يتوَّج في وستمنستر ملكًا على إنجلترا", "92ddd637"], "d": ["نزل وليم في بيفنسي في 28 سبتمبر 1066، وسحق هارولد في معركة سينلاك (هاستينغز) في 14 أكتوبر؛ وتوّج في وستمنستر يوم عيد الميلاد. واستغرق إخضاعه جنوب إنجلترا وغربها وشمالها خمس سنوات أخرى.", "78756409"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1068-01-01:0":{"b": ["وليم الفاتح يشن حملة على إكستر الثائرة", "cc25aa87"], "d": ["قضى وليم سنة 1068 في حملات عسكرية على إكستر ويورك اللتين لجأ إليهما أنصار هارولد.", "e1fb87c6"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1069-01-01:0":{"b": ["ثورة الشمال: الدنماركيون والإنجليز يستولون على يورك؛ وليم يحاصر المدينة ويستردها ويخرّب الشمال", "c15ad892"], "d": ["بعد مقتل روبير كومين في دورهام أعلن الشمال إدغار أثلينغ ملكًا، وأرسل الملك الدنماركي سوين أسطولًا؛ فاستولى الدنماركيون والإنجليز على يورك التي كانت محمية بقلعتين نورمانديتين. وزحف وليم إلى يورك وطرد الدنماركيين إلى سفنهم، وأخذ المدينة بالحصار، وخرّب البلاد حتى دورهام؛ وأتم في مطلع 1070 إخضاع الشمال بزحفه إلى تشيستر.", "a4420b47"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1075-01-01:0":{"b": ["البابا غريغوريوس السابع يحظر التنصيب العلماني في تعيين رجال الدين (منح الرتب بيد غير رجال الدين)", "bc8488be"], "d": ["جاء حظر التنصيب العلماني بعد سنتين من انتخاب هيلدبراند بابا باسم غريغوريوس السابع سنة 1073، فهدّد سلطة الإمبراطورية على التعيينات الدينية، وكان بداية الصراع المفتوح مع هنري الرابع.", "c78da49d"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1080-03-07:0":{"b": ["البابا غريغوريوس السابع يحرم هنري الرابع للمرة الثانية ويعلن خلعه", "d73a0f3d"], "d": ["بعد نصر فلاركهايم (27 يناير 1080)، وتحت ضغط الساكسون وتأثير معلومات خاطئة، ترك غريغوريوس السابع سياسة الانتظار؛ فأعلن في 7 مارس 1080 حرمان هنري مجددًا وخلعه، وحلّل رعاياه من أيمان الولاء. وكان الأثر أضعف كثيرًا مما كان سنة 1076؛ وعزل مجمع براكسن غريغوريوس في 25 يونيو 1080.", "518e832b"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1111-04-13:0":{"b": ["هنري الخامس يتوَّج بالتاج الإمبراطوري في روما؛ مسألة التنصيب تُحسم بتسوية قصيرة الأمد", "f7e1aee5"], "d": ["نال هنري الخامس في سوتري في فبراير 1111 وعدًا بالتاج الإمبراطوري مقابل التخلي عن التنصيب؛ وانتُزع من البابا باسكال الثاني حق التنصيب ووعد التتويج، وأُقيم حفل التتويج في 13 أبريل 1111. وبعد مغادرة هنري روما أعلن مجمع أن هذا الامتياز باطل.", "5d77b395"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1152-01-01:0":{"b": ["هنري (الثاني) يتزوج إليانور فيكسب بواتو وغيين وغسقونية", "4db69859"], "d": ["صار هنري بلانتاجنت سنة 1150 دوق نورماندي، وسنة 1151 كونت أنجو بوفاة أبيه؛ وبزواجه سنة 1152 من إليانور، التي طلقت ملك فرنسا لويس السابع، حصل على بواتو وغيين وغسقونية — وهي النصف الجنوبي للإمبراطورية الأنجوية. وأثار الزواج عداوة سيده لويس السابع.", "39880a5d"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1154-10-25:0":{"b": ["وفاة الملك ستيفن؛ هنري الثاني يعتلي عرش إنجلترا دون أي مقاومة", "e1882039"], "d": ["كان هنري قد انتزع سنة 1153 من ستيفن، بمساعدة الكنيسة وأنصار أمه ماتيلدا، الاعتراف بحقه في وراثة العرش الإنجليزي؛ فلما توفي ستيفن في 25 أكتوبر 1154 طرح مطالبته دون معارضة. وجمعت الإمبراطورية الأنجوية الأراضي الممتدة من إنجلترا إلى البرانس.", "82a14d22"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1155-06-18:0":{"b": ["فريدريك الأول بربروسا يتوَّج بالتاج الإمبراطوري في روما", "94350025"], "d": ["نال فريدريك في حملته الإيطالية الأولى سنة 1154 التاج الإمبراطوري في روما في 18 يونيو 1155؛ وعاد إلى ألمانيا في الخريف بسبب قلة قواته والعداوة التي نشأت.", "ae0ad79e"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1157-01-01:0":{"b": ["مجلس بيزانسون: نبلاء بورغندي يقدمون الولاء لفريدريك؛ تصاعد الصراع بين البابا والإمبراطور", "7252823d"], "d": ["في المجلس الذي انعقد في بيزانسون في أكتوبر 1157 أقسم النبلاء البورغنديون يمين الولاء لفريدريك؛ وتفاقم الخلاف بين البابا والإمبراطور بسبب القبض على رئيس الأساقفة السويدي أثناء عودته من روما.", "7b20ab27"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1173-01-01:0":{"b": ["ريموند الخامس كونت تولوز يقسم يمين الولاء لهنري الثاني", "460d9e41"], "d": ["أجبر هنري الثاني، الذي ورث مطالب إليانور في تولوز، ريموند الخامس كونت تولوز سنة 1173، بعد صراع طويل، على أن يقسم له يمين الولاء على تولوز.", "1727d885"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1176-05-29:0":{"b": ["معركة ليغنانو: الرابطة اللومباردية تهزم فريدريك الأول", "b7613445"], "d": ["في حملته الإيطالية الخامسة سنة 1174، كانت الرابطة اللومباردية قد تأسست ضد فريدريك وشُيّدت قلعة أليساندريا. ولما لم يساعده هنري الأسد دوق ساكسونيا، هُزم فريدريك في ليغنانو في 29 مايو 1176؛ وظُنّ أنه جُرح ومات. وانسحب إلى بافيا وبدأ مفاوضات السلام مع البابا ألكسندر الثالث.", "4d37e6ac"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1177-01-01:0":{"b": ["معاهدة البندقية: فريدريك بربروسا والبابا ألكسندر الثالث يتصالحان؛ هدنة ست سنوات مع الرابطة اللومباردية", "041665b3"], "d": ["بعد ليغنانو اعترف فريدريك بموجب معاهدة البندقية في أغسطس 1177 بألكسندر الثالث بابا شرعيًّا ورُفع عنه الحرمان (قبّل قدم البابا في يوليو 1177)؛ وعُقدت هدنة لمدة ست سنوات مع الرابطة اللومباردية. وتُرك ميراث ماتيلدا لقرار التحكيم.", "1b138556"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1183-06-25:0":{"b": ["معاهدة كونستانس: فريدريك يعقد سلامًا دائمًا مع الرابطة اللومباردية", "91ea5aaf"], "d": ["عُقدت في يونيو 1183 في كونستانس معاهدة مع الرابطة اللومباردية (سلام دائم حلّ محل الهدنة ذات الست سنوات سنة 1177). وكان هنري الأسد دوق ساكسونيا قد جُرّد في تلك الأثناء من دوقيته ونُفي، وتفككت الدوقية؛ وفي 1184 خُطب ابنه هنري إلى كونستانس ابنة روجر ملك صقلية.", "97ab19ec"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1201-01-01:0":{"b": ["استسلام نويس: أوتو الرابع يعترف بالسلطة البابوية على الأراضي البابوية", "b43b4c91"], "d": ["اعترف الإمبراطور الألماني أوتو الرابع بموجب استسلام نويس سنة 1201 بالسلطة البابوية على المنطقة الممتدة من رادي كوفاني إلى ممر تشيبرانو (إكسرخسية رافينا والمدن الخمس وثغر أنكونا وأسقفية سبوليتو وأملاك ماتيلدا وكونتية بريتينورو). وبقي جزء من هذه الأراضي قرونًا مجرد رغبة بابوية؛ ويؤرخ الضم الفعلي لأماكن مثل رافينا وأنكونا وبولونيا وفيرارا بالقرن 16.", "e76fd40c"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1204-01-01:0":{"b": ["فيليب أوغسطس يفتح نورماندي: الاتحاد القائم مع إنجلترا منذ 1106 ينتهي؛ ومين وتورين وأنجو وبواتو تنتقل إلى فرنسا في 1204-1205", "ad5f7cb2"], "d": ["بعد أن أمر جون بلا أرض بقتل آرثر، استولى فيليب أوغسطس على نورماندي في 1203-1204 (حصار شاتو غيار من سبتمبر 1203 إلى أبريل 1204، وروان في 24 يونيو 1204). وكان فتح مين وتورين وأنجو وبواتو في 1204 و1205 سهلًا كأنه «نزهة تقريبًا»؛ ولم تصمد سوى قلعتي لوش وشينون سنة أخرى.", "e587727d"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1204-01-01:1":{"b": ["تورين (تور) تنتقل إلى التاج الفرنسي", "220394a0"], "d": ["ربطت فتوحات فيليب أوغسطس على اللوار في 1204-1205 مين وتورين وأنجو وبواتو بملك فرنسا؛ وصمدت قلعتا لوش وشينون سنة أخرى.", "c3eaca78"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1214-01-01:0":{"b": ["فريدريك الثاني يمنح أوتو الفيتلسباخي بلاتينية الراين (كونتية البلاتين في أسرة فيتلسباخ)", "5f54fd76"], "d": ["عند وفاة هنري كونت بلاتين الراين سنة 1214، منح الملك الألماني فريدريك الثاني البلاتينية لأوتو، الابن الأصغر للودفيغ الأول دوق بافاريا (المخطوب لأغنيس أخت هنري). ومنذ استقرار كونراد سنة 1155 في قلعة يوتنبويل قرب هايدلبرغ، كانت هذه المنطقة تُعدّ عاصمة البلاتينية.", "066e8777"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1218-01-01:0":{"b": ["سيمون دي مونفور يموت أثناء حصار تولوز", "6da05355"], "d": ["كان سيمون دي مونفور، قائد الحملة الصليبية على الألبيجيين، قد دخل تولوز سنة 1215، لكنه مات سنة 1218 وهو يحاصر المدينة. وانتقلت قيادة الصليبيين إلى ابنه أموري؛ وتولى ريموند السابع ابن ريموند السادس الكونتية سنة 1222.", "47aa27de"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1229-01-01:0":{"b": ["معاهدة باريس (مو-باريس): ريموند السابع يتخلى عن معظم إقطاعاته للتاج الفرنسي", "ef1cb151"], "d": ["بمعاهدة باريس سنة 1229 جرّد ملك فرنسا أسرة تولوز من معظم إقطاعاتها؛ وكان على الكونتية أن تنتقل إلى التاج الفرنسي سنة 1271 عن طريق جان ابنة ريموند وزوجها ألفونس (أخي لويس التاسع).", "7186cd3b"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1266-07-02:0":{"b": ["ملك النرويج يتخلى عن جزيرة مان والهبرايد لإسكتلندا مقابل 4000 مارك", "e027acbe"], "d": ["أرسل ألكسندر الثالث سنة 1261 سفيرًا إلى النرويج للتنازل عن الجزر، ولما لم يصل إلى نتيجة أعلن الحرب؛ ودُمّر الأسطول النرويجي في لارغز سنة 1263. واضطر ماغنوس ملك مان إلى التخلي عن جميع الجزر ما عدا مان. وفي 1266 تنازل ملك النرويج عن الجزر (بما فيها مان) لإسكتلندا مقابل 4000 مارك؛ ولم يستقر الحكم الإسكتلندي في مان إلا سنة 1275 بهزيمة أهل مان في رونالدزواي.", "fdf0afa6"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1266-07-02:1":{"b": ["ملك النرويج يتخلى عن الهبرايد ومان لإسكتلندا مقابل 4000 مارك: بيل (مان)", "92b7f459"], "d": ["قوّضت هزيمة لارغز سنة 1263 مطالبة النرويج بالهبرايد؛ وفي 1266 ترك ملك النرويج الجزر (بما فيها مان) لإسكتلندا مقابل 4000 مارك.", "11675aa6"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1266-07-02:2":{"b": ["ملك النرويج يتخلى عن الهبرايد لإسكتلندا مقابل 4000 مارك: إيونا (الهبرايد)", "215cac00"], "d": ["اهتزت السيادة النرويجية على الهبرايد بانتصار ألكسندر الثالث على الأسطول النرويجي في لارغز (1263)؛ وفي 1266 تنازل ملك النرويج عن الجزر لإسكتلندا مقابل 4000 مارك.", "81cc8cf0"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1268-10-29:0":{"b": ["إعدام كونرادين في نابولي: انقراض السلالة الذكرية لآل هوهنشتاوفن", "55645d01"], "d": ["حوكم كونرادين، آخر ممثل لأسرة هوهنشتاوفن، في نابولي بتهمة الخيانة بعد هزيمته أمام شارل دوق أنجو في تاليافوتسو (23 أغسطس 1268)، وأُعدم في 29 أكتوبر مع صديقه فريدريك البادني (الدوق الاسمي للنمسا). وانقرضت السلالة الذكرية لآل هوهنشتاوفن.", "d81af0d1"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1271-01-01:0":{"b": ["وفاة ألفونس دي بواتييه وزوجته جان: ميراث كونتية تولوز يؤول إلى التاج الفرنسي", "eabc3640"], "d": ["حين توفي ريموند السابع سنة 1249 آل ميراثه إلى ابنته جان؛ وكانت جان متزوجة من ألفونس أخي لويس التاسع. وبوفاتهما سنة 1271 انتقل الميراث الواسع لكونتات تولوز إلى التاج الفرنسي.", "ee58c39e"]},
"OLAYLAR_ORTACAG_BATI_AVRUPA:1276-11-21:0":{"b": ["سلام فيينا: ملك بوهيميا أوتوكار الثاني يتخلى عن النمسا وشتيريا وكارينثيا وكرانيولا", "db5c2bc4"], "d": ["بعد انتخاب رودولف الهابسبورغي ملكًا (1273) وضع أوتوكار تحت الحظر الإمبراطوري وأعلن عليه الحرب في يونيو 1276؛ وبعد أن انتزع رودولف هنري دوق بافاريا السفلى من أوتوكار، أجبر ملك بوهيميا في نوفمبر 1276 على التخلي عن الولايات الأربع. ومُنح أوتوكار بوهيميا ومورافيا وحدهما إقطاعًا من جديد، وخُطب ابنه فينسلاس إلى ابنة رودولف؛ ودخل رودولف فيينا ظافرًا.", "d79ed14c"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0534-01-01:0":{"b": ["البيزنطيون يستردون أفريقيا الوندالية: قرطاجة تعود إلى الرومان الشرقيين", "ab2096c0"], "d": ["بحملة القائد بيليساريوس، قائد جستنيان الأول، انتُزعت شمال أفريقيا من الوندال وعادت قرطاجة مدينة بيزنطية. وستصبح المدينة لاحقًا مركز إكسرخسية أفريقيا.", "319ada36"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0568-01-01:0":{"b": ["الأفار يدخلون بانونيا: استقرار خاقانية الأفار في حوض الدانوب", "2471607b"], "d": ["بعد انهيار دولة الجبيد، استقر الأفار بقيادة بايان في بانونيا؛ وصار حوض الدانوب وتيسا مركز خاقانية الأفار. وستحاصر الخاقانية القسطنطينية سنة 626، وتشن مع السلاف غارات على البلقان.", "7074a5d1"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0568-04-01:0":{"b": ["اللومبارديون بقيادة ألبوين يحتشدون للزحف إلى إيطاليا (1 أبريل 568)", "677663c6"], "d": ["احتشد اللومبارديون في بانونيا في 1 أبريل 568 بقيادة ألبوين، بعد أن تركوا موطنهم للأفار، وحملوا أسرهم وأموالهم للهجرة إلى إيطاليا. وعبروا حدود فريولي واستولوا على تشيفيدالي ودمروا أكويليا.", "11d42338"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0582-01-01:0":{"b": ["موريس يؤسس إكسرخسية أفريقيا: إدارة عسكرية ومدنية مركزها قرطاجة", "b4b43203"], "d": ["منح موريس لقب «إكسرخوس» للقائد العسكري في أفريقيا وأعطاه الأفضلية على الإدارة المدنية؛ فكان نائب الإمبراطور يحكم من قرطاجة في مواجهة هجمات البربر.", "52939fe9"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0582-01-01:1":{"b": ["موريس يؤسس إكسرخسية رافينا: وضع الأراضي البيزنطية في إيطاليا تحت حاكم عسكري", "6039bf5f"], "d": ["أسند الإمبراطور موريس الإدارة البيزنطية في إيطاليا إلى «إكسرخوس» عُدّ نائبًا عن الإمبراطور في مواجهة اللومبارديين، وصارت رافينا مركزها. ويُعدّ هذا الترتيب الخطوة الأولى نحو نظام «الثيمات» اللاحق.", "543f687c"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0610-10-05:0":{"b": ["هرقل يطيح بفوقاس ويعتلي العرش", "8868d0c0"], "d": ["جاء هرقل، ابن إكسرخوس أفريقيا، بالأسطول إلى القسطنطينية؛ وقُبض على فوقاس صباح 5 أكتوبر 610 وقُتل، وصار هرقل إمبراطورًا. ويرتبط عهده بالحرب مع الفرس والفتوحات العربية وأسس نظام «الثيمات».", "758b6d64"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0626-07-29:0":{"b": ["الأفار والفرس يحاصرون القسطنطينية", "26f1fc15"], "d": ["ضرب خاقان الأفار والقبائل التابعة له معسكرهم أمام أسوار القسطنطينية في 29 يوليو 626، وكان الجيش الفارسي قد نزل في الجانب الآسيوي. وتجاوزت المدينة الحصار بمقاومة شديدة ونجاح الأسطول.", "f96ea122"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0674-01-01:0":{"b": ["الأسطول الأموي يحاصر القسطنطينية برًّا وبحرًا (674-678)", "6242af3a"], "d": ["بدأ أسطول معاوية، بعد استيلائه على شبه جزيرة كابيداغ، حصار القسطنطينية برًّا وبحرًا سنة 674؛ واستمر الهجوم حتى سنة 678.", "9b10c5be"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0717-03-25:0":{"b": ["ليو الثالث يعتلي العرش: بداية الأسرة الإيسورية", "a991b678"], "d": ["بعد فترة الفوضى بين 685 و717، صار القائد (ستراتيجوس) ليو، وهو من أصل إيسوري، إمبراطورًا في 25 مارس 717. وكان على القسطنطينية أن تستعد فورًا لحصار عربي كبير.", "7b99e68e"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0717-08-15:0":{"b": ["مسلمة يبدأ حصار القسطنطينية (15 أغسطس 717)", "ff3c52ac"], "d": ["عبر القائد الأموي مسلمة المضيق من أبيدوس بجيش يبلغ نحو 180.000 مقاتل وأسطول كبير، وحاصر القسطنطينية في 15 أغسطس 717. وساعد الخان البلغاري تيرفيل البيزنطيين بمهاجمة القوات العربية في تراقيا.", "1b3e9a30"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0718-08-15:0":{"b": ["رفع الحصار العربي الثاني عن القسطنطينية", "ed916ed1"], "d": ["أمام المجاعة والبرد والوباء وهجمات البلغار، انسحب مسلمة بأمر من الخليفة عمر الثاني بعد عام كامل، في 15 أغسطس 718. وأوقف هذا النجاح التقدم العربي في أوروبا.", "9a305e2f"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0782-01-01:0":{"b": ["إيرين تعقد الصلح مع هارون الرشيد: القسطنطينية تنجو من الخطر", "7fcd8ae6"], "d": ["حين تقدم جيش القائد العباسي هارون الرشيد حتى قاضي كوي، وقّعت الإمبراطورة إيرين معاهدة صلح، ونجت العاصمة من التهديد العربي.", "7ffffb25"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0787-09-24:0":{"b": ["انعقاد المجمع المسكوني السابع في نيقية: إدانة تحطيم الأيقونات", "124c1212"], "d": ["بدعوة من الإمبراطورة إيرين اجتمع نحو 350 أسقفًا في كنيسة آيا صوفيا (الحكمة المقدسة) في نيقية، وأدانوا تحطيم الأيقونات. وهذا هو آخر مجمع تعدّه الكنيسة الأرثوذكسية مسكونيًّا.", "8444f8b3"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0800-12-25:0":{"b": ["شارلمان يتوَّج إمبراطورًا في روما على يد البابا؛ بيزنطة لا تعترف بذلك", "5ac5f7a9"], "d": ["أُعلن الملك الفرنجي شارل (شارلمان) «إمبراطور الرومان» بعد أن توّجه البابا ليو الثالث في 25 ديسمبر 800. ولما لم تعترف بيزنطة بصفته الإمبراطورية، ظهرت الثنائية بين الدولتين الشرقية والغربية بوضوح.", "dde987c7"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0813-06-22:0":{"b": ["معركة فيرسينيكيا: ميخائيل رانغابي ينهزم أمام كروم", "cc6f63ec"], "d": ["هُزم ميخائيل الأول رانغابي أمام البلغار في 22 يونيو 813 في فيرسينيكيا قرب أدرنة؛ وبدا أن الهزيمة كان قد مهّد لها موقف ستراتيجوس الأناتوليكون ليو الأرمني. ووصل كروم في السنة نفسها إلى أمام القسطنطينية.", "2d3099f5"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0814-04-14:0":{"b": ["وفاة الخان كروم: حملة حصار القسطنطينية تتوقف في منتصفها", "1dde895f"], "d": ["توفي كروم في 14 أبريل 814 بانفجار مفاجئ في أحد الأوعية الدموية، وهو يعدّ جيشًا كبيرًا مزودًا بعدد كثير من آلات الحصار ضد القسطنطينية. وعقد ابنه أومورتاغ مع بيزنطة صلحًا لمدة ثلاثين عامًا.", "e1b684e8"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0827-04-02:0":{"b": ["عرب الأندلس يستقرون في إقريطش: قيام إمارة إقريطش", "2a7c0adc"], "d": ["جاء عرب الأندلس الذين طُردوا بعد ثورة الربض في قرطبة إلى إقريطش بقيادة أبي حفص عمر بن شعيب، وفتحوا الجزيرة تدريجيًّا وأسسوا مدينة ربض الخندق (قنديا). وحكم نسل أبي حفص الجزيرة حتى سنة 961.", "11e895b0"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0860-06-18:0":{"b": ["الروس يظهرون لأول مرة أمام القسطنطينية", "43b4ec06"], "d": ["دخل نحو مائتي سفينة روسية من البحر الأسود إلى المضيق وهاجمت القسطنطينية في 18 يونيو 860؛ وكان الإمبراطور بجيشه على الحدود العربية. وبددت عاصفة الأسطول الروسي.", "6370f840"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0867-01-01:0":{"b": ["أسطول الأغالبة يحاصر دوبروفنيك؛ المدينة تنجو بالأسطول البيزنطي", "9ed0c1d7"], "d": ["حاصر أسطول من الأغالبة المسيطرين على صقلية دوبروفنيك سنة 867؛ ونجت المدينة من حصار دام خمسة عشر شهرًا بمساعدة الأسطول البيزنطي. وبهذا النصر عززت بيزنطة تفوقها في الأدرياتيك.", "1cbf391c"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0904-07-31:0":{"b": ["الأسطول الإقريطشي يستولي على سالونيك وينهبها", "d4ce556a"], "d": ["استولى الأسطول العربي بقيادة ليو الطرابلسي المرتد على سالونيك في 31 يوليو 904 بعد حصار دام ثلاثة أيام؛ وعاد دون أن يتعقبه أحد ومعه أكثر من 30.000 أسير وغنائم. وأظهر هذا الحدث ضعف الأسطول البيزنطي.", "f9cb1530"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0913-01-01:0":{"b": ["القيصر البلغاري سيميون يصل إلى أسوار القسطنطينية", "4e338292"], "d": ["وصل سيميون إلى أسوار القسطنطينية بقصد الحصول على التاج البيزنطي؛ فتوصلت الحكومة معه إلى اتفاق بعد تقديم تنازلات ثقيلة، ومُنح لقب «باسيليوس البلغار».", "0cce5551"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0924-01-01:0":{"b": ["سيميون يحاصر القسطنطينية من جديد", "452b0447"], "d": ["حاصر سيميون القسطنطينية من جديد سنة 924؛ وتجاوزت دبلوماسية رومانوس الأول هذا الخطر أيضًا.", "90de8672"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0926-01-01:0":{"b": ["الملك الكرواتي توميسلاف يوقع الهزيمة بالجيش البلغاري", "21d8e44f"], "d": ["هاجم القيصر البلغاري سيميون كرواتيا حليفة بيزنطة، لكن جيشه هُزم أمام الملك الكرواتي توميسلاف وتفرق. وعزز هذا النصر سلطة المملكة الكرواتية على مدن دالماسيا.", "60abf25d"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0927-05-27:0":{"b": ["وفاة القيصر سيميون: انتهاء عهد الحروب الكبرى في بلغاريا", "ff2c1a5e"], "d": ["توفي سيميون فجأة في 27 مايو 927، وكان قد اضطر إلى طلب الصلح بوساطة البابا. وغيّر موته التوازن في البلقان؛ ولم تؤدّ بلغاريا دورًا فاعلًا في المنطقة طوال الستين عامًا التالية.", "3e140fec"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0927-09-08:0":{"b": ["الصلح البيزنطي البلغاري: بيتار ابن سيميون يتزوج أميرة بيزنطية", "5f781f16"], "d": ["بموجب الصلح الذي وُقّع في خريف 927 بعد وفاة سيميون، تزوج ابنه وخليفته بيتار من ماريا ليكابيني حفيدة رومانوس الأول؛ واعترفت به بيزنطة «إمبراطورًا للبلغار» وقبلت كذلك البطريركية البلغارية المستقلة. وبدأت بين الدولتين فترة سلام طويلة.", "08bf5989"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0963-08-16:0":{"b": ["نقفور فوقاس يصبح إمبراطورًا", "1e752d7a"], "d": ["أُعلن نقفور إمبراطورًا من قبل جيش قيصرية، ودخل العاصمة في 14 أغسطس 963؛ وبعد اشتباكات في الشوارع مع حرس القصر اعتلى العرش في 16 أغسطس. ويرتبط عهده بفتوح إقريطش وقيليقية وأنطاكية.", "b34380fd"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0969-12-10:0":{"b": ["مقتل نقفور فوقاس؛ يوحنا تزيمسكيس يصبح إمبراطورًا", "1232f3d1"], "d": ["بعد ستة أسابيع من فتح أنطاكية، في ليلة 10-11 ديسمبر 969، قُتل نقفور الثاني فوقاس في مؤامرة بالقصر؛ وخلفه يوحنا تزيمسكيس (969-976).", "485e7a85"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0971-04-23:0":{"b": ["تزيمسكيس يهزم سفياتوسلاف أمام دوروستولون (سيليسترا)", "692f203b"], "d": ["خاض تزيمسكيس في 23 أبريل 971 معركة كبرى مع الجيش الروسي بقيادة سفياتوسلاف في السهل الواقع على بعد اثني عشر ميلًا جنوب دوروستولون؛ وانهزمت القوات الروسية، وبدأ في المدينة حصار دام ثلاثة أشهر.", "9a082cf5"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:0986-08-17:0":{"b": ["معركة بوابة تراجان: باسيل الثاني يتلقى هزيمة ثقيلة أمام البلغار", "9060af56"], "d": ["انتهى زحف باسيل الثاني نحو سرديكا (صوفيا) في 17 أغسطس 986 بهزيمة ثقيلة في ممر بوابة تراجان، لأن الإعداد له كان سيئًا ولأن قادته كانوا متنازعين؛ ونجا الإمبراطور بصعوبة.", "7c003379"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1001-01-01:0":{"b": ["باسيل الثاني يستولي على صوفيا", "3006324b"], "d": ["خلال حملات باسيل الثاني السنوية، استولت بيزنطة سنة 1001 على صوفيا التي كانت بيد الدولة البلغارية؛ ثم سقطت فيدين وأسكوب وقلاع أخرى.", "52c0acb4"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1003-01-01:0":{"b": ["فيدين تستسلم للبيزنطيين بعد حصار دام ثمانية أشهر", "4394c5b7"], "d": ["بعد انهيار الدولة البلغارية، قاومت فيدين القوات البيزنطية حتى سنة 1003؛ ثم أُخذت بعد حصار دام ثمانية أشهر. واستمرت السيادة البيزنطية حتى سنة 1185.", "7e2d95ee"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1014-07-29:0":{"b": ["معركة كليديون: باسيل الثاني يبيد الجيش البلغاري", "c8375830"], "d": ["في 29 يوليو 1014 التفّ نقفور كسيفياس من الخلف حول الموقع البلغاري في ممر كليديون («المفتاح») في جبال بيلاسيتسا في وادي ستروما. ونجا صمويل بمساعدة ابنه هاربًا إلى بريليب؛ وفُقئت أعين نحو 15.000 جندي بلغاري وقعوا في الأسر.", "a7b90e39"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1014-10-06:0":{"b": ["وفاة القيصر صمويل", "a71a0c57"], "d": ["أصيب صمويل بنوبة حين رأى جنود جيشه المنهزم في كليديون وقد فُقئت أعينهم، وتوفي بعد يومين، في 6 أكتوبر 1014. وكانت أوخريد عاصمة الإمبراطورية البلغارية الغربية، واستمرت المقاومة أربع سنوات أخرى.", "b75e105a"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1018-01-01:0":{"b": ["ضم الأراضي البلغارية كلها إلى بيزنطة: انتهاء الدولة البلغارية الأولى", "62e8f992"], "d": ["بعد مقتل إيفان فلاديسلاف أمام دورازو، قبل باسيل الثاني في مطلع سنة 1018 عند أبواب أوخريد استسلام أسرة آخر القياصرة، وصارت الأراضي البلغارية حتى الدانوب ولاية بيزنطية بالكامل. واستمر هذا الوضع حتى 1186-1187.", "7686035c"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1018-01-01:1":{"b": ["مقتل إيفان فلاديسلاف أمام دورازو", "75e41587"], "d": ["قُتل القيصر البلغاري إيفان فلاديسلاف (1015-1018)، الذي تولى العرش بعد قتله غافريل رادوميير، في هجوم عقيم على دورازو. ولما بلغ الخبر القسطنطينية خرج باسيل الثاني في حملته الأخيرة، واستسلمت أسرة آخر القياصرة عند أبواب أوخريد.", "38a7f246"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1040-01-01:0":{"b": ["ثورة بيتار دليان: عدد من القلاع، منها أسكوب، يقع في أيدي الثائرين", "7fef5f4f"], "d": ["تحول الاستياء الذي ازداد بإلغاء الضرائب العينية وتحويلها إلى نقود إلى ثورة بقيادة بيتار دليان، حفيد صمويل. وتقدم الثائرون جنوبًا من بلغراد، وبدعم من البوليار المحليين استولوا على عدد من القلاع منها أسكوب.", "86258b6e"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1040-01-01:1":{"b": ["ستيفان فويسلاف يبدأ حركة الاستقلال في زيتا", "ab16166f"], "d": ["كانت ثورة ستيفان فويسلاف الأولى سنة 1036 قد أُخمدت، وسيق هو إلى القسطنطينية؛ وعند اندلاع ثورة بيتار دليان في مقدونيا هرب سنة 1040 وتولى قيادة حركة تحرر جديدة في زيتا. ورغم أن بيزنطة أخمدت ثورة دليان، لم تستطع تجديد سلطتها على زيتا، وبقيت المنطقة مستقلة زمنًا طويلًا.", "d1357c04"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1042-01-01:0":{"b": ["جورج مانياكيس ينزل في تارانتو بصفة كاتيبان إيطاليا", "6281a936"], "d": ["وصل جورج مانياكيس، الذي أخرجه ميخائيل الخامس من السجن وجعله «ماجيستروس وكاتيبان»، إلى تارانتو في أواخر أبريل 1042 خلال حكم زوي وثيودورا المشترك؛ وتوقفت حملاته ضد النورمان وثوار بوليا في سبتمبر 1042 بعزله من منصبه.", "926b3102"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1054-07-20:0":{"b": ["الانشقاق الكبير بين الكنيستين الشرقية والغربية", "22d54273"], "d": ["بقطع البطريرك ميخائيل كيرولاريوس صلاته بروما، تحوّل الخلاف الذي دام قرونًا بين كنيستي روما والقسطنطينية إلى انفصال نهائي.", "6de367fc"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1059-01-01:0":{"b": ["مجمع ملفي: البابا يقر الفتوحات النورماندية", "df9797bd"], "d": ["عكس نقولا الثاني السياسة الشرقية وعقد تحالفًا مع النورمان في مجمع ملفي وأقرّ فتوحاتهم. وقد باركت هذه الاتفاقية صعود النورمان الذي كان يهدد الوجود البيزنطي في جنوب إيطاليا.", "456db916"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1071-01-01:0":{"b": ["سقوط باري بيد النورمان: بيزنطة تفقد إيطاليا", "75af6d4d"], "d": ["بعد حصار دام ثلاث سنوات، استسلمت باري، آخر معاقل بيزنطة في جنوب إيطاليا، لنورمان روبرت غيسكار؛ وبذلك فقدت بيزنطة وجودها في إيطاليا.", "03196667"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1071-08-26:0":{"b": ["معركة ملاذكرد: ألب أرسلان يهزم الجيش البيزنطي ورومانوس الرابع يقع في الأسر", "9ed92850"], "d": ["هزمت القوات التركية للسلطان ألب أرسلان في ملاذكرد في 26 أغسطس 1071 الجيش البيزنطي الذي كان أغلبه من المرتزقة النورمان والفرنجة والغز والبتشنك. ووقع الإمبراطور رومانوس الرابع في الأسر؛ وبدأت عملية انفتاح الأناضول أمام الأتراك.", "d260a768"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1081-04-01:0":{"b": ["ألكسيوس كومنينوس يدخل القسطنطينية: بداية الأسرة الكومنينية", "2c31c531"], "d": ["دخلت قوات ألكسيوس، الذي أعلنه النبلاء العسكريون إمبراطورًا، القسطنطينية في 1 أبريل 1081. ومضى عهد ألكسيوس (1081-1118) في مواجهة تهديدات النورمان والبتشنك والصليبيين.", "89144267"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1082-01-01:0":{"b": ["قسطنطين بودين يصبح حاكم زيتا (دوكليا) ويخضع راشكا والبوسنة", "4eff1f06"], "d": ["اعتلى قسطنطين بودين، ابن ميخائيل (نحو 1050-82، الذي نال لقب ملك من البابا غريغوريوس السابع ورفع أسقفية بار إلى رتبة رئاسة أساقفة)، العرش نحو سنة 1082، وفتح راشكا والبوسنة وأقام فيهما مرشحيه. وهكذا شملت زيتا تقريبًا كل الأراضي التي يسكنها الصرب؛ وسرعان ما تفككت الدولة بسبب نزاعات الأسرة.", "813bc53b"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1091-01-01:0":{"b": ["سلافونيا تُضمّ إلى المجر", "35eb29f1"], "d": ["في أواخر القرن الحادي عشر أدت نزاعات الأسرة الكرواتية إلى الاتحاد مع المجر، وضُمّت منطقة سلافونيا الشمالية جزئيًّا إلى المجر (1091).", "4e53ab25"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1118-08-16:0":{"b": ["يوحنا الثاني كومنينوس يتوَّج", "255f3655"], "d": ["في خضم وفاة أبيه ألكسيوس والصراعات في القصر، توّج يوحنا نفسه وصار إمبراطورًا في 16 أغسطس 1118. ومضى عهده في حملات ضد البتشنك والسلاجقة وفي قيليقية.", "25043caf"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1122-01-01:0":{"b": ["يوحنا الثاني يهزم البتشنك هزيمة حاسمة قرب ستارا زاغورا", "3e585237"], "d": ["هُزم البتشنك، الذين كانوا قد تقدموا حتى تراقيا، هزيمة حاسمة سنة 1122 على يد يوحنا الثاني كومنينوس؛ وبهذا النصر تأمنت الحدود الغربية.", "52eb72c6"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1137-01-01:0":{"b": ["يوحنا الثاني يُخضع قيليقية للسيادة البيزنطية: أخذ المصيصة", "e09dfcbc"], "d": ["أخضع يوحنا الثاني كومنينوس بحملة 1137-1138 سهل قيليقية ومناطق طوروس التي كانت بيد الإمارة الأرمنية الروبينية؛ وتحققت جزئيًّا كذلك السيادة البيزنطية على أنطاكية.", "266b1fc5"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1159-01-01:0":{"b": ["مانويل كومنينوس يدخل أنطاكية في موكب احتفالي", "6a943bb7"], "d": ["أثبت مانويل كومنينوس مجددًا، بحملته على قيليقية وسوريا في 1158-1159، السيادة البيزنطية على إمارة أنطاكية الصليبية؛ ويُعدّ دخوله الاحتفالي إلى أنطاكية ذروة حكمه.", "670785eb"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1171-03-12:0":{"b": ["مانويل كومنينوس يأمر باعتقال جميع البنادقة في الإمبراطورية", "0b1087c4"], "d": ["استاء مانويل من سياسة البندقية في إيطاليا ودالماسيا، فأمر في 12 مارس 1171 باعتقال جميع البنادقة في الإمبراطورية ومصادرة أموالهم. وردّت البندقية بإرسال أسطول.", "01a7fe6d"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1172-01-01:0":{"b": ["مانويل يهزم نيمانيا ويقتاده إلى القسطنطينية: الصرب يقبلون السيادة البيزنطية", "85c3545e"], "d": ["حين ثار ستيفان نيمانيا، الزوبان الأكبر لراشكا، على بيزنطة، هزمه مانويل سنة 1172 وقاده في موكب النصر إلى القسطنطينية؛ ثم أُطلق سراحه ولم يُثر مشكلة حتى وفاة مانويل.", "dea0829e"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1180-01-01:0":{"b": ["ستيفان نيمانيا يجعل الدولة الصربية مستقلة", "8df8e6f5"], "d": ["استفاد ستيفان نيمانيا من الاضطراب الذي أحدثه موت مانويل، فجعل راشكا نواة ووضع أساس دولة صربية كبيرة تشمل زيتا وهوم أيضًا؛ وحافظ على لقب «الزوبان الأكبر». وتُعرف أسرته باسم «النيمانيتش».", "5d62e581"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1180-09-24:0":{"b": ["وفاة مانويل كومنينوس", "ef8d68b9"], "d": ["توفي مانويل الأول في 24 سبتمبر 1180؛ وكان قد رفض حتى اللحظة الأخيرة ترتيب أمر الوصاية. وتبيّن في السنوات 1180-1204 أن الإمبراطورية الرومانية الشرقية فقدت تفوقها الذي كان لها في العصر البيزنطي الوسيط.", "3909f514"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1182-01-01:0":{"b": ["مذبحة اللاتين في القسطنطينية؛ أندرونيقوس كومنينوس يصل إلى السلطة", "cdf8aa39"], "d": ["أنهت ثورة شعبية وصاية أرملة مانويل، وتعرض التجار اللاتين للمذبحة، وارتقى أندرونيقوس كومنينوس إلى السلطة (1182-1185). وزادت المذبحة عداء الغرب لبيزنطة.", "e1babdc2"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1185-01-01:0":{"b": ["النورمان يستولون على سالونيك وينهبونها", "0389d7b9"], "d": ["هاجم النورمان القادمون من صقلية وجنوب إيطاليا سالونيك برًّا وبحرًا في أغسطس 1185 بأسطول من 200 سفينة وجيش؛ ونُهبت المدينة نهبًا فظيعًا. وعجّل هذا الخبر في العاصمة بالثورة على أندرونيقوس.", "f309d689"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1185-01-01:1":{"b": ["ثورة بيتار وأسين: أساس الدولة البلغارية الثانية حول ترنوفو", "fca2ce92"], "d": ["ثار الأخوان البويار بيتار وأسين على الضرائب البيزنطية حول ترنوفو؛ ورغم أن الإمبراطور استعاد الأراضي سنة 1186، استردّ الأخوان شمال بلغاريا بجيش حصلا عليه من الكومان وراء الدانوب، وأُجبرت بيزنطة سنة 1187 على الصلح.", "d0471819"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1185-09-12:0":{"b": ["إسحاق الثاني أنجيلوس يعتلي العرش", "e5f6e2dd"], "d": ["حين علم أهل القسطنطينية باستيلاء النورمان على سالونيك، ثاروا على أندرونيقوس كومنينوس وأجلسوا إسحاق أنجيلوس على العرش في 12 سبتمبر 1185. وبدأ عهد الأسرة الأنجيلية (1185-1204).", "d2f55a2e"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1189-01-01:0":{"b": ["فريدريك بربروسا يستولي على ديموتيكا ويقتل أهلها", "d38b78a4"], "d": ["خلال الحملة الصليبية الثالثة، استولى الإمبراطور الألماني بربروسا على ديموتيكا سنة 1189 وقتل جميع أهلها، عدا النساء والأطفال (نحو 1500 شخص).", "e843c9c5"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1190-01-01:0":{"b": ["البلغار يهزمون إسحاق أنجيلوس", "ab4b84df"], "d": ["بينما كان الحكام الصرب والبلغار يأملون في دعم بربروسا الزاحف إلى الأناضول، هُزم إسحاق أنجيلوس أمام البلغار قرب ستارا زاغورا ونجا بصعوبة. واستولى البلغار على صوفيا ونقلوا رفات القديس إيفان الريلي إلى ترنوفو.", "87219877"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1197-01-01:0":{"b": ["كالويان يعتلي العرش البلغاري", "ad96cfe5"], "d": ["بعد مقتل أسين (1196) وبيتار (1197)، اعتلى أخوهما كالويان (يوانيتسا) العرش البلغاري سنة 1197؛ وحكم حتى 1207 فوسّع بلغاريا وأقام علاقة مع البابوية.", "5adc869f"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1203-04-08:0":{"b": ["البان كولين يعطي ضمانًا بالولاء للعقيدة الكاثوليكية (بيلينو بولي)", "30e1a588"], "d": ["حين اتُّهم بان البوسنة كولين (نحو 1180-1204) بإيواء البتارينيين (البوغوميل)، طلب البابا إنوسنت الثالث من ملك المجر تطهير البلاد منهم. وفي 8 أبريل 1203 أعطى كولين أمام مندوب البابا ضمانًا بالولاء للتعاليم الكاثوليكية.", "1bdcf7f6"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1203-07-17:0":{"b": ["الصليبيون يدخلون القسطنطينية؛ إسحاق الثاني وألكسيوس الرابع يُجلسان على العرش", "e315ae7a"], "d": ["هاجمت جيوش الحملة الصليبية الرابعة القسطنطينية في 17 يوليو 1203 وأجبرت ألكسيوس الثالث على الفرار؛ وأُعيد إسحاق الثاني إلى العرش مع ابنه ألكسيوس الرابع. ولم يُوفَّ لاحقًا بما وعد به ألكسيوس الصليبيين.", "6742de22"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1203-08-01:0":{"b": ["ألكسيوس الرابع أنجيلوس يتوَّج إمبراطورًا مشاركًا", "89f1f57b"], "d": ["توّج ألكسيوس، الذي كان تحت حماية الصليبيين، إمبراطورًا مشاركًا مع أبيه إسحاق الثاني في آيا صوفيا في 1 أغسطس 1203. ولم يستطع الوفاء بما وعد به الصليبيين.", "88f53483"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1204-01-01:0":{"b": ["أثينا تقع في أيدي الصليبيين: أوتون دي لا روش يصبح سيد أثينا", "b38757d9"], "d": ["في حملة ماركيز مونفرات بونيفاس، صار البورغندي أوتون دي لا روش سيد أثينا في أواخر أكتوبر أو في نوفمبر 1204. وصارت أثينا جزءًا من اليونان اللاتينية بوصفها دوقية بورغندية (دوقية أثينا فيما بعد)؛ وحُوّل البارثينون إلى كاتدرائية كاثوليكية.", "47e8140e"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1204-01-01:1":{"b": ["إغريبوز تنتقل إلى اللاتين", "3ac87cb5"], "d": ["في حملة ماركيز مونفرات بونيفاس في خريف 1204، عبر الفرسان اللاتين من بيوتيا وأتيكا إلى جزيرة إغريبوز؛ وانقسمت الجزيرة في أول توزيع بين البنادقة والصليبيين.", "56fb0f97"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1204-01-01:2":{"b": ["غاليبولي تدخل في إدارة اللاتين", "e94882ae"], "d": ["بعد الحملة الصليبية الرابعة، دخلت غاليبولي سنة 1204 في إدارة اللاتين (البنادقة والإمبراطورية اللاتينية)؛ وسيستردها يوحنا فاتاتزس سنة 1235.", "1561323c"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1204-01-01:3":{"b": ["ميخائيل أنجيلوس يؤسس مستبدية إبيروس؛ ويانينا تصبح المركز", "053487d5"], "d": ["بعد الحملة الصليبية الرابعة، أسس ميخائيل كومنينوس دوكاس أنجيلوس، قريب إسحاق الثاني وألكسيوس الثالث، دولة يونانية مستقلة حول أرتا ويانينا، وهي مستبدية إبيروس التي ستعيش حتى سنة 1430. وبقي ميخائيل في البداية قائمًا بالاعتماد على الدبلوماسية مع البندقية والبابوية.", "738fe372"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1204-02-08:0":{"b": ["ألكسيوس الخامس مورتزوفلوس يعتلي العرش", "1a09c827"], "d": ["بانقلاب في القصر خُلع ألكسيوس الرابع وأبوه إسحاق الثاني، وصار مورتزوفلوس، صهر ألكسيوس الثالث، إمبراطورًا بلقب ألكسيوس الخامس. واعتبر الصليبيون ذلك تحديًا وقرروا اقتحام المدينة.", "a18f3330"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1204-04-13:0":{"b": ["الحملة الصليبية الرابعة تستولي على القسطنطينية", "684dcd71"], "d": ["بعد أسبوع من إيقاف الهجوم الأول في 6 أبريل، دخل الصليبيون والبنادقة القسطنطينية في 13 أبريل 1204؛ ونُهبت المدينة ثلاثة أيام ودُمّر نصفها بالحرائق. وتمزقت الإمبراطورية البيزنطية؛ وظهرت ثلاث دويلات بيزنطية في نيقية وطرابزون وإبيروس.", "0faa7103"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1204-05-16:0":{"b": ["كونت فلاندرز بلدوين يتوَّج: تأسيس الإمبراطورية اللاتينية", "39f062a5"], "d": ["توّج الصليبيون بعد ثمانية أيام من الانتخاب، في 16 مايو 1204، بلدوين كونت فلاندرز وإينو إمبراطورًا في آيا صوفيا. وعُيّن البندقي توما موروزيني بطريركًا لاتينيًّا، وقُسّمت أراضي الإمبراطورية بين الصليبيين والبنادقة.", "c1dcef9e"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1204-11-08:0":{"b": ["كالويان ينال تاج الملك من مندوب البابا في ترنوفو", "791d9635"], "d": ["بعد مفاوضات مع البابا إنوسنت الثالث، توّج مندوب البابا الكاردينال ليو كالويان ملكًا في ترنوفو في 8 نوفمبر 1204 بتاج جُلب من روما؛ وفي اليوم التالي رُسّم رئيس أساقفة ترنوفو «بريمات».", "2055a2ef"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1205-04-15:0":{"b": ["معركة أدرنة: كالويان يهزم الإمبراطور اللاتيني بلدوين ويأسره", "d320c946"], "d": ["خلال الثورات التي اندلعت بعد استيلاء اللاتين على القسطنطينية، هُزم الجيش اللاتيني أمام أدرنة هزيمة ساحقة على يد القوات البيزنطية البلغارية المشتركة؛ وأُسر الإمبراطور بلدوين وسيق إلى ترنوفو. وكانت هذه الهزيمة أول ضربة كبرى للإمبراطورية اللاتينية.", "1af0cda8"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1205-11-19:0":{"b": ["إمارة أخائية (المورة): غيوم دي شامبليت يُعرف بـ«أمير أخائية»", "ef90dab0"], "d": ["أسهم فتح جوفروا دي فيلاردوين وغيوم دي شامبليت للمورة (نصر كوندورا) في وقوع معظم اليونان في أيدي الصليبيين في مطلع 1205. وتذكر رسالة إنوسنت الثالث المؤرخة في 19 نوفمبر 1205 شامبليت بلقب «الأمير»؛ وهكذا تثبت وجود إمارة أخائية. وتولى فيلاردوين لقب الأمير قبل أواخر 1209.", "44588e3a"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1206-01-01:0":{"b": ["كالويان يهاجم ديموتيكا مرتين؛ الأسوار تنهار", "5a4dd23b"], "d": ["غزا الجيش البلغاري بقيادة القيصر كالويان تراقيا في مطلع 1206 وهاجم ديموتيكا مرتين؛ وفي الهجوم الثاني انهارت أسوار المدينة المحاصرة. وكان الدفاع قد أُوكل إلى الوحدات الرومية بقيادة ثيودور برانس.", "b00f7e1e"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1206-08-20:0":{"b": ["هنري الفلاندري يتوَّج إمبراطورًا لاتينيًّا", "ffd08538"], "d": ["توّج البطريرك اللاتيني الجديد توما موروزيني هنري، شقيق بلدوين الأسير ووصيّه، في آيا صوفيا في 20 أغسطس 1206. ويُعدّ هنري أكفأ حكام الإمبراطورية اللاتينية.", "350bed68"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1207-01-01:0":{"b": ["ماركو سانودو يؤسس دوقية ناكسوس (دوقية الأرخبيل)", "79faa9e1"], "d": ["نزل ماركو سانودو، ابن أخي دوج البندقية دندولو، مع جماعة من المغامرين في جزر بحر إيجه؛ واستسلمت سبع عشرة جزيرة بسهولة، وقاومت ناكسوس وحدها، وعاشت الدوقية التي أُسست فيها سنة 1207 أكثر من ثلاثة قرون. وقدّم سانودو ولاءه لا إلى البندقية بل إلى الإمبراطور اللاتيني هنري.", "02fd4630"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1207-10-08:0":{"b": ["وفاة كالويان أثناء حصار سالونيك", "d5427396"], "d": ["توفي القيصر البلغاري كالويان في 8 أكتوبر 1207 بصورة لم تتضح بعد، وهو يشن هجومًا جديدًا على سالونيك. وبهذا الموت انتهت الفترة العنيفة من الصراعات البلغارية اللاتينية؛ وانتقل عرش ترنوفو إلى بوريل.", "e6029330"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1210-06-20:0":{"b": ["ميخائيل مستبد إبيروس يرتبط بدوج البندقية", "669ad38d"], "d": ["وقّع ميخائيل دوكاس في 20 يونيو 1210، أمام تهديد الإمبراطور اللاتيني هنري، عقدًا مع الدوج بييترو زياني قبل بموجبه أن تترك له البندقية ولورثته إبيروس وأكارنانيا وأيتوليا؛ فحافظ بذلك على دولته بوصفه تابعًا للبندقية.", "5d11e9b1"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1216-06-11:0":{"b": ["وفاة الإمبراطور اللاتيني هنري في سالونيك", "929c3cd5"], "d": ["توفي الإمبراطور اللاتيني هنري فجأة في سالونيك في 11 يونيو 1216 قبل بلوغه الأربعين؛ وكان قد قوّى الإمبراطورية اللاتينية في عهده الذي دام عشر سنوات. وفي يوليو من السنة نفسها توفي البابا إنوسنت الثالث أيضًا؛ فخمدت ريح الحملة الصليبية الرابعة.", "6070f6e0"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1217-04-09:0":{"b": ["بيير دي كورتناي يتوَّج في روما إمبراطورًا لاتينيًّا", "f36d8586"], "d": ["توّج هونوريوس الثالث بيير دي كورتناي، الذي انتُخب بعد وفاة هنري، في روما في كنيسة القديس لورنزو في 9 أبريل 1217؛ وأقام البابا المراسم خارج أسوار المدينة لئلا يخلط بين لقبي إمبراطورية الشرق والغرب. ثم توجّه بالسفن البندقية إلى دورازو.", "98fb2727"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1221-03-25:0":{"b": ["روبير دي كورتناي يتوَّج في القسطنطينية", "932b6236"], "d": ["بعد وفاة الإمبراطورة يولاندا سنة 1219، انتقل العرش اللاتيني إلى ابنها الثاني روبير دي كورتناي؛ وتوّجه البطريرك اللاتيني الجديد ماثيو في القسطنطينية في 25 مارس 1221.", "bf2f3298"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1225-01-01:0":{"b": ["انتهاء مملكة سالونيك اللاتينية: سالونيك تنتقل إلى إبيروس", "1ae95078"], "d": ["سقطت مملكة سالونيك اللاتينية (1205-1225) التي أسسها بونيفاس حين استولى مستبد إبيروس ثيودور أنجيلوس على سالونيك واتخذ لقب «ملك الرومان وإمبراطورهم». وأسس ثيودور إمبراطورية سالونيك ودخل في منافسة مع نيقية على القسطنطينية.", "fe098325"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1228-01-01:0":{"b": ["إزميت تعود إلى السيادة البيزنطية (إمبراطورية نيقية)", "249950f8"], "d": ["انتقلت إزميت، التي تبادلتها بيزنطة واللاتين طويلًا، سنة 1228 إلى سيادة إمبراطورية نيقية.", "a051dabd"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1229-01-01:0":{"b": ["انتخاب جان دي بريين إمبراطورًا لاتينيًّا", "df313398"], "d": ["بعد وفاة روبير في المورة (1228) وكون بلدوين الثاني طفلًا، انتُخب جان دي بريين، ملك القدس السابق، إمبراطورًا في العام التالي. ودافع جان عن القسطنطينية ببطولة من الحصار البلغاري النيقي.", "2316312e"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1230-01-01:0":{"b": ["كلوكوتنيتسا: إيفان أسين الثاني يهزم مستبد إبيروس ثيودور ويأسره؛ ديموتيكا تدخل في السيادة البلغارية", "514365f5"], "d": ["في أبريل 1230 هزم القيصر البلغاري إيفان أسين الثاني ثيودور أنجيلوس وأسره في كلوكوتنيتسا على طريق أدرنة-فيلبه؛ وانكسرت قوة إمبراطورية سالونيك، وتوسعت بلغاريا في تراقيا ومقدونيا. وبقيت ديموتيكا بين 1230 و1246 تحت السيادة البلغارية.", "40e19d64"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1235-01-01:0":{"b": ["إعادة تأسيس البطريركية البلغارية", "2390176f"], "d": ["أُحييت البطريركية البلغارية من جديد سنة 1235.", "d24362c4"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1235-01-01:1":{"b": ["غاليبولي تنتقل إلى إمبراطور نيقية يوحنا الثالث", "3687c283"], "d": ["استعاد يوحنا (إمبراطور نيقية يوحنا الثالث فاتاتزس) سنة 1235 غاليبولي التي كانت بيد اللاتين منذ 1204.", "623f8bea"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1236-01-01:0":{"b": ["الجيشان الرومي والبلغاري يحاصران القسطنطينية؛ أمير المورة جوفروا الثاني ينقذها", "a07ee4a8"], "d": ["حاصر إيفان أسين ويوحنا فاتاتزس القسطنطينية من جديد سنة 1236؛ وكان اللاتين في آخر أنفاسهم، لكن أمير أخائية جوفروا الثاني دي فيلاردوين هرع من المورة وشارك في الدفاع عن المدينة، ورُفع الحصار.", "2c66c5d9"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1241-01-01:0":{"b": ["وفاة إيفان أسين الثاني: بداية تراجع بلغاريا", "1b1fa198"], "d": ["توفي القيصر البلغاري إيفان أسين الثاني سنة 1241؛ وفي السنة نفسها هاجم التتار البلاد، وضعفت الدولة البلغارية تدريجيًّا بسبب نزاعات البويار.", "6b44149b"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1246-01-01:0":{"b": ["ديموتيكا تدخل في إدارة بيزنطة (إمبراطورية نيقية)", "b0220eb0"], "d": ["دخلت ديموتيكا، التي كانت تحت السيادة البلغارية منذ 1230، سنة 1246 في إدارة بيزنطة بحملة يوحنا فاتاتزس على تراقيا.", "50e64103"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1246-01-01:1":{"b": ["سالونيك تنضم إلى إمبراطورية نيقية: انتهاء إمبراطورية سالونيك", "1f9b3c28"], "d": ["عبر يوحنا فاتاتزس سنة 1246 إلى تراقيا واستولى على الأراضي التي احتلها البلغار وعلى سالونيك؛ وسقطت دولة سالونيك التي أقامها يوحنا وديمتريوس ابنا ثيودور أنجيلوس، وعادت مقدونيا إلى السيادة البيزنطية/النيقية.", "26edc699"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1257-01-01:0":{"b": ["روستيسلاف يستولي على فيدين ويتخذ لقب قيصر البلغار", "19935b89"], "d": ["استولى روستيسلاف، ربيب ملك المجر، على فيدين سنة 1257 واتخذ لقب قيصر البلغار.", "9e6e94f4"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1259-01-01:0":{"b": ["معركة بيلاغونيا: ميخائيل باليولوغوس يهزم تحالف إبيروس وأخائية وصقلية", "eb3a201d"], "d": ["هزم ميخائيل الثامن الجيش المشترك لصقلية وإبيروس وأخائية وملوك الصرب في سهل بيلاغونيا (غرب مقدونيا)؛ وأُسر أمير أخائية غيوم دي فيلاردوين. ومهّد النصر لنهاية الإمبراطورية اللاتينية.", "18641aca"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1259-01-01:1":{"b": ["إعلان ميخائيل الثامن باليولوغوس إمبراطورًا في نيقية", "5875ecef"], "d": ["أُعلن ميخائيل باليولوغوس، وصيّ يوحنا الرابع لاسكاريس الصغير في إمبراطورية نيقية، إمبراطورًا مشاركًا في 1 يناير 1259؛ وبذلك بدأت الأسرة الباليولوغية (1259-1453).", "3627dde8"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1261-03-13:0":{"b": ["معاهدة نيمفايون: جنوة تعد بيزنطة بأسطول لاستعادة القسطنطينية", "a094d9f0"], "d": ["بموجب المعاهدة الموقعة بين ميخائيل الثامن وجنوة في نيمفايون في 13 مارس 1261، يرث التجار الجنويون امتيازات البندقية القديمة في حال استعادة القسطنطينية.", "6b7cc95c"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1261-07-25:0":{"b": ["قوات نيقية تستعيد القسطنطينية: انتهاء الإمبراطورية اللاتينية", "2c768188"], "d": ["دخلت قوات نيقية المدينة في 25 يوليو 1261 بعد أن أحرقت الحي اللاتيني على ساحل القرن الذهبي وفتحت الباب في السور من الداخل. وانتهى الحكم اللاتيني الذي دام سبعة وخمسين عامًا، وأُعيدت بيزنطة.", "a7d71b53"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1261-08-15:0":{"b": ["ميخائيل الثامن يتوَّج في آيا صوفيا", "ff8bdbd5"], "d": ["دخل ميخائيل الثامن المدينة من الباب الذهبي أمام أيقونة هوديجيتريا وسار في موكب، وتوّج في آيا صوفيا في 15 أغسطس 1261. وبقيت الأسرة الباليولوغية في الحكم حتى نهاية الإمبراطورية.", "8b4dbff9"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1265-01-01:0":{"b": ["ميخائيل الثامن يفرض على إبيروس قبول السيادة البيزنطية (يانينا)", "725f54aa"], "d": ["أخذ ميخائيل باليولوغوس سنة 1264 جزءًا من مقدونيا من البلغار، واستولى سنة 1265 على يانينا، فأجبر مستبدية إبيروس على قبول سيادة الإمبراطورية.", "3f3bbd15"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1267-05-24:0":{"b": ["فيلاردوين يربط إمارة أخائية بشارل دانجو (فيتربو)", "3c8a26a9"], "d": ["في فيتربو في 24 مايو 1267، وبموافقة الإمبراطور اللاتيني بلدوين الثاني، تنازل أمير أخائية غيوم دي فيلاردوين عن الإمارة لشارل دانجو ملك صقلية؛ على أن يبقى غيوم في الإمارة مدى الحياة، وتتزوج ابنته إيزابيلا من فيليب ابن شارل. وإن لم يولد وريث ذكر انتقلت الإمارة إلى أسرة أنجو في نابولي؛ وبذلك تُحمى المورة من الوقوع في يد باليولوغوس.", "124a7b0f"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1272-01-01:0":{"b": ["شارل دانجو يحتل دورازو وسواحل إبيروس", "64aaba29"], "d": ["احتل شارل دانجو كورفو سنة 1267 ودورازو وسواحل إبيروس سنة 1272؛ ثم اتفق مع الصرب والبلغار. وأجبر هذا التهديد ميخائيل الثامن على الاتحاد الكنسي مع البابوية.", "98ea3c00"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1272-01-01:1":{"b": ["انتهاء حكم ياكوف سفيتوسلاف تابع المجر في فيدين", "2cf90f4e"], "d": ["استولى الجيش المجري على فيدين في يونيو 1266 ودمّر المنطقة؛ وبقي ياكوف سفيتوسلاف، وهو من أصل روسي، في الحكم بلقب قيصر البلغار تابعًا للمجر حتى 1272، ثم ضعفت فيدين ولم تتعافَ زمنًا طويلًا.", "aeb24b65"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1274-07-06:0":{"b": ["مجمع ليون الثاني: بيزنطة تقبل سيادة البابا", "7603205f"], "d": ["بناء على إنذار البابا غريغوريوس العاشر، قبل اللوغوثيت الأكبر جورجيوس أكروبوليتس في ليون في 6 يوليو 1274 باسم الإمبراطور السيادة البابوية والعقيدة الرومانية. وانهار الاتحاد سنة 1281.", "879a4291"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1278-05-01:0":{"b": ["وفاة غيوم دي فيلاردوين: إمارة أخائية تنتقل إلى أسرة أنجو", "e4eac0d2"], "d": ["توفي أمير أخائية غيوم في 1 مايو 1278، وصارت الإمارة مباشرة لأسرة أنجو بموجب ترتيب فيتربو سنة 1267 (حتى 1289). وأضاف شارل دانجو أمير أخائية إلى ألقابه.", "f789577b"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1281-01-01:0":{"b": ["الجيش البيزنطي يفكّ حصار أنجو أمام برات", "745cab6e"], "d": ["حقق الجيش البيزنطي سنة 1281 أمام برات نصرًا على قوات أنجو.", "ccb74513"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1281-07-03:0":{"b": ["معاهدة أورفيتو: أنجو والبندقية والإمبراطور اللاتيني فيليب يتحالفون ضد بيزنطة", "b9000a4a"], "d": ["في ظل حماية البابا مارتن الرابع، عقد شارل دانجو في أورفيتو في 3 يوليو 1281 معاهدة تحالف ضد بيزنطة مع فيليب (ابن بلدوين الثاني) الذي يحمل لقب الإمبراطور اللاتيني ومع جمهورية البندقية. وأوقفت صلاة غروب صقلية (1282) هذه الخطة في منتصفها.", "fe224f07"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1281-11-18:0":{"b": ["البابا مارتن الرابع يحرم ميخائيل الثامن: انهيار اتحاد ليون", "c4569aff"], "d": ["حرم البابا الفرنسي مارتن الرابع، الذي انتُخب في 22 فبراير 1281، الإمبراطور ميخائيل الثامن باليولوغوس في 18 نوفمبر 1281 بتأثير من شارل دانجو؛ وبذلك انهار الاتحاد الكنسي في ليون.", "9a9b275d"]},
"OLAYLAR_ORTACAG_BIZANS_BALKAN:1333-01-01:0":{"b": ["جمهورية دوبروفنيك تشتري بيلييشاتس مع ستون من الملك الصربي دوشان", "702474c3"], "d": ["اشترت دوبروفنيك سنة 1333 شبه جزيرة بيلييشاتس مع ستون من الملك الصربي ستيفان دوشان؛ وصارت ستون ثاني مدينة للجمهورية في إنتاج الملح (المملحة).", "53d8f4b7"]},
"OLAYLAR_ORTACAG_BOZKIR:0567-01-01:0":{"b": ["إستمي يبغو يرسل وفدًا دبلوماسيًّا إلى بيزنطة: التحالف الغوك ترك - البيزنطي", "cef38140"], "d": ["أرسل إستمي يبغو، الذي ساءت علاقته بالساسانيين، وفدًا دبلوماسيًّا إلى القسطنطينية عام 567؛ وهذه أول سفارة أُرسلت من آسيا الوسطى إلى القسطنطينية. وأرسل البيزنطيون أيضًا سفيرًا إلى مركز إستمي يبغو؛ وأوقع التحالف الغوك ترك - البيزنطي الساسانيين في موقف صعب.", "ba370a65"]},
"OLAYLAR_ORTACAG_BOZKIR:0922-05-12:0":{"b": ["الوفد العباسي يصل إلى معسكر خان بلغار الفولغا؛ ألمش خان يعتنق الإسلام", "3416fffe"], "d": ["أرسل خان البلغار ألمش بن شلكي رسولًا إلى الخليفة المقتدر بالله يبلغه برغبته في الإسلام. ووصل الوفد برئاسة سوسن الرسي، الذي شارك فيه ابن فضلان، إلى معسكر الخان على ضفة الفولغا في 12 محرم 310 (12 أيار/مايو 922)؛ وبقبول الخان الرسمي للإسلام صارت دولة بلغار الفولغا دولة مسلمة تابعة للخلافة العباسية.", "2bb4aede"]},
"OLAYLAR_ORTACAG_BOZKIR:0965-01-01:0":{"b": ["بلغار الفولغا يتحررون من التفوق الخزري ويستقلون تمامًا", "6425140e"], "d": ["لما ضعفت الخاقانية الخزرية نتيجة ضربة ثقيلة تلقتها من غارات البشناق والقمان - القفجاق ومن الروس، نال بلغار الفولغا استقلالهم التام عام 965.", "be12b363"]},
"OLAYLAR_ORTACAG_BOZKIR:0985-01-01:0":{"b": ["إمارة كييف الروسية تقوم بحملة على بلاد بلغار الفولغا", "66c87db1"], "d": ["تعرضت بلاد بلغار الفولغا لغزو إمارة كييف الروسية مرتين، في عامي 964 و985؛ وأُبطلت مفعول هذه الهجمات.", "8c0bc16e"]},
"OLAYLAR_ORTACAG_BOZKIR:1006-01-01:0":{"b": ["توقيع اتفاقية تجارية بين إمارة كييف الروسية وبلغار الفولغا", "50c7bd31"], "d": ["وقّع البلدان اتفاقية تجارية عام 1006 بعد حملتي 964 و985.", "1050f8d0"]},
"OLAYLAR_ORTACAG_BOZKIR:1078-01-01:0":{"b": ["القفجاق يحاصرون أدرنة مع البشناق الثائرين", "b9fbc7ea"], "d": ["حاصر القفجاق عام 1078 أدرنة مع البشناق الذين ثاروا على بيزنطة؛ ثم شنوا غارات على بيزنطة في السنوات 1083-1096 و1109-1114.", "549cafaa"]},
"OLAYLAR_ORTACAG_BOZKIR:1209-01-01:0":{"b": ["إيديقوت الأويغور في قوتشو (تورفان) بارتشوق يتبع جنكيز خان", "b39f8607"], "d": ["تبعت دولة الأويغور في تورفان جنكيز خان عام 1209 واستمر وجودها تحت الإدارة المغولية حتى 1368؛ وخدم بارتشوق إيديقوت في جيش جنكيز، وتزوج عام 1211 من ابنة جنكيز آل خاتون. وكانت التبعية على هيئة خضوع طوعي.", "2225f854"]},
"OLAYLAR_ORTACAG_BOZKIR:1221-01-01:0":{"b": ["المغول يستولون على بلخ", "969bd4e3"], "d": ["انضم تولوي إلى جنكيز خان بعد أن استولى على هراة؛ وقضى جنكيز خان صيف 1220 في نخشب وفتح ترمذ، وفي السنة التالية (1221) عبر جيحون واستولى على بلخ.", "cdb8e36e"]},
"OLAYLAR_ORTACAG_BOZKIR:1221-01-01:1":{"b": ["المغول يستولون على كركانج (أورغنج)، عاصمة خوارزم", "a84fd33e"], "d": ["بعد حصار طويل قام به جغتاي وجوجي وأوكتاي، رُدمت الخنادق وأُشعلت النار في المدينة بالنفط؛ وقُتل الأهالي ما عدا الحرفيين، وقُتل الشيخ نجم الدين كبرى أيضًا. وأعطى جنكيز خان خوارزم وغرب سيبيريا لجوجي.", "039f9966"]},
"OLAYLAR_ORTACAG_BOZKIR:1221-01-01:2":{"b": ["أمير فلاديمير الأكبر يوري الثاني يبني قلعة نيجني نوفغورود", "0e58fe98"], "d": ["بنى الأمير الروسي يوري بن فسيفولود عام 1221 قلعة نيجني نوفغورود (غوركي) في إطار الضغط الروسي على أراضي بلغار الفولغا.", "bc937f4a"]},
"OLAYLAR_ORTACAG_BOZKIR:1238-01-01:0":{"b": ["المغول ينهبون موسكو", "81cdd316"], "d": ["نُهبت موسكو في شباط/فبراير 1238 بعد الاستيلاء على كثير من المدن في حملة باتو خان على الإمارات الروسية (أواخر 1237).", "f298f66e"]},
"OLAYLAR_ORTACAG_BOZKIR:1239-10-18:0":{"b": ["المغول ينهبون تشيرنيغوف", "a88faba3"], "d": ["نُهبت تشيرنيغوف (تُذكر في TDV باسم «Çernikov») عام 1239 في حملة باتو خان على روسيا.", "2fda24ee"]},
"OLAYLAR_ORTACAG_BOZKIR:1240-01-01:0":{"b": ["المغول يستولون على كييف ويخربونها", "812e4cf8"], "d": ["بعد تشتيت القفجاق، نزل المغول في كانون الأول/ديسمبر 1240 إلى سهوب أوكرانيا واستولوا على كييف، أكبر إمارة في المنطقة، وخربوها؛ ثم نهبت جيوش باتو بولندا والمجر والنمسا ودالماتيا.", "d5c24efa"]},
"OLAYLAR_ORTACAG_BOZKIR:1242-01-01:0":{"b": ["باتو خان يعود من حملته الغربية ويستقر في موطنه على الفولغا؛ تأسيس ساراي مركز القبيلة الذهبية", "48b498b4"], "d": ["عدّ باتو خان نبأ وفاة أوكتاي أمرًا بإنهاء الحملة، فعاد عام 1242 إلى موطنه عبر الأفلاق والبغدان، وأسس على الضفة اليسرى للفولغا عاصمته ساراي. وبذلك تأسست خانية القبيلة الذهبية، الجناح الغربي لأولوس جوجي.", "6e98d911"]},
"OLAYLAR_ORTACAG_BOZKIR:1252-08-24:0":{"b": ["طلائع كتبغا نويان تتحرك من قراقورم إلى الحملة الغربية", "b9a621af"], "d": ["كُلّف هولاكو بقرار المجلس (قوريلتاي) من منكو خان بالقضاء على الإسماعيلية وإخضاع الخلافة العباسية وفتح مصر وسوريا؛ وانطلقت طلائع كتبغا نويان في 24 آب/أغسطس 1252.", "84326f37"]},
"OLAYLAR_ORTACAG_BOZKIR:1253-04-24:0":{"b": ["هولاكو يتحرك من قراقورم في حملة إيران والشرق الأدنى", "62a1b34d"], "d": ["تحرك هولاكو من قراقورم في 24 نيسان/أبريل 1253 بعد طلائعه؛ وتحركت الطلائع في أيار/مايو 1253 على الإسماعيلية.", "e8fb31db"]},
"OLAYLAR_ORTACAG_BOZKIR:1256-11-19:0":{"b": ["زعيم الإسماعيلية ركن الدين خورشاه يسلّم ألموت إلى هولاكو", "848fbdb5"], "d": ["لم يستطع الإسماعيلية الصمود أمام المغول، فاستسلم رئيسهم في ألموت ركن الدين خورشاه لهولاكو في 19 تشرين الثاني/نوفمبر 1256؛ وسوّى هولاكو القلعة بالأرض وأعمل السيف في أهلها، وأخذ أوتشيغين نويان القلاع الإسماعيلية في سوريا.", "b5404ed4"]},
"OLAYLAR_ORTACAG_BOZKIR:1259-09-12:0":{"b": ["هولاكو يتحرك من تبريز في حملة سوريا", "ec15575b"], "d": ["تحرك هولاكو من تبريز في 12 أيلول/سبتمبر 1259 بعد أن أرسل طلائع كتبغا نويان أمامه؛ وسلمت الرها وحران وحماة وحمص ودمشق للمغول في وقت قصير، وحوصرت حلب وأُخذت.", "814ae379"]},
"OLAYLAR_ORTACAG_CIN:0577-01-17:0":{"b": ["جيش تشو الشمالية يصل إلى بينغتشو (تاييوان/جينيانغ)؛ حاكم تشي الشمالية يفر إلى يه", "46527e6b"], "d": ["وصل الجيش الكبير لإمبراطور تشو الشمالية وو إلى بينغتشو (جينيانغ، تاييوان الحالية)؛ فترك حاكم تشي الشمالية ابن عمه أمير آن دي يانزونغ للدفاع عن بينغتشو، وفر بفرسانه الخفاف إلى العاصمة يه.", "735dcdfa"]},
"OLAYLAR_ORTACAG_CIN:0581-03-04:0":{"b": ["يانغ جيان يعتلي العرش في قاعة لينغقوانغ: تأسيس أسرة سوي", "d5326ae1"], "d": ["بعد أن أصدر إمبراطور تشو الشمالية مرسوم التنازل عن العرش ليانغ جيان، دخل يانغ جيان القصر في عاصمة تشو وصار إمبراطورًا في قاعة لينغقوانغ؛ وغُيّر اسم العهد إلى كايهوانغ. وانتقلت منطقة تشانغآن من تشو الشمالية إلى سوي.", "37819dc2"]},
"OLAYLAR_ORTACAG_CIN:0605-04-10:0":{"b": ["يانغدي يأمر ببناء العاصمة الشرقية (دونغجينغ) في لويانغ", "cd3cf270"], "d": ["أمر يانغ قوانغ كلًّا من يانغ سو ويانغ دا ويوون كاي ببناء العاصمة الشرقية على نهري يي ولوه، وبتوطين أهل مدينة يوتشو فيها؛ فأُسست لويانغ عاصمةً ثانية.", "3e0738cc"]}
});
